const SHORT_DESC = "Станьте руководителем службы охраны труда за 256 часов. Дистанционный курс по Приказу 2464н с выдачей диплома о переподготовке. Обучение согласно профстандартам РФ.";
const FULL_DESC = "Программа профессиональной переподготовки разработана для подготовки квалифицированных управленцев, способных выстроить эффективную систему управления охраной труда на предприятии. В условиях ужесточения надзорной деятельности и регулярного обновления нормативной базы роль руководителя службы охраны труда становится стратегически важной для обеспечения комплексной безопасности производственных процессов и минимизации рисков административной и уголовной ответственности работодателя. Обучение в объеме 256 академических часов позволяет полностью освоить компетенции, необходимые для соответствия профессиональному стандарту и эффективного выполнения должностных обязанностей.\n\nКурс предназначен для специалистов по охране труда, планирующих карьерный рост, руководителей подразделений и главных инженеров, а также лиц с высшим образованием, желающих сменить сферу профессиональной деятельности. Программа актуальна для сотрудников организаций, чья деятельность требует обязательного наличия сертифицированной службы охраны труда согласно статье 217 Трудового кодекса РФ. Обучение также будет полезно индивидуальным предпринимателям и руководителям малого бизнеса, стремящимся самостоятельно контролировать соблюдение требований безопасности и оптимизировать бюджет на охрану труда.\n\nВ процессе обучения слушатели освоят методологию оценки и управления профессиональными рисками, научатся разрабатывать локальные нормативные акты и организовывать систему обучения персонала по новым правилам Постановления Правительства РФ №2464. Программа охватывает компетенции по планированию бюджета на мероприятия по ОТ, взаимодействию с государственными надзорными органами и проведению внутренних аудитов. Особое внимание уделяется алгоритмам расследования несчастных случаев на производстве и внедрению современных цифровых инструментов для автоматизации документооборота и мониторинга условий труда.\n\nПо окончании обучения выпускники получают диплом о профессиональной переподготовке установленного образца, дающий право на ведение нового вида профессиональной деятельности. Сведения о выданном документе в обязательном порядке вносятся в федеральный реестр ФИС ФРДО, что подтверждает легитимность квалификации при проверках ГИТ. Вместе с дипломом слушатели получают прикладной пакет шаблонов документов, необходимых для работы службы, включая инструкции, положения и графики проверок, полностью соответствующие актуальным требованиям Приказа Минтруда России.";

const LESSONS: Record<string, string> = {"64c09558-3c02-413e-a879-30d93d90db3c": "[{\"type\": \"heading1\", \"content\": \"Практическое задание: Разработка и актуализация Положения о системе управления охраной труда (СУОТ) предприятия\", \"id\": \"707319cd-b89f-4ff5-8172-c068e42d84eb\"}, {\"type\": \"paragraph\", \"content\": \"Данное практическое задание направлено на формирование навыков структурирования локальных нормативных актов в области охраны труда в соответствии с требованиями статьи 217 Трудового кодекса РФ и Приказа Минтруда России от 29.10.2021 № 776н. Слушателю предстоит проанализировать специфику деятельности условной организации и составить каркас ключевого документа, определяющего политику и процедуры безопасности на производстве.\", \"id\": \"e5e021b9-1651-4e3a-943a-a5d3a98f4d2b\"}, {\"type\": \"heading2\", \"content\": \"Постановка задачи (Ситуация)\", \"id\": \"bf6721cd-8928-4983-bb43-4401bb38a487\"}, {\"type\": \"paragraph\", \"content\": \"Вы назначены на должность специалиста по охране труда в ООО «Машиностроительный завод «Прогресс». На предприятии проведена реорганизация: в состав завода вошли два новых цеха (литейный и малярный), а также увеличилась штатная численность до 450 человек. Генеральный директор поставил задачу актуализировать Положение о СУОТ, так как текущий документ не обновлялся с 2018 года и не учитывает новые требования законодательства, а также специфику возросших рисков (химические факторы, термические воздействия). Ваша цель — подготовить проект обновленного Положения, распределив обязанности и определив процедуры управления профессиональными рисками.\", \"id\": \"1729fbd4-4c9d-4814-aaef-3acdf25e7ad2\"}, {\"type\": \"heading2\", \"content\": \"Исходные данные\", \"id\": \"3e07e461-6167-47e2-8d91-5ca7e82c7369\"}, {\"type\": \"list\", \"content\": [\"Организационно-правовая форма: Общество с ограниченной ответственностью (ООО).\", \"Штатная численность: 450 сотрудников (включая офисный персонал, рабочих цехов, водителей).\", \"Структурные подразделения: администрация, механический цех, литейный цех (новое), малярный цех (новое), складское хозяйство, транспортный отдел.\", \"Оборудование: плавильные печи, покрасочные камеры, фрезерные станки, вилочные погрузчики.\", \"Действующие локальные акты: устаревшее Положение о СУОТ, должностные инструкции, результаты последней СОУТ (выявлены классы условий труда 3.1 и 3.2).\"], \"id\": \"add59b3e-f298-4e1f-a299-efef5434bda7\"}, {\"type\": \"heading2\", \"content\": \"Вопросы для разбора и выполнения задания\", \"id\": \"7ff1e0b7-dd5b-4e28-9869-47c0712dc6ad\"}, {\"type\": \"list\", \"content\": [\"Какие обязательные разделы должны быть включены в Положение о СУОТ согласно Приказу Минтруда № 776н?\", \"Как распределяются обязанности по охране труда между генеральным директором, начальниками новых цехов и службой охраны труда?\", \"Какие процедуры должны быть описаны в разделе 'Управление профессиональными рисками' с учетом специфики литейного и малярного производств?\", \"Каков порядок участия работников в управлении охраной труда через работу профсоюза или уполномоченных лиц?\", \"Каким образом в Положении должна быть отражена процедура реагирования на аварийные ситуации и несчастные случаи?\", \"Каков порядок вступления в силу и пересмотра данного локального нормативного акта?\"], \"id\": \"927d51d8-5397-4253-9b18-1d6e6d97522a\"}, {\"type\": \"heading2\", \"content\": \"Методические указания\", \"id\": \"d0a99f3f-2b53-4079-8a3c-a56de3dd15da\"}, {\"type\": \"paragraph\", \"content\": \"При выполнении задания следует строго придерживаться структуры Примерного положения, утвержденного Приказом Минтруда № 776н. Важно помнить, что СУОТ — это цикличный процесс (Планируй - Делай - Проверяй - Корректируй). Особое внимание уделите разделу 'Обеспечение функционирования СУОТ' — здесь необходимо прописать распределение полномочий. Не копируйте текст приказа дословно: адаптируйте его под «Машиностроительный завод «Прогресс». Например, при описании рисков укажите конкретные опасности: 'ожоги расплавленным металлом' (литейный цех) или 'отравление парами растворителей' (малярный цех). Обратите внимание, что работодатель имеет право упрощать структуру для малого бизнеса, но для завода с численностью 450 человек этого делать не рекомендуется.\", \"id\": \"b41f811c-81f7-4e86-a34d-c4f2b5c491fc\"}, {\"type\": \"heading2\", \"content\": \"Образец решения / Эталонный ответ\", \"id\": \"6e5bcd11-c068-42f0-b430-ed39f77e4ae5\"}, {\"type\": \"quote\", \"content\": \"Структура проекта Положения о СУОТ ООО «МЗ «Прогресс»:\\n1. Общие положения (Цели, область действия).\\n2. Политика в области охраны труда (Приоритет жизни и здоровья).\\n3. Планирование (Цели на год: снижение травматизма на 10%).\\n4. Обеспечение функционирования СУОТ (Распределение обязанностей: Гендиректор обеспечивает финансирование; Начальники цехов — контроль применения СИЗ; Специалист по ОТ — методическую поддержку).\\n5. Функционирование (Процедуры: спецобучение, медосмотры, СОУТ, оценка рисков).\\n6. Контроль функционирования и анализ (Трехступенчатый контроль).\\n7. Улучшение (Порядок актуализации).\", \"id\": \"c37f14c8-8c46-4713-a4d3-1330f99277d9\"}, {\"type\": \"paragraph\", \"content\": \"В разделе управления рисками для новых цехов необходимо закрепить применение метода 'Контрольных листов' или 'Матричного метода' для идентификации опасностей. Ответственность за первичную идентификацию возлагается на начальников литейного и малярного цехов. Для снижения рисков в Положении прописывается процедура обеспечения работников современными средствами индивидуальной защиты (СИЗ), фильтрующими масками и спецодеждой с защитой от теплового излучения. Документ вводится в действие приказом генерального директора после согласования с выборным органом первичной профсоюзной организации.\", \"id\": \"4c5d36cd-e945-4e42-8e91-5a6090413e07\"}, {\"type\": \"heading2\", \"content\": \"Нормативно-правовые акты (НПА)\", \"id\": \"6e892d8e-c717-4d61-ade3-48425c779b65\"}, {\"type\": \"list\", \"content\": [\"Трудовой кодекс Российской Федерации (статьи 209, 212, 214, 217).\", \"Приказ Минтруда России от 29.10.2021 № 776н 'Об утверждении Примерного положения о системе управления охраной труда'.\", \"Приказ Минтруда России от 28.12.2021 № 926 'Об утверждении Рекомендаций по выбору методов оценки уровней профессиональных рисков и по снижению уровней таких рисков'.\", \"Приказ Минтруда России от 22.09.2021 № 650н 'Об утверждении примерного положения о комитете (комиссии) по охране труда'.\", \"Постановление Правительства РФ от 24.12.2021 № 2464 'О порядке обучения по охране труда и проверки знания требований охраны труда'.\"], \"id\": \"fa93a6b6-7fbb-458b-9c40-2b1b8f7c7a2c\"}, {\"type\": \"paragraph\", \"content\": \"Важно помнить, что отсутствие Положения о СУОТ или его несоответствие актуальному законодательству влечет административную ответственность по ч. 1 ст. 5.27.1 КоАП РФ (штраф на юридическое лицо до 80 000 рублей).\", \"id\": \"c1ba0d76-bdb3-4932-af8f-fb06c656f705\"}]", "7e72a4bc-4c1f-4309-b75e-27eafeed576f": "[{\"type\": \"heading1\", \"content\": \"Урок: Политика и цели организации в области охраны труда\", \"id\": \"b73dcc5d-adef-49ee-ab26-9142a89b038e\"}, {\"type\": \"paragraph\", \"content\": \"Политика в области охраны труда является фундаментом, на котором строится вся Система управления охраной труда (СУОТ) в современной организации. Это не просто формальный документ для проверки инспектора ГИТ, а стратегический манифест работодателя, декларирующий его намерения и обязательства по обеспечению безопасности работников. Согласно статье 214 Трудового кодекса РФ, создание и функционирование СУОТ является прямой обязанностью работодателя. Руководитель службы охраны труда выступает ключевым архитектором этого процесса, обеспечивая соответствие корпоративных принципов актуальному законодательству и специфике производственных процессов.\", \"id\": \"3d7e0812-c58e-46fb-9f7b-f2dfee775922\"}, {\"type\": \"heading2\", \"content\": \"Правовая основа и нормативные требования к Политике\", \"id\": \"bc1c954d-65f9-408d-9189-5f1bac909b61\"}, {\"type\": \"paragraph\", \"content\": \"Основным нормативным актом, регламентирующим структуру и содержание СУОТ, является Приказ Минтруда России от 29.10.2021 № 776н «Об утверждении Примерного положения о системе управления охраной труда». Данный документ устанавливает, что Политика должна быть публичной, доступной для всех работников и заинтересованных лиц. Она должна быть оформлена в виде локального нормативного акта, подписана первым лицом организации (генеральным директором) и, что крайне важно, согласована с представительным органом работников (при его наличии), как того требует статья 372 ТК РФ.\", \"id\": \"04e02cf9-a030-403d-8f6e-3df3f9b794a4\"}, {\"type\": \"quote\", \"content\": \"Политика (стратегия) в области охраны труда является публичным документальным декларативным заявлением работодателя о намерении и готовности соблюдать государственные нормативные требования охраны труда и добровольно принятые на себя обязательства. (Приказ Минтруда № 776н)\", \"id\": \"b919d42a-b996-4391-8e95-6750259f9d83\"}, {\"type\": \"heading2\", \"content\": \"Ключевые принципы формирования текста Политики\", \"id\": \"4bc85b61-7b08-4a78-abdf-a7edf89f1246\"}, {\"type\": \"paragraph\", \"content\": \"При разработке Политики руководитель службы ОТ должен руководствоваться принципами конкретики и выполнимости обязательств. Недопустимо копирование шаблонных фраз, не имеющих отношения к деятельности предприятия. Важно интегрировать вопросы техносферной безопасности в общую бизнес-стратегию. Политика должна быть лаконичной (обычно 1-2 страницы), написанной понятным языком, чтобы каждый рабочий — от слесаря до финансового директора — понимал свою роль в обеспечении безопасности.\", \"id\": \"f6590c02-9657-4b5b-8c06-f13e7df0a065\"}, {\"type\": \"list\", \"content\": \"Соответствие характеру и масштабам рисков организации\\nОбязательство по предотвращению травматизма и ухудшения здоровья работников\\nОбязательство по соблюдению применимых законодательных требований\\nПринцип непрерывного совершенствования системы управления\\nОбязательство по учету мнения работников и их участию в управлении ОТ\", \"id\": \"082df4bd-0389-4aa9-a3d0-32f009fe3703\"}, {\"type\": \"heading2\", \"content\": \"Цели в области охраны труда: от деклараций к действиям\", \"id\": \"6fcac581-ad49-43e3-ac4b-88499dfe9c6d\"}, {\"type\": \"paragraph\", \"content\": \"Если Политика — это общее направление движения, то цели — это конкретные вехи на этом пути. Согласно методологии SMART, цели в СУОТ должны быть конкретными, измеримыми, достижимыми, актуальными и ограниченными во времени. Приказ № 776н подчеркивает, что цели должны устанавливаться для каждого релевантного функционального направления и уровня управления. Например, цель «снизить травматизм» без указания цифр и сроков является нерабочей. Правильная формулировка: «Снизить частоту микроповреждений (микротравм) в цехе №3 на 15% к концу 2024 года за счет внедрения системы блокировки LOTO».\", \"id\": \"eee2f9e6-21c2-4cd7-8729-106b719a9480\"}, {\"type\": \"list\", \"content\": \"Совершенствование технического состояния оборудования для минимизации опасных факторов\\nПовышение качества обучения и инструктажей в соответствии с Постановлением Правительства РФ № 2464\\nЦифровизация процессов учета выдачи СИЗ и прохождения медосмотров\\nСнижение уровней профессиональных рисков на рабочих местах (по результатам СОУТ согласно ФЗ-426)\\nРазвитие культуры безопасности и «нулевого травматизма» (Vision Zero)\", \"id\": \"2f4ec94c-b3b0-4cff-9c29-8e73e628488b\"}, {\"type\": \"heading2\", \"content\": \"Связь Политики с оценкой профессиональных рисков\", \"id\": \"1551142d-1d6e-4172-ae2e-86f752ab64ca\"}, {\"type\": \"paragraph\", \"content\": \"Современная модель управления ОТ в РФ перешла от компенсационной к риск-ориентированной. Это означает, что Политика и цели должны напрямую базироваться на результатах идентификации опасностей. Если в организации по результатам оценки выявлен высокий риск падения с высоты, одна из приоритетных целей должна быть направлена на модернизацию систем обеспечения безопасности работ на высоте. Игнорирование результатов оценки рисков при постановке целей делает СУОТ формальной и неэффективной, что ведет к росту штрафных санкций при проверках.\", \"id\": \"7c7aa8f4-1834-4352-9fdf-8eac7ef74f5f\"}, {\"type\": \"heading2\", \"content\": \"Роль обучения в реализации Политики (ПП РФ № 2464)\", \"id\": \"14d35916-40eb-40fb-b2a3-58579ffa1deb\"}, {\"type\": \"paragraph\", \"content\": \"Реализация Политики невозможна без грамотного персонала. С 1 сентября 2022 года вступило в силу Постановление Правительства РФ № 2464 «О порядке обучения по охране труда и проверки знания требований охраны труда». Теперь обучение — это не просто лекции, а инструмент достижения целей безопасности. В Политику рекомендуется включить пункт о непрерывном развитии компетенций работников. Руководитель службы ОТ обязан выстроить систему так, чтобы программы обучения (включая оказание первой помощи и использование СИЗ) соответствовали актуальным рискам, изложенным в СУОТ.\", \"id\": \"ca7fa862-b256-4614-9b91-aedd7305d914\"}, {\"type\": \"heading2\", \"content\": \"Анализ и пересмотр Политики руководством\", \"id\": \"2edaaf2d-8083-4213-9827-196354b373ea\"}, {\"type\": \"paragraph\", \"content\": \"Политика не является статичным документом. Не реже одного раза в год (или при значительных изменениях в законодательстве, технологии, структуре компании) должен проводиться анализ со стороны руководства. Руководитель службы ОТ готовит отчет, в котором сопоставляет фактические показатели (статистика несчастных случаев, результаты производственного контроля, выполнение плана мероприятий) с заявленными целями. Если цели не достигнуты, это повод не для наказания, а для корректировки ресурсов или пересмотра самой стратегии управления.\", \"id\": \"84650ab5-f647-4fda-b57f-98d23e630d1d\"}, {\"type\": \"quote\", \"content\": \"Работодатель должен обеспечивать своевременный пересмотр целей в области охраны труда, чтобы они оставались актуальными и способствовали повышению результативности СУОТ. (ГОСТ Р ИСО 45001-2020)\", \"id\": \"362d240a-7de9-470c-b7fd-68359154d237\"}, {\"type\": \"heading2\", \"content\": \"Коммуникации и популяризация Политики\", \"id\": \"d808d6f4-3d63-425a-bd02-276b643a7d21\"}, {\"type\": \"paragraph\", \"content\": \"Для того чтобы Политика «заработала», она должна быть доведена до каждого сотрудника. Практика показывает, что простое ознакомление под роспись при приеме на работу недостаточно. Эффективные методы включают размещение текста на информационных стендах, экранах в местах отдыха, вкладыши в пропуска, публикацию на корпоративном портале. На ежесменных инструктажах и «минутках безопасности» руководители подразделений должны напоминать о целях организации. Это формирует психологическую установку: «безопасность — это ценность, а не обуза».\", \"id\": \"7949cd0c-1c0d-4635-9047-db35633ba9e1\"}, {\"type\": \"paragraph\", \"content\": \"В заключение следует отметить, что роль Руководителя службы охраны труда заключается в том, чтобы превратить Политику из декларативного текста в живой механизм управления. Четко сформулированные цели, подкрепленные бюджетом и человеческими ресурсами, позволяют не только соблюсти требования законодательства РФ (включая статьи 209-214 ТК РФ), но и реально сохранить жизнь и здоровье персонала, что является высшей ценностью любого социально ответственного бизнеса.\", \"id\": \"30cbcc15-32a1-4fb0-a2b2-0ab8449bb640\"}]", "94f2a396-694d-4198-9865-b114be05e87a": "[{\"type\": \"heading1\", \"content\": \"Методы выявления опасностей и оценки уровней профессиональных рисков\", \"id\": \"1948e4ee-0d6c-4f63-a4ae-13f2d919f451\"}, {\"type\": \"paragraph\", \"content\": \"В современной системе управления охраной труда (СУОТ) переход от списочного подхода к риск-ориентированному является фундаментальным изменением. Профессиональный риск — это вероятность причинения вреда здоровью в результате воздействия вредных или опасных производственных факторов при исполнении работником обязанностей по трудовому договору. Руководитель службы охраны труда должен четко понимать, что оценка рисков — это не разовая бумажная процедура, а непрерывный процесс, интегрированный в повседневную деятельность организации. Согласно статье 209.1 Трудового кодекса РФ, основными принципами обеспечения безопасности труда являются предупреждение и профилактика опасностей, а также минимизация повреждения здоровья работников.\", \"id\": \"6ccd80cf-49a0-4b5e-b0c6-c87d46044013\"}, {\"type\": \"quote\", \"content\": \"Работодатель обязан обеспечить систематическое выявление опасностей и профессиональных рисков, их регулярный анализ и оценку. (Статья 214 ТК РФ)\", \"id\": \"b98e318b-affd-4114-8b66-8cda36901269\"}, {\"type\": \"paragraph\", \"content\": \"Процесс управления рисками включает три основных этапа: идентификацию опасностей, оценку уровня риска и разработку мер по управлению ими. Идентификация — самый ответственный этап. Если опасность не выявлена, она не будет оценена, и меры защиты не будут приняты. Источниками информации для выявления опасностей служат результаты специальной оценки условий труда (СОУТ), проводимой в соответствии с ФЗ-426, статистические данные о травматизме, протоколы ступенчатого контроля, жалобы работников и техническая документация на оборудование.\", \"id\": \"430c8849-f0a7-4f0e-9f92-594dca8b51e4\"}, {\"type\": \"heading2\", \"content\": \"Классификация методов оценки профессиональных рисков\", \"id\": \"86d9ebe2-130e-45f5-8d46-689f0c0e7997\"}, {\"type\": \"paragraph\", \"content\": \"При выборе методологии оценки руководитель службы ОТ должен руководствоваться Приказом Минтруда России от 28.12.2021 № 796 «Об утверждении Рекомендаций по выбору методов оценки уровней профессиональных рисков и по их снижению». Законодательство не навязывает конкретный метод, позволяя адаптировать инструментарий под специфику бизнеса — от малого предприятия до крупного промышленного холдинга. Все методы делятся на качественные (основанные на экспертных оценках), количественные (оперирующие вероятностными расчетами) и смешанные (полуколичественные).\", \"id\": \"74a1f519-367e-40c8-9802-1ec4ea447f14\"}, {\"type\": \"list\", \"content\": \"Метод «Контрольных листков» (Чек-листы) — наиболее простой способ для малых предприятий.\\nМатричный метод (Метод Файна-Кинни и его модификации) — самый распространенный инструмент в РФ.\\nМетод «Что если?» (What-if?) — творческий метод для анализа нестандартных ситуаций.\\nАнализ дерево отказов (FTA) — для объектов повышенной опасности.\\nМетод HAZOP (исследование опасности и работоспособности) — для сложных технологических процессов.\", \"id\": \"e08f1a0b-e549-4997-8e15-174efd6db64b\"}, {\"type\": \"heading2\", \"content\": \"Матричный метод: практическое применение\", \"id\": \"0e22ceb0-d5a1-46d2-8830-2fb154582d64\"}, {\"type\": \"paragraph\", \"content\": \"Матричный метод основан на определении двух параметров: тяжести последствий (ущерба) и вероятности реализации опасного события. Уровень риска определяется как произведение этих величин. Руководитель службы ОТ формирует шкалы (например, от 1 до 5), где 1 — незначительный ущерб (микротравма), а 5 — катастрофические последствия (групповой несчастный случай со смертельным исходом). Аналогично градируется вероятность. Итоговая матрица позволяет визуализировать риски по зонам: допустимые (зеленая зона), средние (желтая) и недопустимые (красная). Основным преимуществом является наглядность и легкость объяснения результатов линейным руководителям.\", \"id\": \"ec514e61-32e2-41a9-b763-7c78a84ec497\"}, {\"type\": \"quote\", \"content\": \"При оценке уровней профессиональных рисков должны учитываться не только штатные условия эксплуатации, но и возможные отклонения в работе, включая аварийные ситуации. (ГОСТ Р 12.0.010-2009)\", \"id\": \"77211539-3f80-4d55-abe4-dc9028fee35c\"}, {\"type\": \"heading2\", \"content\": \"Связь оценки рисков с обучением и СИЗ\", \"id\": \"03bb4b50-10fb-4414-8418-b2b0291b8806\"}, {\"type\": \"paragraph\", \"content\": \"Согласно Постановлению Правительства РФ № 2464, результаты оценки рисков напрямую влияют на содержание программ обучения по охране труда. Работодатель обязан включать в программы обучения вопросы, связанные с выявленными опасностями на конкретном рабочем месте. Более того, с 1 сентября 2023 года нормы выдачи средств индивидуальной защиты (СИЗ) переходят на Единые типовые нормы (ЕТН), которые базируются не на отраслевой принадлежности, а именно на выявленных опасностях. Если риск не зафиксирован в картах оценки, обосновать выдачу соответствующего СИЗ перед налоговой или инспекцией труда будет невозможно.\", \"id\": \"4b1ff130-6bbe-418f-9d01-8739c8dfb748\"}, {\"type\": \"paragraph\", \"content\": \"Важно учитывать требования Приказа Минтруда № 776н об утверждении Примерного положения о СУОТ. В нем акцентируется внимание на том, что процедура оценки рисков должна быть цикличной. Повторная оценка проводится при вводе нового оборудования, изменении технологического процесса, после несчастных случаев или по результатам государственного надзора. Руководитель службы охраны труда координирует работу комиссии, в которую обязательно должны входить представители профсоюза и специалисты, непосредственно эксплуатирующие оборудование.\", \"id\": \"47c80bee-eba2-4c0b-8111-a989ac99b27e\"}, {\"type\": \"heading2\", \"content\": \"Алгоритм выявления опасностей на рабочем месте\", \"id\": \"51c8f997-0474-4d1b-93ed-3778b636d9c9\"}, {\"type\": \"list\", \"content\": \"Шаг 1. Предварительный анализ: сбор карт СОУТ, журналов ТО, данных о профзаболеваниях.\\nШаг 2. Обход рабочих мест: наблюдение за выполнением работ, интервью с работниками.\\nШаг 3. Составление реестра опасностей: группировка по видам (механические, электрические, климатические и т.д.).\\nШаг 4. Определение возможных последствий для каждой опасности.\\nШаг 5. Оформление карт оценки рисков и ознакомление с ними работников под роспись.\", \"id\": \"05b07fb8-dd18-4d56-b69c-ed8486f1e100\"}, {\"type\": \"paragraph\", \"content\": \"Типичной ошибкой при выявлении опасностей является игнорирование «скрытых» или поведенческих факторов. Часто эксперты фиксируют только физические факторы (шум, вибрация), забывая о рисках, связанных с эргономикой, монотонностью труда или психологическим давлением. Для руководителя службы ОТ важно обеспечить междисциплинарный подход, привлекая технологов и медиков. Использование положений Приказа Минтруда № 36н поможет правильно классифицировать опасности по категориям: нахождения в зонах повышенных температур, падения с высоты, воздействия движущихся частей машин.\", \"id\": \"ccef7120-0458-4bfa-ae2d-90a6667b1b13\"}, {\"type\": \"heading2\", \"content\": \"Управление рисками и иерархия мер контроля\", \"id\": \"261f0350-d786-4afd-ba5d-2e493f7177d8\"}, {\"type\": \"paragraph\", \"content\": \"После того как риски оценены, необходимо разработать План мероприятий по управлению рисками. Здесь применяется международно признанная иерархия мер, закрепленная в российских стандартах ССБТ. Приоритетом является полное устранение опасности (например, замена опасного химического вещества на безопасное). Если это невозможно, применяются инженерно-технические меры (ограждения, блокировки), затем административные (инструктажи, знаки безопасности) и в последнюю очередь — использование СИЗ. Руководитель службы охраны труда должен следить за тем, чтобы бюджет предприятия распределялся эффективно, отдавая приоритет мерам коллективной защиты.\", \"id\": \"bbff7e9b-7cd5-4565-8c70-c794caa59cde\"}, {\"type\": \"quote\", \"content\": \"Результаты оценки профессиональных рисков являются основой для планирования всех мероприятий по охране труда в организации. (Приказ Минтруда № 776н)\", \"id\": \"9fb365ed-8e20-4e10-9dc9-def47e474c22\"}, {\"type\": \"paragraph\", \"content\": \"В заключение следует отметить, что ведение Реестра опасностей и Карт оценки рисков в электронном виде становится стандартом де-факто для крупных компаний. Это позволяет оперативно вносить изменения и интегрировать данные в общекорпоративные системы управления ресурсами (ERP). Для руководителя службы ОТ это также инструмент обоснования затрат перед топ-менеджментом: переводя риски в финансовые показатели возможных потерь от простоев и штрафов, можно гораздо эффективнее защищать бюджет на мероприятия по безопасности.\", \"id\": \"13d1cbc4-551b-4992-86db-b39227089df1\"}]", "f9260670-720e-4070-b9fe-143453be710d": "[{\"type\": \"heading1\", \"content\": \"Разработка локальных нормативных актов и документации СУОТ\", \"id\": \"a58625de-562d-43a7-9725-b268812b3eb0\"}, {\"type\": \"paragraph\", \"content\": \"Система управления охраной труда (СУОТ) представляет собой комплекс взаимосвязанных и взаимодействующих между собой элементов, устанавливающих политику и цели в области охраны труда у конкретного работодателя и процедуры по достижению этих целей. Ключевая роль руководителя службы охраны труда на этапе создания СУОТ заключается в формировании стройной системы локальных нормативных актов (ЛНА), которые должны не только соответствовать государственным нормативным требованиям, но и реально функционировать, обеспечивая безопасность производственных процессов. Согласно статье 214 ТК РФ, работодатель обязан обеспечить создание и функционирование системы управления охраной труда, что делает разработку документации не формальной задачей, а прямой юридической обязанностью организации.\", \"id\": \"f91b81d1-4091-4a63-bbd6-0d1a42741c67\"}, {\"type\": \"heading2\", \"content\": \"Нормативная база для разработки документации СУОТ\", \"id\": \"2288734b-97a1-48ef-a308-23c26247080b\"}, {\"type\": \"paragraph\", \"content\": \"При проектировании документарной базы СУОТ руководителю службы охраны труда необходимо опираться на иерархию нормативных правовых актов. Основополагающим документом является Трудовой кодекс РФ (раздел X). Детализация требований к СУОТ приведена в Приказе Минтруда России от 29.10.2021 № 776н «Об утверждении Примерного положения о системе управления охраной труда». Этот документ заменил старый типовой порядок и ввел модульный принцип построения системы, позволяющий адаптировать структуру документации под специфику бизнеса. Также критически важными являются Постановление Правительства РФ от 24.12.2021 № 2464 по обучению, Федеральный закон от 28.12.2013 № 426-ФЗ «О специальной оценке условий труда» и Приказ Минтруда от 29.10.2021 № 773н, устанавливающий требования к информированию работников об их правах и условиях труда.\", \"id\": \"f011af0c-1cd4-47e4-b348-04d069d3906a\"}, {\"type\": \"quote\", \"content\": \"Статья 217 ТК РФ: Система управления охраной труда — это комплекс взаимосвязанных и взаимодействующих между собой элементов, устанавливающих политику и цели в области охраны труда у конкретного работодателя и процедуры по достижению этих целей. Работодатель обязан обеспечить создание и функционирование системы управления охраной труда.\", \"id\": \"a0233745-f862-4f1b-ac66-467a5b689ec0\"}, {\"type\": \"heading2\", \"content\": \"Структура и перечень основных локальных нормативных актов\", \"id\": \"416910fd-0c99-48ff-b88e-fa0ab6bdc5ec\"}, {\"type\": \"paragraph\", \"content\": \"Полный пакет документации СУОТ можно разделить на три уровня. Первый уровень — стратегический (Политика и Цели). Второй уровень — управленческий (Положение о СУОТ, стандарты предприятия, регламенты взаимодействия между подразделениями). Третий уровень — операционный (инструкции по охране труда, программы инструктажей, журналы, графики). Важно понимать, что Положение о СУОТ является «конституцией» безопасности в организации, закрепляющей распределение обязанностей по охране труда не только за специалистами УОТ, но и за всеми руководителями среднего звена и функциональными директорами.\", \"id\": \"4a268167-4bc7-407b-9925-f6bea27125de\"}, {\"type\": \"list\", \"content\": \"Положение о системе управления охраной труда (базовый документ)\\nПолитика работодателя в области охраны труда (декларация намерений)\\nПриказ о распределении обязанностей и ответственности в рамках СУОТ\\nПоложение (порядок) проведения оценки профессиональных рисков\\nПеречень инструкций по охране труда по профессиям и видам работ\\nПрограммы проведения инструктажей (вводного и на рабочем месте)\\nПоложение о порядке обучения и проверки знаний (в соответствии с ПП РФ № 2464)\\nГрафики проведения медицинских осмотров и психиатрических освидетельствований\", \"id\": \"01fecb32-3104-455e-b081-4c0f0a762f98\"}, {\"type\": \"heading2\", \"content\": \"Процедура управления профессиональными рисками как ядро СУОТ\", \"id\": \"33753fa9-0d06-4b09-86ae-17e139c53ad2\"}, {\"type\": \"paragraph\", \"content\": \"Современная модель управления охраной труда в РФ перешла от компенсаторной модели к рискоориентированному подходу. Разработка ЛНА по оценке рисков — это наиболее сложный этап для руководителя службы. Необходимо разработать Положение об оценке рисков, в котором будет зафиксирована выбранная методика (например, по ГОСТ Р 12.0.010-2009). Документация по рискам должна включать реестр опасностей, карты оценки рисков и план мероприятий по снижению их уровней. Без легитимной базы по оценке рисков работодатель не сможет корректно обосновать выдачу СИЗ по единым типовым нормам (ЕТН) или установление режимов труда и отдыха.\", \"id\": \"6b464859-d762-4e02-b7c8-77aa35480923\"}, {\"type\": \"heading2\", \"content\": \"Организация обучения в рамках СУОТ по новым правилам\", \"id\": \"469e1566-86f3-4311-881e-19e726b9701e\"}, {\"type\": \"paragraph\", \"content\": \"С вступлением в силу Постановления Правительства РФ № 2464 «О порядке обучения по охране труда и проверки знания требований охраны труда», документация в этой сфере претерпела радикальные изменения. Теперь руководитель службы охраны труда должен обеспечить наличие пяти различных программ обучения (если применимо к типам работ). Особое внимание в локальных актах следует уделить процедуре регистрации инструктажей: допускается использование личных листков, журналов или электронного документооборота, если это закреплено в ЛНА. Также необходимо утвердить перечень должностей, освобожденных от инструктажа на рабочем месте, и перечень лиц, подлежащих обучению в сторонних учебных центрах.\", \"id\": \"a3f8b887-fe5e-4a96-9165-16d7e3c5b809\"}, {\"type\": \"list\", \"content\": \"Программа обучения по оказанию первой помощи пострадавшим\\nПрограмма обучения по использованию (применению) СИЗ\\nПрограмма обучения безопасным методам и приемам выполнения работ при воздействии вредных факторов\\nПрограмма обучения безопасным методам и приемам выполнения работ повышенной опасности\\nПеречень лиц, ответственных за проведение инструктажей и обучение\", \"id\": \"30c3ae7d-e4bd-4666-a17a-b6d448a63127\"}, {\"type\": \"heading2\", \"content\": \"Документирование системы обеспечения СИЗ\", \"id\": \"2dc1c506-7da7-438b-a190-af45d0f2b935\"}, {\"type\": \"paragraph\", \"content\": \"Переход на Единые типовые нормы (ЕТН) требует разработки Порядка обеспечения работников СИЗ и смывающими средствами. Этот локальный акт должен определять правила выбора СИЗ на основе данных СОУТ и оценки рисков, порядок их выдачи, хранения, стирки и утилизации. Руководитель службы ОТ должен утвердить Нормы выдачи СИЗ конкретно для своей организации, основываясь на Приказе Минтруда № 767н и Приказе № 766н. Отсутствие утвержденных норм или несоответствие их результатам оценки рисков является прямым нарушением, влекущим штрафы по ст. 5.27.1 КоАП РФ.\", \"id\": \"252807f8-bdd8-4e89-932d-633299f7e4c9\"}, {\"type\": \"heading2\", \"content\": \"Обеспечение инклюзивности и участия работников\", \"id\": \"e65828b7-0c55-41d1-8a28-080991480b34\"}, {\"type\": \"paragraph\", \"content\": \"Важным элементом СУОТ является документирование участия работников в управлении охраной труда. Для этого разрабатывается Положение о комитете (комиссии) по охране труда и Положение об уполномоченных (доверенных) лицах по охране труда от профсоюза. Эти ЛНА позволяют легализовать процесс проведения взаимных проверок, трехступенчатого контроля и оперативного учета предложений работников по улучшению условий труда. Коллективный договор также может содержать раздел по охране труда, который является значимым ЛНА, влияющим на социальный климат и юридическую защищенность работодателя.\", \"id\": \"36b02ae0-c00c-44f8-b6b4-bcb13487674b\"}, {\"type\": \"heading2\", \"content\": \"Порядок пересмотра и актуализации документации\", \"id\": \"dde483d0-f1e3-433a-8af1-02470d312399\"}, {\"type\": \"paragraph\", \"content\": \"Локальные нормативные акты не являются статичными документами. Согласно требованиям Приказа № 776н, работодатель обязан регулярно проводить оценку эффективности СУОТ. Это подразумевает ежегодный аудит документации. Руководитель службы ОТ должен издать приказ о сроках пересмотра инструкций по охране труда (теперь жесткий срок в 5 лет отменен, пересмотр осуществляется при изменении условий труда, НПА или оборудования). Система документооборота должна обеспечивать своевременное ознакомление работников со всеми изменениями под подпись, в том числе через системы ЭДО (электронного документооборота), что разрешено статьями 22.1-22.3 ТК РФ.\", \"id\": \"0c7804a1-d1ce-4261-bbaf-463e2a19a63f\"}, {\"type\": \"list\", \"content\": \"Анализ изменений в федеральном законодательстве (ежеквартально)\\nПроверка актуальности ссылок на НПА в действующих инструкциях\\nИнвентаризация реестра опасностей и корректировка карт рисков\\nАктуализация списков работников на медосмотры и обучение\\nВнесение изменений в Положение о СУОТ по результатам внутренних аудитов\", \"id\": \"e6586a18-8fbd-4998-bd34-83d33ac7e8c9\"}, {\"type\": \"heading1\", \"content\": \"Заключение для руководителя службы\", \"id\": \"ac10b869-2c4b-4211-8914-635e51b0611e\"}, {\"type\": \"paragraph\", \"content\": \"Правильно выстроенная система документации СУОТ — это главный инструмент защиты руководителя службы охраны труда и директора организации при проверках ГИТ или несчастных случаях. Она должна представлять собой бесшовный механизм, где данные СОУТ перетекают в оценку рисков, оценка рисков — в программы обучения и нормы выдачи СИЗ, а обучение завершается допуском к самостоятельной работе. Качество разработки ЛНА определяет не только отсутствие штрафов, но и реальное снижение производственного травматизма, что и является главной целью профессиональной деятельности руководителя службы охраны труда.\", \"id\": \"7f2a397e-2d11-47a2-933b-a14f7a9c54ec\"}]", "68933350-773f-476a-9e28-59ddb22f433e": "[{\"type\": \"heading1\", \"content\": \"Государственный надзор и контроль за соблюдением трудового законодательства в Российской Федерации\", \"id\": \"14bac094-1bdd-4edf-806c-7a6424ad68ec\"}, {\"type\": \"paragraph\", \"content\": \"Государственный надзор и контроль за соблюдением трудового законодательства представляет собой целостную систему мер, направленных на предупреждение, обнаружение и пресечение нарушений прав работников, а также на обеспечение безопасных условий труда. Роль руководителя службы охраны труда (СОТ) в этой системе является ключевой, так как именно он выступает связующим звеном между работодателем и проверяющими органами. Понимание структуры надзора, полномочий инспекторов и порядка проведения проверок позволяет руководителю СОТ выстроить эффективную систему внутреннего контроля и минимизировать риски административной и уголовной ответственности предприятия.\", \"id\": \"ad940906-543f-48bf-b666-dda8a5e6a3d6\"}, {\"type\": \"heading2\", \"content\": \"Правовые основы и структура надзорных органов\", \"id\": \"52863def-55d4-4c3b-b8eb-432585c0fba0\"}, {\"type\": \"paragraph\", \"content\": \"Основным нормативным правовым актом, регламентирующим данную сферу, является Трудовой кодекс Российской Федерации (ТК РФ), в частности Глава 57. Также деятельность инспекционных органов жестко регламентирована Федеральным законом № 248-ФЗ «О государственном контроле (надзоре) и муниципальном контроле в Российской Федерации». Ключевым органом, осуществляющим федеральный государственный контроль (надзор) за соблюдением трудового законодательства, является Федеральная служба по труду и занятости (Роструд) и её территориальные органы — Государственные инспекции труда (ГИТ).\", \"id\": \"cd334ddd-85d1-4411-90ff-2cb7e9a92d79\"}, {\"type\": \"quote\", \"content\": \"Согласно ст. 353 ТК РФ, федеральный государственный контроль (надзор) за соблюдением трудового законодательства и иных нормативных правовых актов, содержащих нормы трудового права, осуществляется федеральной инспекцией труда.\", \"id\": \"925262e1-6418-432d-aadf-35988d574012\"}, {\"type\": \"paragraph\", \"content\": \"Помимо ГИТ, в систему надзора включены специализированные органы. За радиационной безопасностью следит Ростехнадзор, за соблюдением санитарно-эпидемиологических норм на рабочих местах — Роспотребнадзор. Генеральная прокуратура РФ осуществляет высший надзор за единообразным исполнением законов всеми ведомствами и работодателями. Важно понимать, что современная модель надзора перешла от карательной функции к риск-ориентированному подходу, что закреплено в Постановлении Правительства РФ от 21.07.2021 № 1230.\", \"id\": \"e5040e4c-1834-4b84-9d02-d1f886e4a8af\"}, {\"type\": \"heading2\", \"content\": \"Риск-ориентированный подход и категории риска\", \"id\": \"b8623d34-19fd-4a0d-8998-5479e3816890\"}, {\"type\": \"paragraph\", \"content\": \"Внедрение риск-ориентированного подхода означает, что интенсивность контрольных мероприятий напрямую зависит от того, к какой категории риска отнесена деятельность работодателя. Всего выделяют пять категорий риска: высокий, значительный, средний, умеренный и низкий. От этой классификации зависит частота проведения плановых проверок. Например, для объектов высокого риска плановая проверка проводится один раз в 2 года, а для низкого риска плановые проверки не проводятся вовсе. Руководитель СОТ должен уметь самостоятельно рассчитывать категорию риска организации, используя ведомственные методики Роструда, чтобы прогнозировать надзорную нагрузку.\", \"id\": \"9cd16c0d-8ef4-49cd-9706-c8a549814e6e\"}, {\"type\": \"list\", \"content\": \"Критерии отнесения к категории риска:\\nПоказатель травматизма в организации за предыдущие три года\\nНаличие задолженности по заработной плате\\nНаличие факт административных наказаний за нарушения требований охраны труда\\nВид экономической деятельности (ОКВЭД) организации\\nРезультаты специальной оценки условий труда (СОУТ)\", \"id\": \"dfb3efb1-01f0-4154-94cd-61b02b2f7c92\"}, {\"type\": \"heading2\", \"content\": \"Виды контрольных мероприятий и полномочия инспекторов\", \"id\": \"83b6aa27-05ea-4907-a516-3bdb8b02bbac\"}, {\"type\": \"paragraph\", \"content\": \"Современное законодательство (ФЗ-248) выделяет различные виды контрольных (надзорных) мероприятий: инспекционный визит, рейдовый осмотр, документарная проверка и выездная проверка. Инспекционный визит является краткосрочным мероприятием (не более 1 рабочего дня) и не предполагает детального изучения всей документации. Выездная проверка — наиболее глубокое мероприятие, в ходе которого проверяется соответствие зданий, сооружений, оборудования и рабочих процессов требованиям охраны труда, включая исполнение Постановления Правительства РФ № 2464 по обучению персонала и ФЗ № 426 «О специальной оценке условий труда».\", \"id\": \"028a0c5d-9855-41cc-a940-33e9a541ad69\"}, {\"type\": \"paragraph\", \"content\": \"Инспекторы труда имеют широкие полномочия: они вправе беспрепятственно посещать организации в любое время суток (при наличии удостоверения и распоряжения), запрашивать любые документы, касающиеся трудовых отношений и охраны труда, изымать образцы материалов для анализа, а также выдавать предписания, обязательные для исполнения. За неисполнение законных требований инспектора предусмотрена ответственность по статье 19.5 КоАП РФ. Однако руководитель СОТ должен следить, чтобы инспектор не выходил за рамки предмета проверки, указанного в распоряжении (решении) о проведении КНМ.\", \"id\": \"57630aa2-c542-41b4-9f48-d39053d07567\"}, {\"type\": \"heading2\", \"content\": \"Профилактические мероприятия как новый приоритет\", \"id\": \"43f4d630-2f40-45db-a178-6f30f953eeda\"}, {\"type\": \"paragraph\", \"content\": \"В актуальной редакции законодательства профилактика нарушений стоит выше их пресечения. Одним из важнейших инструментов стал профилактический визит. В отличие от проверки, профилактический визит не заканчивается штрафами или предписаниями. Это консультационная помощь работодателю. Если в ходе профилактического визита выявлены нарушения, инспектор лишь дает рекомендации по их устранению. Для руководителя службы охраны труда инициирование добровольного профилактического визита — это отличный способ провести внешний аудит системы управления охраной труда (СУОТ) без бюджетных потерь.\", \"id\": \"3feba439-c9dd-452a-968a-7b215bfa2869\"}, {\"type\": \"list\", \"content\": \"Другие формы профилактики включают:\\nИнформирование через СМИ и официальные сайты\\nОбобщение правоприменительной практики\\nОбъявление предостережения о недопустимости нарушения обязательных требований\\nСамообследование (использование чек-листов на портале Онлайнинспекция.рф)\", \"id\": \"2fdf9cbf-7f4c-45c4-876b-58ed7bea352f\"}, {\"type\": \"heading2\", \"content\": \"Обязательные требования: фокус внимания надзора\", \"id\": \"cb61f5cf-3057-4193-ae00-cd1685ed331b\"}, {\"type\": \"paragraph\", \"content\": \"При проведении государственного надзора особое внимание уделяется исполнению ключевых институтов охраны труда. Первое — это проведение СОУТ в соответствии с ФЗ-426. Инспекторы проверяют наличие карт СОУТ, ознакомление работников с результатами и предоставление гарантий и компенсаций. Второе — организация обучения по охране труда согласно Приказу Минтруда № 2464н. Теперь инспекторы сверяют данные в реестре Минтруда с внутренними протоколами организации. Отсутствие записи в федеральном реестре об обученном сотруднике приравнивается к допуску к работе без обучения.\", \"id\": \"f5997791-8cff-4492-bc22-61b6f5cfe247\"}, {\"type\": \"quote\", \"content\": \"Статья 5.27.1 КоАП РФ предусматривает штрафы до 80 000 рублей на юридическое лицо за отсутствие СОУТ и до 130 000 рублей за допуск работника без обучения или медицинского осмотра.\", \"id\": \"25689a38-3ba8-4ab6-bfb4-f53be11ef4fd\"}, {\"type\": \"paragraph\", \"content\": \"Также под пристальным вниманием находится обеспечение работников средствами индивидуальной защиты (СИЗ) по Единым типовым нормам (ЕТН). С 2024 года переход на ЕТН становится обязательным для всех, и надзорные органы будут жестко контролировать наличие личных карточек учета выдачи СИЗ (в том числе в электронном виде) и соответствие выдаваемых изделий классу защиты и условиям труда. При выявлении фактов сокрытия несчастных случаев на производстве материалы незамедлительно передаются в Следственный комитет для возбуждения дел по ст. 143 УК РФ.\", \"id\": \"819a4440-f2da-4cd8-8db6-2797602360a6\"}, {\"type\": \"heading2\", \"content\": \"Порядок оформления результатов контроля и обжалования\", \"id\": \"f2bc9a64-2240-4b36-ad50-eaa35adb8471\"}, {\"type\": \"paragraph\", \"content\": \"По результатам проверки составляется акт. Если выявлены нарушения, работодателю выдается предписание с указанием сроков их устранения. Важно помнить о системе «досудебного обжалования», которая стала обязательной для большинства видов контроля. Если работодатель не согласен с выводами инспектора, он обязан сначала подать жалобу через портал Госуслуг вышестоящему должностному лицу Роструда и только после получения отказа имеет право обратиться в суд. Этот механизм позволяет оперативно исправлять ошибки инспекторов без затяжных судебных разбирательств.\", \"id\": \"1037c225-81dd-46a2-b976-00c396236572\"}, {\"type\": \"paragraph\", \"content\": \"В заключение стоит отметить, что современный руководитель службы охраны труда должен владеть навыками внутреннего аудита по чек-листам Роструда (Приказ Роструда № 123). Регулярное использование проверочных листов позволяет подготовить организацию к любому визиту государственного инспектора, обеспечив полную прозрачность процедур и безопасность сотрудников на рабочих местах.\", \"id\": \"0ae56833-bd78-4890-ba29-696f2d19e8a7\"}]", "14f5dfd8-a92e-47fd-9da5-79ef551aa8ec": "[{\"type\": \"heading1\", \"content\": \"Урок: Аудит и анализ функционирования системы управления охраной труда (СУОТ)\", \"id\": \"c2502ae8-d4fe-4061-b041-1d3f13733018\"}, {\"type\": \"paragraph\", \"content\": \"Аудит СУОТ представляет собой систематический, независимый и документируемый процесс получения свидетельств аудита и их объективной оценки в целях установления степени выполнения критериев аудита. Для руководителя службы охраны труда этот процесс является ключевым инструментом контроля, позволяющим не только выявить несоответствия требованиям законодательства, но и оценить реальную эффективность профилактических мероприятий. В условиях современного правового поля РФ, опирающегося на риск-ориентированный подход, аудит перестал быть просто проверкой наличия журналов и превратился в механизм стратегического управления рисками. Основная цель внутреннего аудита — подтверждение того, что СУОТ функционирует в соответствии с запланированными мероприятиями, требованиями Трудового кодекса РФ и локальных нормативных актов работодателя.\", \"id\": \"e76a51c6-8e1b-469d-8f16-25cf660efa1e\"}, {\"type\": \"quote\", \"content\": \"Статья 217 ТК РФ: Система управления охраной труда — это комплекс взаимосвязанных и взаимодействующих между собой элементов, устанавливающих политику и цели в области охраны труда у конкретного работодателя и процедуры по достижению этих целей. Работодатель обязан обеспечить создание и функционирование системы управления охраной труда.\", \"id\": \"db9de031-35d9-4291-ac37-a011b7e12296\"}, {\"type\": \"heading2\", \"content\": \"Нормативная база и стандарты проведения аудита\", \"id\": \"cfa4f69e-12e1-4fc3-857b-0d199dec8dde\"}, {\"type\": \"paragraph\", \"content\": \"При организации системы внутреннего аудита руководитель службы ОТ должен опираться на несколько уровней документов. Во-первых, это Приказ Минтруда России № 776н «Об утверждении Примерного положения о системе управления охраной труда», который прямо указывает на необходимость проведения регулярного контроля функционирования СУОТ. Во-вторых, методологическую основу составляют национальные стандарты, такие как ГОСТ Р ИСО 45001-2020 «Системы менеджмента безопасности труда и охраны здоровья» и ГОСТ 12.0.230.1-2015, касающийся мониторинга и оценки результативности. Особое внимание следует уделять интеграции результатов проведения специальной оценки условий труда (СОУТ) в систему аудита, что регламентируется Федеральным законом № 426-ФЗ. Аудит должен подтверждать, что выявленные в ходе СОУТ вредные факторы учитываются при назначении компенсаций и планировании мероприятий по улучшению условий труда.\", \"id\": \"5ed5395e-8070-454c-a70e-125f998a5ceb\"}, {\"type\": \"heading2\", \"content\": \"Виды контроля и аудита в СУОТ\", \"id\": \"86e5c9b1-64a4-47fd-afbd-6bd2022dbdb4\"}, {\"type\": \"list\", \"content\": \"Постоянный контроль (мониторинг): осуществляется непосредственно руководителями работ и службой ОТ в ежедневном режиме (проверки рабочих мест, состояния оборудования).\\nПлановый внутренний аудит: комплексная проверка подразделений, проводимая по утвержденному графику (обычно 1-2 раза в год).\\nВнеплановый аудит: инициируется при смене технологий, после несчастных случаев на производстве или при изменении законодательства.\\nВнешний аудит: проводится независимыми консалтинговыми организациями или в рамках сертификации на соответствие стандартам ИСО.\\nВедомственный контроль: актуален для государственных учреждений и корпораций с развитой вертикальной структурой.\", \"id\": \"c06ccc2d-916f-41a3-b5d0-ae91ec2e9a4f\"}, {\"type\": \"heading2\", \"content\": \"Проверка процедур обучения в рамках аудита (Постановление № 2464)\", \"id\": \"c5121498-3cab-4e58-9976-68f8588fe1d5\"}, {\"type\": \"paragraph\", \"content\": \"Одним из самых критичных блоков аудита сегодня является проверка соблюдения требований Постановления Правительства РФ № 2464 «О порядке обучения по охране труда и проверки знания требований охраны труда». Ревизор должен убедиться, что в организации сформированы программы обучения по трем основным направлениям: требования охраны труда (А, Б, В), использование СИЗ и оказание первой помощи. В ходе аудита проверяется наличие протоколов проверки знаний, внесены ли данные в реестр Минтруда (для обученных внутри организации), и соблюдены ли сроки стажировок. Отсутствие записей о стажировке или нарушение порядка регистрации инструктажей в электронном или бумажном виде является грубым нарушением, ведущим к административной ответственности по статье 5.27.1 КоАП РФ. Руководитель службы ОТ должен анализировать не только факт наличия «корочек», но и качество транслируемых знаний.\", \"id\": \"7c894ba3-81cd-428f-89ca-7c7f420ad9cb\"}, {\"type\": \"heading2\", \"content\": \"Анализ эффективности функционирования СУОТ\", \"id\": \"df7eff41-8b83-4965-8859-57740c2b2c7e\"}, {\"type\": \"paragraph\", \"content\": \"Анализ со стороны руководства — это высший уровень оценки СУОТ. Он проводится на основе данных, собранных в ходе аудитов. Руководитель службы охраны труда готовит отчет, в который включаются показатели производственного травматизма (частота и тяжесть), профессиональной заболеваемости, результаты СОУТ и оценки профессиональных рисков. Анализ должен давать ответ на вопрос: «Достигнуты ли цели, поставленные в Политике работодателя?». Если количество микротравм (учет которых обязателен согласно ст. 226 ТК РФ) растет, это сигнал о неэффективности профилактических мер. Важно использовать не только реактивные показатели (свершившиеся несчастные случаи), но и проактивные — например, процент выявленных опасных условий, устраненных до момента инцидента.\", \"id\": \"bbb33a60-2fad-4076-84f9-f09b43ad2ad0\"}, {\"type\": \"list\", \"content\": \"Динамика показателей травматизма и профзаболеваний за отчетный период.\\nСтепень выполнения плана мероприятий по охране труда.\\nРезультативность корректирующих действий по итогам предыдущих аудитов.\\nОценка достаточности ресурсов (финансовых, людских, технических) для обеспечения безопасности.\\nПредложения по совершенствованию процедур СУОТ и пересмотру оценки рисков.\", \"id\": \"a07cc6d9-85b2-4eb7-9bb9-3996cc9712f6\"}, {\"type\": \"heading2\", \"content\": \"Методика проведения аудиторской проверки\", \"id\": \"23b36774-e90d-4fd8-a28c-c978230a3811\"}, {\"type\": \"paragraph\", \"content\": \"Процесс аудита разделяется на три этапа: подготовка, полевая проверка и подготовка отчетности. На этапе подготовки формируется аудиторская группа (желательно из сотрудников, не проверяющих собственную работу) и составляются чек-листы. Чек-листы должны быть детализированы под конкретные технологические процессы. Полевая проверка включает интервьюирование персонала, осмотр рабочих мест и проверку документации. Важно помнить, что аудит — это не поиск виновных, а поиск слабых мест в системе. Например, если работник не использует СИЗ, аудитор должен выяснить причину: не выдали, выдали неудобные средства или отсутствует культура безопасности. По завершении составляется акт (отчет), где все несоответствия классифицируются на значительные и незначительные. На каждое несоответствие разрабатывается план корректирующих действий с указанием сроков и ответственных.\", \"id\": \"df5bd110-ac11-4cb3-9132-ffce33dfe77d\"}, {\"type\": \"quote\", \"content\": \"Приказ Минтруда № 776н рекомендует: при проведении контроля функционирования СУОТ и анализа результативности СУОТ работодателю необходимо оценить выполнение мероприятий, направленных на снижение уровней профессиональных рисков.\", \"id\": \"a64a581f-7cbc-458a-83c6-768a1f6d7ec5\"}, {\"type\": \"heading2\", \"content\": \"Оценка рисков как объект аудита\", \"id\": \"20b8881b-a8fa-47a0-b634-fca1438d03d4\"}, {\"type\": \"paragraph\", \"content\": \"Современная СУОТ строится вокруг управления рисками. В ходе аудита руководитель службы ОТ должен проверить актуальность реестра опасностей. Поскольку производство динамично, риски меняются. Аудитор проверяет: отражены ли в картах оценки рисков изменения в оборудовании, учитываются ли мнения рядовых работников. Оценка рисков не должна быть формальной бумагой для инспектора ГИТ. На основе уровней риска должны распределяться бюджеты на охрану труда. Если аудит показывает, что наиболее опасные участки не финансируются в приоритетном порядке, такая СУОТ признается формальной и неэффективной.\", \"id\": \"22a14723-7772-493b-97f0-7b217ce457e5\"}, {\"type\": \"heading2\", \"content\": \"Документационное обеспечение аудита\", \"id\": \"c2978388-b41a-4dce-b04b-440ab107dc85\"}, {\"type\": \"list\", \"content\": \"Положение о проведении внутреннего аудита СУОТ (ЛНА).\\nЕжегодный график проведения проверок.\\nПриказ о назначении комиссии (или аудиторов).\\nЧек-листы (контрольные листы) по направлениям.\\nОтчет (акт) по результатам аудита с перечнем несоответствий.\\nПлан корректирующих и предупреждающих действий (САРА).\", \"id\": \"c2284a5f-b219-4956-bcd0-70c1eeb27de2\"}, {\"type\": \"paragraph\", \"content\": \"Завершающим этапом цикла PDCA (Plan-Do-Check-Act) в СУОТ является действие по улучшению. Результаты аудита и последующего анализа со стороны руководства должны приводить к обновлению локальных актов, пересмотру программ обучения в соответствии с Приказом № 2464н и, при необходимости, к изменению структуры службы охраны труда. Только при условии замыкания этого цикла система управления становится «живой» и способной эффективно защищать жизнь и здоровье работников, а также минимизировать юридические риски для руководителя организации.\", \"id\": \"17d53333-90f7-4ba7-889b-8480aa22e57f\"}, {\"type\": \"heading2\", \"content\": \"Типичные ошибки при проведении аудита\", \"id\": \"acd9ceb2-10b2-4dab-a975-f0f582d806a3\"}, {\"type\": \"paragraph\", \"content\": \"К наиболее распространенным ошибкам руководителей служб ОТ можно отнести: формальный подход (когда аудит проводится только по документам без выхода «в цех»), отсутствие контроля за выполнением корректирующих действий (несоответствия переходят из акта в акт годами) и недостаточную квалификацию внутренних аудиторов. Важно, чтобы аудиторы понимали не только требования закона, но и специфику технологических процессов. Также критической ошибкой является скрытие негативных результатов аудита от высшего руководства, что создает иллюзию безопасности и препятствует получению необходимых ресурсов для модернизации системы.\", \"id\": \"d8e7c419-dde0-4baa-bbd4-cc71f61b07a0\"}]", "d3928e39-2947-4b06-a8e9-8b2c998cf86e": "[{\"type\": \"heading1\", \"content\": \"Урок: Ответственность за нарушение требований охраны труда\", \"id\": \"86dee492-506a-498f-84f4-9948d5a78e30\"}, {\"type\": \"paragraph\", \"content\": \"Для руководителя службы охраны труда понимание системы ответственности является критически важным аспектом профессиональной деятельности. В Российской Федерации правовое регулирование в данной сфере основывается на комплексном подходе, обеспечивающем соблюдение конституционного права человека на труд в условиях, отвечающих требованиям безопасности и гигиены. Ответственность за несоблюдение норм охраны труда классифицируется по нескольким видам и может быть применена как к юридическим лицам (организациям), так и к должностным лицам, включая самих специалистов в области охраны труда, руководителей подразделений и топ-менеджмент. Основным механизмом контроля выступает Федеральный государственный контроль (надзор) за соблюдением трудового законодательства, осуществляемый Федеральной службой по труду и занятости (Роструд) и его территориальными органами.\", \"id\": \"59b209a3-eeb9-454b-a040-9e663b7f9ccc\"}, {\"type\": \"quote\", \"content\": \"Согласно статье 419 Трудового кодекса РФ, лица, виновные в нарушении трудового законодательства и иных актов, содержащих нормы трудового права, привлекаются к дисциплинарной и материальной ответственности в порядке, установленном настоящим Кодексом и иными федеральными законами, а также привлекаются к гражданско-правовой, административной и уголовной ответственности в порядке, установленном федеральными законами.\", \"id\": \"573f3d3e-4a8f-468c-a536-b844edc57442\"}, {\"type\": \"heading2\", \"content\": \"Дифференциация ответственности и роль СОТ\", \"id\": \"4716ff4c-97ed-4a61-a6fa-313c9b1863e8\"}, {\"type\": \"paragraph\", \"content\": \"Руководитель службы охраны труда (СОТ) несет ответственность в рамках своей должностной инструкции и трудового договора. Важно понимать, что ответственность распределяется между работодателем и должностными лицами. Ключевым документом здесь является Постановление Правительства РФ от 24.12.2021 № 2464 «О порядке обучения по охране труда и проверки знания требований охраны труда». Несоблюдение данных правил автоматически переводит нарушение в категорию административных правонарушений. Если специалист по охране труда не обеспечил проведение своевременной проверки знаний или не организовал процесс обучения, он может быть привлечен к дисциплинарной ответственности внутри компании, а организация — к штрафам по КоАП РФ. При этом крайне важно разграничивать ответственность за непосредственное нарушение правил безопасности на рабочем месте (которую несет работник или его непосредственный руководитель) и нарушение организационно-методического обеспечения системы управления охраной труда (СУОТ).\", \"id\": \"7fabd16d-0c7a-45c3-ba4d-b99f6c354efe\"}, {\"type\": \"heading2\", \"content\": \"Административная ответственность: КоАП РФ\", \"id\": \"920a3048-1729-4fa1-b1ef-b9155156fc06\"}, {\"type\": \"paragraph\", \"content\": \"Наиболее часто применяемым инструментом воздействия является Кодекс РФ об административных правонарушениях. Статья 5.27.1 КоАП РФ содержит детализированную разбивку по видам нарушений. Особое внимание уделяется отсутствию специальной оценки условий труда (СОУТ), требования к которой установлены Федеральным законом № 426-ФЗ. Штрафы здесь носят аккумулирующий характер. Например, если в организации не проведена оценка условий труда на пяти рабочих местах, в некоторых трактовках надзорных органов и судебной практике за это может последовать суммированный штраф, что создает существенные финансовые риски для предприятия.\", \"id\": \"408527e9-8c5d-45c6-9c44-ad98d8de09cf\"}, {\"type\": \"list\", \"content\": \"Нарушение общих государственных нормативных требований охраны труда: влечет предупреждение или штраф на юрлиц от 50 000 до 80 000 рублей.\\nНарушение порядка проведения СОУТ или ее непроведение: штраф на юрлиц от 60 000 до 80 000 рублей.\\nДопуск работника к исполнению трудовых обязанностей без прохождения обучения и проверки знаний требований ОТ, а также обязательных медосмотров: штраф на юрлиц от 110 000 до 130 000 рублей за каждого такого работника.\\nНеобеспечение работников средствами индивидуальной защиты (СИЗ), отнесенными ко 2 классу риска (предотвращающие гибель или инвалидизацию): штраф на юрлиц от 130 000 до 150 000 рублей.\\nПовторное совершение аналогичного административного правонарушения: штраф на юрлиц до 200 000 рублей или административное приостановление деятельности на срок до 90 суток.\", \"id\": \"2a03fcaf-9957-4231-8508-576cbdc27381\"}, {\"type\": \"heading2\", \"content\": \"Уголовная ответственность: Статья 143 УК РФ\", \"id\": \"7bdcffec-3390-458e-9a78-75ea5ccb0996\"}, {\"type\": \"paragraph\", \"content\": \"Уголовная ответственность наступает только при наличии тяжких последствий: причинения тяжкого вреда здоровью человека или смерти. Субъектом ответственности по ст. 143 УК РФ являются лица, на которых в силу их служебного положения или по специальному распоряжению непосредственно возложена обязанность обеспечивать соблюдение правил охраны труда на определенном участке работ, а также руководители организаций и их заместители. Руководитель службы охраны труда может быть привлечен к ответственности, если следствием будет доказано, что его бездействие (например, отсутствие уведомления работодателя о критических нарушениях) привело к несчастному случаю. Важно опираться на ГОСТ 12.0.230-2007 «ССБТ. Системы управления охраной труда», который определяет стандарты распределения обязанностей в организации.\", \"id\": \"f446b996-9ae9-4486-acad-7bb4636a57eb\"}, {\"type\": \"quote\", \"content\": \"Статья 143 УК РФ гласит: Нарушение требований охраны труда, совершенное лицом, на которое возложены обязанности по их соблюдению, если это повлекло по неосторожности причинение тяжкого вреда здоровью человека, наказывается штрафом в размере до четырехсот тысяч рублей... либо лишением свободы на срок до одного года.\", \"id\": \"08a7ccbc-1906-427d-9ecf-65b8ba18ba41\"}, {\"type\": \"heading2\", \"content\": \"Дисциплинарная ответственность и материальные последствия\", \"id\": \"f748e0d8-aa05-4963-a7a1-d5f600c676aa\"}, {\"type\": \"paragraph\", \"content\": \"Дисциплинарная ответственность регулируется статьями 192–195 ТК РФ. Для специалиста по охране труда это может быть замечание, выговор или увольнение. Основанием может служить невыполнение должностных обязанностей, закрепленных в профессиональном стандарте «Специалист в области охраны труда». Важным инструментом воздействия работодателя на нарушителей среди персонала является лишение премиальных выплат, если это предусмотрено локальным актом (Положением об оплате труда). Кроме того, существует материальная ответственность (ст. 238 ТК РФ), согласно которой работник обязан возместить работодателю причиненный ему прямой действительный ущерб. В контексте охраны труда это могут быть выплаты по искам пострадавших сотрудников, которые работодатель в регрессном порядке может попытаться взыскать с виновного должностного лица (в пределах среднего месячного заработка, если не установлена полная материальная ответственность).\", \"id\": \"b942e0b4-ff3f-4d60-a31f-191d0068c022\"}, {\"type\": \"heading2\", \"content\": \"Гражданско-правовая ответственность организации\", \"id\": \"6bb9830a-d61a-4f92-b0cf-785587aa6d36\"}, {\"type\": \"paragraph\", \"content\": \"Данный вид ответственности касается исключительно юридического лица или индивидуального предпринимателя перед пострадавшим работником или его родственниками. В соответствии с ГК РФ, работодатель обязан компенсировать моральный вред, а также дополнительные расходы на лечение и реабилитацию, не покрываемые выплатами из Социального фонда РФ. Суммы компенсаций морального вреда в последние годы имеют тенденцию к росту и в случае смертельных несчастных случаев могут исчисляться миллионами рублей. Руководитель СОТ должен использовать эти риски как аргумент при обосновании бюджета на закупку качественных СИЗ или модернизацию оборудования.\", \"id\": \"cfd01414-95b4-4164-ab2e-40d272d3ebc6\"}, {\"type\": \"heading2\", \"content\": \"Зоны особого внимания для руководителя СОТ\", \"id\": \"f1f9abc2-10dc-4ee4-972f-c344dfbf8a6b\"}, {\"type\": \"paragraph\", \"content\": \"В рамках риск-ориентированного подхода руководитель службы охраны труда должен сосредоточиться на трех «критических точках», за которые надзорные органы наказывают жестче всего. Во-первых, это легитимность системы обучения. С введением Постановления № 2464 контроль за реестрами обученных лиц в информационной системе Минтруда стал автоматизированным. Любое расхождение данных может стать поводом для внеплановой проверки. Во-вторых, это соблюдение процедуры расследования несчастных случаев. Сокрытие несчастного случая или нарушение сроков уведомления органов (согласно ст. 228.1 ТК РФ) влечет за собой штрафы и пристальное внимание прокуратуры. В-третьих, это соблюдение периодичности медосмотров и психиатрических освидетельствований для определенных категорий работников.\", \"id\": \"9b2f2ef5-e056-41c0-9159-b9f67add1197\"}, {\"type\": \"list\", \"content\": \"Контроль за своевременным проведением оценки профессиональных рисков (Приказ Минтруда № 776н).\\nНадзор за соблюдением норм выдачи СИЗ по Единым типовым нормам (ЕТН).\\nМониторинг соблюдения режима труда и отдыха, особенно для водителей и персонала на опасных объектах.\\nПроверка соответствия оборудования требованиям ГОСТ ССБТ.\\nОбеспечение функционирования трехступенчатого контроля за состоянием условий труда.\", \"id\": \"fdc39dac-75d9-47e8-a474-e0044d761fa9\"}, {\"type\": \"heading2\", \"content\": \"Минимизация рисков ответственности\", \"id\": \"65d7375f-a824-4f37-a1df-382de8c8ef13\"}, {\"type\": \"paragraph\", \"content\": \"Для минимизации персональных рисков руководителю СОТ необходимо выстроить систему «бумажной безопасности». Это не означает формализм, но подразумевает четкое документальное подтверждение всех действий специалиста. Если СОТ выявил нарушение, он обязан выдать предписание руководителю подразделения. Если предписание не исполнено, необходимо письменно уведомить работодателя (генерального директора). Наличие таких служебных записок с отметкой о получении является ключевым доказательством отсутствия вины специалиста при судебных разбирательствах. Помните, что согласно ст. 2.1 КоАП РФ, юридическое лицо признается виновным, если у него имелась возможность для соблюдения правил, но данным лицом не были приняты все зависящие от него меры.\", \"id\": \"711f0d6c-8e9f-4d61-b6f0-7b472e2bc010\"}, {\"type\": \"paragraph\", \"content\": \"Завершая обзор, следует подчеркнуть, что динамика изменений в законодательстве (переход к риск-ориентированному подходу и ЕТН) требует от руководителя службы охраны труда непрерывного обучения. Знание актуальных редакций ТК РФ и подзаконных актов — это не только профессиональная обязанность, но и личная гарантия правовой безопасности в условиях ужесточающегося государственного контроля за сохранением жизни и здоровья работников.\", \"id\": \"b3ce8b3f-4e63-46e1-8a72-1c3c6371795d\"}]", "015c704d-830b-4ead-981f-dafb9463998c": "[{\"type\": \"heading1\", \"content\": \"Трудовое законодательство и нормативные правовые акты по охране труда: иерархия и система применения\", \"id\": \"881edecd-3ce3-4fbf-9a56-b695ffc76114\"}, {\"type\": \"paragraph\", \"content\": \"Система нормативного правового регулирования охраны труда в Российской Федерации представляет собой многоуровневую структуру, базирующуюся на Конституции РФ и Трудовом кодексе. Для руководителя службы охраны труда понимание этой иерархии является критически важным, так как оно позволяет корректно определять приоритетность норм при возникновении правовых коллизий. В условиях продолжающейся регуляторной гильотины законодательство стремительно трансформируется от жесткого предписывающего регулирования к риск-ориентированному подходу, где ключевым элементом становится профилактика производственного травматизма.\", \"id\": \"03c2e269-8bd9-4f95-99e2-9ca9a6ab532e\"}, {\"type\": \"heading2\", \"content\": \"Основополагающая роль Трудового кодекса РФ\", \"id\": \"46def020-bc44-457c-91ce-129b93b82fb6\"}, {\"type\": \"paragraph\", \"content\": \"Раздел X Трудового кодекса РФ является фундаментом всей системы охраны труда. После масштабных изменений, вступивших в силу с 1 марта 2022 года, акцент сместился на заблаговременное выявление опасностей. Статья 209 ТК РФ определяет основные понятия, включая профессиональный риск и управление им. Статья 214 ТК РФ устанавливает расширенный перечень обязанностей работодателя, среди которых ключевыми являются обеспечение безопасности работников при эксплуатации зданий, сооружений, оборудования, а также применение СИЗ, прошедших обязательную сертификацию или декларирование. Важно помнить, что любые локальные нормативные акты организации, ухудшающие положение работника по сравнению с установленным в ТК РФ, признаются недействительными.\", \"id\": \"387929b3-fa93-49a8-9b90-b6b973568bbf\"}, {\"type\": \"quote\", \"content\": \"Статья 212 ТК РФ: Государственные нормативные требования охраны труда устанавливают правила, процедуры, критерии и нормативы, направленные на сохранение жизни и здоровья работников в процессе трудовой деятельности.\", \"id\": \"f5425fd1-dba5-4087-9605-05ba1acec162\"}, {\"type\": \"heading2\", \"content\": \"Специальная оценка условий труда (СОУТ) и ФЗ-426\", \"id\": \"b98fab7e-8396-4450-accc-ef1b1352bc0b\"}, {\"type\": \"paragraph\", \"content\": \"Федеральный закон № 426-ФЗ «О специальной оценке условий труда» является вторым по значимости инструментом в работе руководителя службы ОТ. Данный закон определяет единый порядок проведения идентификации потенциально вредных и опасных факторов производственной среды. Результаты СОУТ влияют на установление гарантий и компенсаций работникам, расчет страховых тарифов в Социальный фонд России (СФР) и планирование мероприятий по улучшению условий труда. Руководитель службы должен контролировать не только своевременность проведения СОУТ (не реже одного раза в пять лет, если иное не установлено законом), но и корректность внесения данных во ФГИС СОУТ организацией-проводящим оценку.\", \"id\": \"81cff509-8da6-4393-ae60-f4bb4e664340\"}, {\"type\": \"heading2\", \"content\": \"Обучение и проверка знаний: ПП РФ № 2464\", \"id\": \"1b4ff485-6323-4d79-b9cf-6bc59cf5c6d0\"}, {\"type\": \"paragraph\", \"content\": \"С 1 сентября 2022 года действует Постановление Правительства РФ № 2464 «О порядке обучения по охране труда и проверки знания требований охраны труда». Этот документ радикально изменил подход к подготовке персонала. Теперь обучение разделено на пять основных видов: инструктажи, стажировка на рабочем месте, обучение оказанию первой помощи, обучение использованию (применению) СИЗ и собственно обучение требованиям охраны труда (программы А, Б и В). Программа «А» ориентирована на общие вопросы управления, «Б» — на безопасные методы выполнения работ, «В» — на работы повышенной опасности. Руководитель службы охраны труда обязан обеспечить ведение реестра обученных лиц и своевременную передачу данных в информационную систему Минтруда.\", \"id\": \"e6e0bdb4-8f5f-4b6c-b527-17237969b886\"}, {\"type\": \"list\", \"content\": \"Инструктаж по охране труда (вводный, на рабочем месте, целевой)\\nСтажировка на рабочем месте (для определенных категорий работников)\\nОбучение по оказанию первой помощи пострадавшим\\nОбучение по использованию (применению) средств индивидуальной защиты\\nОбучение требованиям охраны труда у работодателя или в организациях, оказывающих услуги по обучению\", \"id\": \"57f4e850-a439-4946-a63e-9d8e9bec5832\"}, {\"type\": \"heading2\", \"content\": \"Обеспечение СИЗ: новые Единые типовые нормы\", \"id\": \"9938bb73-79f1-4df7-be2e-7ecaddf29843\"}, {\"type\": \"paragraph\", \"content\": \"Переходный период на Единые типовые нормы (ЕТН) выдачи СИЗ и смывающих средств, установленный Приказом Минтруда № 766н и № 767н, требует от руководителя службы глубокой инвентаризации рабочих мест. В отличие от старых отраслевых норм, ЕТН основываются на выявленных опасностях на конкретном рабочем месте. Это означает, что если в ходе оценки профрисков выявлена опасность, не предусмотренная старым типовым перечнем, работодатель обязан обеспечить работника защитой, опираясь на Приказ № 767н. Регулирование использования СИЗ также опирается на технический регламент Таможенного союза ТР ТС 019/2011, который устанавливает требования к качеству и маркировке продукции.\", \"id\": \"1c3b88a4-8c26-4cde-bb9a-272c8f6fe095\"}, {\"type\": \"heading2\", \"content\": \"Система стандартов безопасности труда (ССБТ) и ГОСТы\", \"id\": \"19db80e9-2840-4717-97c7-a2ef17c2cdb4\"}, {\"type\": \"paragraph\", \"content\": \"ГОСТы системы ССБТ играют роль технического фундамента. Например, ГОСТ 12.0.230.1-2015 устанавливает требования к системам управления охраной труда (СУОТ). При разработке внутреннего Положения о СУОТ руководитель службы должен руководствоваться не только Приказом Минтруда № 776н (Об утверждении Примерного положения о СУОТ), но и соответствующими стандартами. Стандарты ССБТ подразделяются на организационно-методические, стандарты требований к производственному оборудованию, процессам и средствам защиты. Использование ГОСТов при описании технологических регламентов позволяет минимизировать риски технического травматизма и облегчает прохождение экспертиз госнадзора.\", \"id\": \"8712e12f-de2e-4b81-a28d-ad7dff218181\"}, {\"type\": \"quote\", \"content\": \"Приказ Минтруда России от 29.10.2021 № 776н: Создание и обеспечение функционирования системы управления охраной труда осуществляются работодателем в целях обеспечения выполнения требований охраны труда и управления профессиональными рисками.\", \"id\": \"a8cb92f7-0cfa-4294-9ac9-e5b0101a3013\"}, {\"type\": \"heading2\", \"content\": \"Медицинские осмотры и психиатрические освидетельствования\", \"id\": \"497a4546-13a6-4b77-b067-8f7068f1f44c\"}, {\"type\": \"paragraph\", \"content\": \"Порядок проведения обязательных медицинских осмотров регламентируется Приказом Минздрава № 29н. Руководитель службы охраны труда должен четко разграничивать предварительные (при поступлении) и периодические осмотры. Список контингентов формируется на основании результатов СОУТ и наличия вредных факторов, поименованных в приложении к приказу. Особое внимание следует уделять обязательному психиатрическому освидетельствованию (Постановление Правительства РФ № 695 утратило силу, сейчас действует Приказ Минздрава № 405н). Важно контролировать недопущение к работе лиц, не прошедших обследование или имеющих противопоказания, так как это является грубейшим нарушением трудового законодательства.\", \"id\": \"857ee76a-33b6-4d35-8c2f-33a9f4454e56\"}, {\"type\": \"heading2\", \"content\": \"Учет и расследование несчастных случаев и микроповреждений\", \"id\": \"6ccd1d1a-d0af-4639-87d6-9fccb0ab8654\"}, {\"type\": \"paragraph\", \"content\": \"Новеллой законодательства (ст. 226 ТК РФ) стала обязанность работодателя вести учет и рассматривать обстоятельства и причины микроповреждений (микротравм). Это превентивная мера, позволяющая предупреждать тяжелые несчастные случаи. Порядок расследования классических несчастных случаев на производстве утвержден Приказом Минтруда № 223н. Руководитель службы охраны труда как обязательный член комиссии должен обеспечивать объективность сбора доказательств, соблюдение сроков извещения органов (СФР, прокуратура, ГИТ) и правильное оформление актов формы Н-1. Несвоевременное или некорректное расследование влечет административную (ст. 5.27.1 КоАП РФ), а в ряде случаев и уголовную ответственность (ст. 143 УК РФ).\", \"id\": \"2cea6b07-e378-4b98-af3c-3cd7ffaa7d5b\"}, {\"type\": \"list\", \"content\": \"Фиксация обращения работника к руководителю о получении микротравмы\\nРассмотрение обстоятельств и причин в течение 3 календарных дней\\nСоставление Справки о рассмотрении обстоятельств и причин\\nРегистрация в Журнале учета микроповреждений (микротравм)\\nРазработка мероприятий по устранению причин\", \"id\": \"6a307d16-f0cb-46db-b792-84806d34bc6c\"}, {\"type\": \"heading2\", \"content\": \"Локальные нормативные акты (ЛНА)\", \"id\": \"670b896a-8981-48c9-a59e-dd457bdd0ae8\"}, {\"type\": \"paragraph\", \"content\": \"На уровне организации законодательство материализуется в виде ЛНА. Профессиональный стандарт специалиста по охране труда обязывает руководителя службы формировать пакет документов, включающий: Положение о СУОТ, инструкции по охране труда по профессиям и видам работ (разработанные согласно Приказу Минтруда № 772н), перечни выдачи СИЗ, графики обучения и планы мероприятий по улучшению условий труда. Все инструкции должны проходить актуализацию при изменении НПА или условий труда. Отсутствие актуализированных инструкций трактуется инспекторами ГИТ как необеспечение безопасности работников, что ведет к значительным штрафам.\", \"id\": \"b053d1c5-c537-47da-9489-c79452bffddf\"}, {\"type\": \"heading2\", \"content\": \"Заключение и выводы\", \"id\": \"10596673-3099-47f8-ba54-fe855a983c4c\"}, {\"type\": \"paragraph\", \"content\": \"Современное трудовое законодательство РФ в сфере охраны труда требует от руководителя службы не просто контроля соблюдения правил, а выстраивания живой системы управления. Знание иерархии НПА — от ТК РФ до отраслевых правил (ПОТ) — позволяет защитить интересы работодателя и сохранить здоровье персонала. Основной тренд — переход от реагирования на происшествия к управлению рисками. Именно поэтому владение методиками оценки рисков и понимание процедур обучения по Постановлению № 2464 становятся базовыми компетенциями для успешного прохождения проверок и обеспечения производственной безопасности.\", \"id\": \"d4cef49d-389d-4a2d-9e5d-0cda278553f2\"}]", "59d2b222-2435-4d9b-97dc-856b68a39a06": "[{\"type\": \"heading1\", \"content\": \"Практическое задание: Идентификация опасностей и оценка профессиональных рисков на рабочем месте сварщика\", \"id\": \"078dd8d1-22cf-4305-9c00-971923b803db\"}, {\"type\": \"paragraph\", \"content\": \"Данное задание разработано для закрепления практических навыков специалистов по охране труда в области выявления потенциальных угроз и определения уровня профессионального риска в соответствии с актуальным законодательством РФ. Слушателям предлагается проанализировать производственную ситуацию, выбрать методику оценки и сформировать перечень мероприятий по снижению рисков.\", \"id\": \"75e0b1e4-bcc8-41d2-8e54-69f7affa4dbf\"}, {\"type\": \"heading2\", \"content\": \"Постановка задачи и описание ситуации\", \"id\": \"8325751f-4e80-49c7-bceb-ef08d685cafc\"}, {\"type\": \"paragraph\", \"content\": \"Объект исследования: Производственный цех металлоконструкций ООО «СтальМонтаж». Рабочее место — пост электросварщика ручной сварки. Сварщик (мужчина, 42 года, стаж 15 лет) выполняет работы по изготовлению двутавровых балок. Работа проводится стационарно в цеху, однако 20% рабочего времени занимают работы на высоте (сварка узлов на эстакаде высотой 2.5 метра). Технологический процесс включает: подготовку кромок (зачистка УШМ), установку деталей в зажимные устройства, непосредственно сварку электродом и последующую проверку шва. Помещение оборудовано общеобменной вентиляцией, однако местная вытяжная вентиляция на данном посту временно неисправна. В непосредственной близости (3 метра) работает мостовой кран, перемещающий заготовки.\", \"id\": \"b3f696ff-83e0-4d55-917f-7fcd0d68b49e\"}, {\"type\": \"heading2\", \"content\": \"Исходные данные\", \"id\": \"ab370398-3001-4e55-a8c5-c6c72d89376c\"}, {\"type\": \"list\", \"content\": [\"Оборудование: Сварочный инвертор, углошлифовальная машина (УШМ), лестница-стремянка, ручной слесарный инструмент.\", \"Материалы: Стальной прокат, электроды с рутиловым покрытием, абразивные диски.\", \"СИЗ: Костюм сварщика (брезент), ботинки с металлическим подноском, маска «Хамелеон», защитные очки, перчатки (спилковые краги).\", \"Окружающая среда: Уровень шума в цеху — 82 дБА, освещенность — 250 лк, температура в зимний период — +14°C.\", \"Статистика: За последние 3 года на данном участке зафиксирован 1 случай микротравмы (попадание окалины в глаз при зачистке шва без очков) и 1 случай падения с лестницы без тяжелых последствий.\"], \"id\": \"7fd310da-d111-444c-aa25-6117c3477a14\"}, {\"type\": \"heading2\", \"content\": \"Вопросы для разбора и выполнения задания\", \"id\": \"a516db61-48bb-4e78-adb7-37762d62442a\"}, {\"type\": \"list\", \"content\": [\"Сформулируйте перечень не менее 7 опасностей, характерных для данного рабочего места, классифицировав их согласно Приказу Минтруда №776н.\", \"Выберите и обоснуйте метод оценки уровня профессионального риска (например, метод Файна-Кинни или Матричный метод). Почему выбранный метод подходит для данного предприятия?\", \"Рассчитайте уровень риска для двух наиболее критичных опасностей: «Воздействие сварочного аэрозоля» и «Падение при разности уровней высот».\", \"Разработайте план корректирующих мероприятий по снижению рисков для выявленных опасностей с высоким уровнем, соблюдая иерархию мер управления (устранение, замена, инженерные меры, административные меры, СИЗ).\", \"Какие документы должны быть оформлены по результатам данной оценки рисков для соблюдения требований инспекции труда?\", \"Определите, как часто должна проводиться переоценка рисков на данном рабочем месте в случае модернизации вентиляционной системы.\"], \"id\": \"531adb2b-ed0f-46cb-b858-b1006e877af1\"}, {\"type\": \"heading2\", \"content\": \"Методические указания\", \"id\": \"9346ed1f-2a80-414b-ba71-356b60bf26c6\"}, {\"type\": \"paragraph\", \"content\": \"При выполнении задания используйте системный подход. Сначала классифицируйте опасности по источнику возникновения: физические, химические, психофизиологические. Помните, что отсутствие местной вентиляции автоматически повышает уровень химической опасности. При использовании матричного метода рекомендуется использовать шкалу 5х5 (Вероятность х Тяжесть). При оценке тяжести последствий учитывайте не только травмы, но и возможность развития профессиональных заболеваний (пневмокониоз, электроофтальмия). Обратите внимание на то, что использование СИЗ является последним барьером защиты и не устраняет саму опасность.\", \"id\": \"60615180-e62f-4073-852c-289b1e405d95\"}, {\"type\": \"heading2\", \"content\": \"Образец решения (эталонный ответ)\", \"id\": \"e5aef3fc-2e84-4a91-a05d-05895ad1bc7f\"}, {\"type\": \"quote\", \"content\": \"Фрагмент Перечня опасностей: 1. Механическая опасность (порез кромкой металла); 2. Электрическая опасность (поражение током при контакте с токоведущими частями); 3. Термическая опасность (ожоги от брызг металла); 4. Химическая опасность (вдыхание марганца и озона); 5. Световая среда (УФ-излучение дуги); 6. Шум (от УШМ); 7. Падение с высоты.\", \"id\": \"37443f57-bb99-4a50-8ca8-dbeba8e82e2b\"}, {\"type\": \"paragraph\", \"content\": \"Оценка риска методом матрицы 5х5: Для опасности «Воздействие сварочного аэрозоля» вероятность принимается как «Часто» (4), так как вентиляция не работает. Тяжесть — «Значительная» (4) из-за риска профзаболевания. Итоговый индекс риска = 16 (Высокий риск). Для опасности «Падение с высоты» вероятность «Средняя» (3), тяжесть «Тяжелая» (5). Итоговый индекс = 15 (Высокий риск).\", \"id\": \"19767ece-ba54-4f9a-9bec-6654203a6806\"}, {\"type\": \"paragraph\", \"content\": \"Меры управления: 1. Инженерные: Срочный ремонт местной вытяжной вентиляции (приоритет №1). 2. Административные: Обучение по охране труда при работе на высоте, запрет на использование неисправных лестниц. 3. Технические: Замена лестниц-стремянок на передвижные подмости с ограждениями. 4. СИЗ: Выдача респираторов для защиты от сварочных аэрозолей на период ремонта вентиляции.\", \"id\": \"3f85f0f6-2073-483e-9082-a2cb7099cc4e\"}, {\"type\": \"paragraph\", \"content\": \"Результатом процедуры должны стать: Реестр опасностей организации, Карты оценки профессиональных рисков на рабочих местах, План мероприятий по управлению рисками. Переоценка проводится внепланово при изменении технологического процесса или вводе нового оборудования (п. 25 Приказа 776н).\", \"id\": \"5b6a0ebe-b9e4-44d0-a17a-0ea3ef2e45be\"}, {\"type\": \"heading2\", \"content\": \"Ссылки на нормативно-правовые акты (НПА)\", \"id\": \"5ca86ddb-bfe9-4625-82c5-8ca34277abb9\"}, {\"type\": \"list\", \"content\": [\"Трудовой кодекс РФ (Статьи 209, 214, 218) — устанавливают обязанность работодателя по оценке рисков.\", \"Приказ Минтруда России от 29.10.2021 № 776н «Об утверждении Примерного положения о системе управления охраной труда» (содержит классификатор опасностей).\", \"Приказ Минтруда России от 28.12.2021 № 926 «Об утверждении Рекомендаций по выбору методов оценки уровней профессиональных рисков и по снижению уровней таких рисков».\", \"Приказ Минтруда России от 31.01.2022 № 36 «Об утверждении Рекомендаций по классификации, обнаружению, распознаванию и описанию опасностей».\", \"ГОСТ Р 12.0.010-2009 «Система стандартов безопасности труда. Системы управления охраной труда. Определение опасностей и оценка рисков».\"], \"id\": \"7cf80a15-d32c-4958-b036-3e01b4b588af\"}]", "289a9a68-d409-46dd-8f8c-c866af1ad2a0": "[{\"type\": \"heading1\", \"content\": \"Управление профессиональными рисками: стратегии снижения и механизмы контроля\", \"id\": \"bc28d80a-3e7e-4ed9-a6db-5a7924e0ee49\"}, {\"type\": \"paragraph\", \"content\": \"Управление профессиональными рисками (УПР) является ключевым элементом современной системы управления охраной труда (СУОТ), перешедшей от реактивной модели реагирования на несчастные случаи к проактивной модели их предотвращения. В соответствии со статьей 209.1 Трудового кодекса РФ, основными принципами обеспечения безопасности труда являются предупреждение, профилактика опасностей и минимизация повреждения здоровья работников. Руководитель службы охраны труда должен понимать, что оценка рисков — это не разовое мероприятие, а непрерывный циклический процесс, интегрированный во все бизнес-процессы организации. Основная цель данного этапа — не просто выявить опасности, а внедрить эффективные меры управления, которые позволят снизить вероятность реализации опасных событий или тяжесть их последствий до приемлемого уровня.\", \"id\": \"3053b81c-1675-419e-b1f0-f5b7ba1be982\"}, {\"type\": \"heading2\", \"content\": \"Нормативно-правовая база управления рисками\", \"id\": \"e09b08fb-1e2f-46ff-bcc3-547d6a1953e7\"}, {\"type\": \"quote\", \"content\": \"Статья 214 ТК РФ: Работодатель обязан обеспечить систематическое выявление опасностей и профессиональных рисков, их регулярный анализ и оценку. При этом реализация мероприятий по улучшению условий труда должна базироваться на результатах такой оценки.\", \"id\": \"62317f80-c432-475a-bb66-a79021d93a6f\"}, {\"type\": \"paragraph\", \"content\": \"Помимо Трудового кодекса, методология управления рисками опирается на ряд подзаконных актов и стандартов. Приказ Минтруда России от 29.10.2021 № 776н утверждает Примерное положение о системе управления охраной труда, где подробно описан алгоритм идентификации опасностей и оценки уровней рисков. Важную роль играет Приказ Минтруда России от 28.12.2021 № 796, устанавливающий рекомендации по выбору методов оценки уровней профессиональных рисков и по их снижению. Не следует забывать и о национальных стандартах, таких как ГОСТ Р ИСО 45001-2020 и ГОСТ Р 58771-2019 «Менеджмент риска. Технологии оценки риска», которые предоставляют глубокий инструментарий для системного анализа производственной среды.\", \"id\": \"426f1ba7-7ec4-4981-b75e-79dd908a4bff\"}, {\"type\": \"heading2\", \"content\": \"Иерархия мер управления рисками\", \"id\": \"cd8f5d00-ed8c-4a33-a167-9964794b3b7c\"}, {\"type\": \"paragraph\", \"content\": \"При выборе мер по снижению уровней профессиональных рисков руководитель службы ОТ должен руководствоваться международно признанной и закрепленной в российском законодательстве иерархией мер. Эта последовательность определяет приоритетность действий от наиболее эффективных к наименее надежным. Применение средств индивидуальной защиты (СИЗ) всегда должно рассматриваться как последняя мера, когда технические и организационные решения не позволяют полностью исключить риск.\", \"id\": \"f47cb4d4-1281-4e2a-8a40-30453f66669a\"}, {\"type\": \"list\", \"content\": \"Устранение опасности (Исключение): Полное удаление источника риска из производственного процесса, например, отказ от использования опасного химического вещества.\\nЗамена (Субституция): Замена опасного процесса, материала или оборудования на менее опасный (например, замена окраски пульверизатором на порошковую окраску).\\nИнженерные (технические) методы: Изоляция людей от опасностей путем установки ограждений, систем блокировки, локальной вытяжной вентиляции или автоматизации процессов.\\nАдминистративные меры: Внедрение процедур безопасного выполнения работ, проведение инструктажей в соответствии с Постановлением Правительства РФ № 2464, маркировка зон, ограничение времени воздействия негативных факторов.\\nСредства индивидуальной защиты (СИЗ): Предоставление работникам спецодежды, спецобуви и других средств защиты, прошедших сертификацию или декларирование в соответствии с ТР ТС 019/2011.\", \"id\": \"5bad3dac-626a-47cc-812f-bef11a563d11\"}, {\"type\": \"heading2\", \"content\": \"Разработка плана мероприятий по снижению рисков\", \"id\": \"d70d34f2-cbbc-4231-964c-47525ce80121\"}, {\"type\": \"paragraph\", \"content\": \"После идентификации опасностей и оценки уровня риска для каждой позиции составляется перечень мер контроля. Если итоговый уровень риска признается недопустимым (высоким), работодатель обязан немедленно прекратить работы или принять экстренные меры по его снижению. Для умеренных рисков разрабатывается долгосрочный план мероприятий. В планах должны быть указаны конкретные сроки исполнения, ответственные лица (из числа технических руководителей и специалистов) и источники финансирования. Важно, чтобы план корректировался при вводе нового оборудования, изменении технологических процессов или после проведения специальной оценки условий труда (СОУТ) согласно ФЗ-426.\", \"id\": \"b5f1055b-c749-4745-b9b1-99892e867347\"}, {\"type\": \"quote\", \"content\": \"Пункт 25 Приложения к Приказу Минтруда № 776н: Меры контроля и управления рисками должны быть направлены на обеспечение того, чтобы остаточный риск после их внедрения не превышал установленный организацией уровень допустимого риска.\", \"id\": \"47a77f97-98b6-4ec6-9ed0-c256263dc087\"}, {\"type\": \"heading2\", \"content\": \"Обучение персонала как инструмент управления рисками\", \"id\": \"68b51faa-c380-4f66-a831-617cf09853e0\"}, {\"type\": \"paragraph\", \"content\": \"С 1 сентября 2022 года вступило в силу Постановление Правительства РФ от 24.12.2021 № 2464 «О порядке обучения по охране труда и проверки знания требований охраны труда». Данный документ тесно связывает процесс обучения с оценкой рисков. Программы обучения теперь должны содержать практические вопросы, касающиеся именно тех опасностей, которые выявлены на конкретном рабочем месте. Руководитель службы ОТ обязан обеспечить, чтобы инструктажи на рабочем месте и программы обучения безопасным методам работ включали в себя информацию о выявленных рисках и мерах по их минимизации. Это позволяет сформировать у работника осознанное отношение к безопасности и навыки идентификации опасных ситуаций до начала выполнения работ.\", \"id\": \"ed71dd58-720a-4573-82ab-d8943eb2122a\"}, {\"type\": \"heading2\", \"content\": \"Мониторинг и контроль эффективности мер\", \"id\": \"9e400689-3e54-456b-82ac-e3d8873c17f5\"}, {\"type\": \"paragraph\", \"content\": \"Контроль реализации мер — это не просто проверка исполнения пунктов плана. Это оценка того, насколько принятые меры действительно снизили вероятность инцидента. В системе управления охраной труда должен быть выстроен многоуровневый контроль: оперативный (со стороны непосредственного руководителя), периодический (со стороны службы ОТ) и стратегический (анализ со стороны руководства). Для мониторинга используются опережающие индикаторы — показатели, которые сигнализируют о проблемах до того, как произойдет несчастный случай. Примерами таких показателей могут быть: количество выявленных небезопасных условий труда, процент выполнения графика технического обслуживания оборудования, результаты микротравматизма.\", \"id\": \"7a3a37c1-e6a9-4546-8382-ca512ea5ebe1\"}, {\"type\": \"list\", \"content\": \"Проведение поведенческих аудитов безопасности (ПАБ) для оценки соблюдения работниками инструкций.\\nРегулярная актуализация реестра опасностей (не реже одного раза в год или при изменениях в производстве).\\nКонтроль за исправностью технических средств защиты и систем коллективной защиты.\\nАнализ эффективности использования СИЗ и их соответствия реальным нагрузкам факторов производственной среды.\\nПроверка знаний работников в части их действий при возникновении аварийных ситуаций, связанных с конкретными рисками.\", \"id\": \"baeaa06a-1f0f-4701-96f9-2aa6c14afe5b\"}, {\"type\": \"heading2\", \"content\": \"Документирование результатов управления рисками\", \"id\": \"46c4be36-ac1d-414c-871f-198aeb91e820\"}, {\"type\": \"paragraph\", \"content\": \"Надлежащее документальное оформление процедур УПР необходимо не только для соответствия требованиям инспекции труда, но и для внутреннего анализа. Основной пакет документов включает в себя: Положение о порядке управления профрисками в организации, Реестр опасностей, Карты оценки профессиональных рисков на рабочих местах и План мероприятий по снижению уровней рисков. Карты должны быть доступны работникам для ознакомления, так как каждый сотрудник имеет право знать о рисках, которым он подвергается в процессе трудовой деятельности (ст. 216.2 ТК РФ).\", \"id\": \"b7a5e3f1-4855-4f81-9abb-9fd435a3e4ba\"}, {\"type\": \"paragraph\", \"content\": \"В заключение стоит отметить, что управление рисками — это динамический процесс. Руководитель службы охраны труда должен стимулировать вовлеченность персонала всех уровней в процесс выявления опасностей. Только когда рабочий на месте сообщает о неисправности блокировки или неудобстве использования защиты, а руководство оперативно выделяет ресурсы на устранение проблемы, система управления рисками становится «живой» и эффективной. Это минимизирует вероятность производственного травматизма и профессиональных заболеваний, обеспечивая устойчивое развитие предприятия.\", \"id\": \"3bad3027-d9d6-48c4-bc1c-c9a1f2e6f21d\"}, {\"type\": \"heading2\", \"content\": \"Взаимосвязь оценки рисков и СОУТ\", \"id\": \"b6a7409f-17db-4e43-af7d-e70ae3955b3b\"}, {\"type\": \"paragraph\", \"content\": \"Необходимо четко разграничивать Специальную оценку условий труда (СОУТ) по ФЗ-426 и оценку профессиональных рисков (ОПР). СОУТ оценивает воздействие вредных и опасных факторов производственной среды и трудового процесса, которые присутствуют постоянно или регулярно (шум, вибрация, освещенность). Оценка рисков же учитывает случайные события, которые могут произойти (падение с высоты, поражение током, наезд транспорта). Однако результаты СОУТ являются входными данными для ОПР: если по результатам СОУТ установлен класс условий труда 3.1 и выше, это автоматически означает наличие высокого риска по фактору воздействия данной вредности, что требует применения мер защиты органов дыхания, слуха или сокращения времени экспозиции.\", \"id\": \"5d41fe67-907e-4134-8230-d11711b64077\"}, {\"type\": \"quote\", \"content\": \"ГОСТ Р 12.0.010-2009 ССБТ. Системы управления охраной труда. Определение опасностей и оценка рисков: Эффективность любой системы управления безопасностью труда оценивается по ее способности своевременно идентифицировать изменения, которые могут привести к новым рискам, и внедрять соответствующие меры контроля.\", \"id\": \"20790a7c-2a6a-4132-b25e-d3d134f6972e\"}]", "495407fc-2dbd-47ea-8904-b7391902c008": "[{\"type\": \"heading1\", \"content\": \"Подготовка и проведение специальной оценки условий труда: пошаговое руководство для руководителя службы ОТ\", \"id\": \"bae9a5b5-ccd3-436b-902f-390cf695bdfe\"}, {\"type\": \"paragraph\", \"content\": \"Специальная оценка условий труда (СОУТ) представляет собой единый комплекс последовательно осуществляемых мероприятий по идентификации вредных и опасных факторов производственной среды и трудового процесса, а также оценке уровня их воздействия на работника с учетом эффективности применяемых средств индивидуальной и коллективной защиты. Проведение СОУТ является прямой обязанностью работодателя в соответствии со статьей 214 ТК РФ. Для руководителя службы охраны труда организация этого процесса — одна из ключевых задач, поскольку результаты оценки определяют объем компенсаций, вид медосмотров, нормы выдачи СИЗ и размеры страховых взносов в Социальный фонд России. Регулируется процедура Федеральным законом № 426-ФЗ «О специальной оценке условий труда» и методикой, утвержденной Приказом Минтруда России от 21.11.2023 № 817н (ранее — № 33н).\", \"id\": \"ef2a4e0a-0642-4ca5-9ec7-12401e4f6fd7\"}, {\"type\": \"heading2\", \"content\": \"Этап 1. Подготовительные мероприятия и создание комиссии\", \"id\": \"d27fc7db-5d68-4fb4-907c-b4b8ce8561f0\"}, {\"type\": \"paragraph\", \"content\": \"Процесс начинается с издания приказа о создании комиссии по проведению СОУТ и утверждения графика работ. Число членов комиссии должно быть нечетным, а в ее состав обязательно включаются представители работодателя, в том числе специалист по охране труда, и представители выборного органа первичной профсоюзной организации. Возглавляет комиссию, как правило, сам работодатель или его полномочный представитель. Важно понимать, что руководитель службы охраны труда играет роль модератора: он готовит проекты документов, координирует взаимодействие с экспертной организацией и контролирует соблюдение сроков согласно утвержденному графику.\", \"id\": \"54a29fae-2c4f-4303-bf6d-dab85f6df28b\"}, {\"type\": \"list\", \"content\": \"Издание приказа о создании комиссии (включает ФИО членов комиссии и сроки этапов).\\nУтверждение перечня рабочих мест, на которых будет проводиться СОУТ (с указанием аналогичных рабочих мест).\\nЗаключение договора с аккредитованной организацией, внесенной в реестр Минтруда.\\nСбор документов по оборудованию, материалам и сырью для экспертов.\", \"id\": \"720c29d6-7aa2-4479-9211-9288b6bf9dd9\"}, {\"type\": \"quote\", \"content\": \"Согласно ст. 9 ФЗ-426, при определении перечня рабочих мест, подлежащих специальной оценке условий труда, комиссия должна выделить аналогичные рабочие места — места, которые расположены в одном или нескольких однотипных производственных помещениях, оборудованных однотипными системами вентиляции, кондиционирования воздуха, отопления и освещения, на которых работники работают по одной и той же профессии, должности, специальности, выполняют одни и те же трудовые функции при однотипном технологическом процессе с использованием однотипного производственного оборудования.\", \"id\": \"c1f29bce-df3f-4adf-a1ba-f74366c26a8a\"}, {\"type\": \"heading2\", \"content\": \"Этап 2. Идентификация потенциально вредных факторов\", \"id\": \"6ab5272d-891b-4564-ad57-436553b01c59\"}, {\"type\": \"paragraph\", \"content\": \"Идентификация — это сопоставление имеющихся на рабочих местах факторов с классификатором, утвержденным Минтрудом России. Эту процедуру осуществляет эксперт организации, проводящей СОУТ, но результаты утверждает комиссия. Если вредные факторы не идентифицированы (то есть условия труда признаны допустимыми или оптимальными по результатам визуального осмотра и анализа документации), исследования и измерения не проводятся. В этом случае работодатель подает декларацию соответствия условий труда государственным нормативным требованиям охраны труда в территориальный орган Роструда. Для руководителя службы ОТ на этом этапе критически важно проследить, чтобы эксперт не «пропустил» скрытые факторы, которые объективно присутствуют на рабочих местах, так как это может привести к предписаниям инспекторов ГИТ в будущем.\", \"id\": \"93b59061-e626-4376-a0ed-13fb2f9f1f9d\"}, {\"type\": \"heading2\", \"content\": \"Этап 3. Проведение исследований и измерений\", \"id\": \"c2006be0-dc03-43b9-9ca0-4ecf70438075\"}, {\"type\": \"paragraph\", \"content\": \"В случае, если факторы были идентифицированы как потенциально вредные, экспертная лаборатория приступает к инструментальным замерам. Оценке подлежат физические факторы (шум, вибрация, электромагнитные поля, микроклимат, освещенность), химические факторы (смеси, вещества в воздухе рабочей зоны) и биологические факторы. Также оцениваются факторы трудового процесса — тяжесть и напряженность труда. Важно обеспечить работу оборудования в штатном режиме во время замеров, иначе результаты могут быть оспорены или признаны недостоверными. По результатам измерений эксперт устанавливает классы условий труда: оптимальный (1), допустимый (2), вредный (3.1, 3.2, 3.3, 3.4) или опасный (4).\", \"id\": \"eb4a1e8e-c2ba-4702-8d11-fa6b5224127b\"}, {\"type\": \"quote\", \"content\": \"Статья 14 ФЗ-426 устанавливает классификацию: вредными условиями труда (3 класс) являются условия труда, при которых уровни воздействия вредных и (или) опасных производственных факторов превышают нормативы и оказывают неблагоприятное воздействие на организм работника и (или) его потомство.\", \"id\": \"62fed64a-9b57-4573-a1af-f47411c495be\"}, {\"type\": \"heading2\", \"content\": \"Этап 4. Оформление результатов и отчетности\", \"id\": \"c2883067-de50-4d08-a864-032de25ed608\"}, {\"type\": \"paragraph\", \"content\": \"По итогам работы организация-исполнитель составляет отчет о проведении СОУТ. Руководитель службы охраны труда должен тщательно проверить проект отчета перед подписанием его членами комиссии. В отчет входят: сведения об организации-проводящей СОУТ, карты СОУТ на каждое рабочее место, протоколы измерений, сводная ведомость, перечень рекомендуемых мероприятий по улучшению условий труда. Особое внимание следует уделить картам СОУТ: в них должны быть четко прописаны гарантии и компенсации (доплаты не менее 4% по ст. 147 ТК РФ, дополнительный отпуск не менее 7 дней по ст. 117 ТК РФ, сокращенная рабочая неделя по ст. 92 ТК РФ), а также коды СИЗ. Подписанный всеми членами комиссии отчет должен быть утвержден председателем в течение 30 календарных дней с момента его направления организацией-исполнителем.\", \"id\": \"7ef6281e-080f-47db-ade0-73406e5bc804\"}, {\"type\": \"list\", \"content\": \"Подписание отчета всеми членами комиссии (член комиссии, не согласный с результатами, имеет право изложить в письменной форме мотивированное особое мнение).\\nОзнакомление работников с результатами СОУТ под роспись в картах в течение 30 календарных дней.\\nРазмещение сводных данных о результатах СОУТ на официальном сайте организации (при его наличии).\\nУведомление организации-исполнителя об утверждении отчета (в течение 3 рабочих дней) и передача копий необходимых документов.\", \"id\": \"7fe2e8fd-6868-45c4-81f7-bf08781ac655\"}, {\"type\": \"heading2\", \"content\": \"Этап 5. Декларирование соответствия и передача данных\", \"id\": \"a0b60ffa-9b52-461b-a7ab-27a1b8a0cb74\"}, {\"type\": \"paragraph\", \"content\": \"Работодатель обязан подать декларацию соответствия условий труда в ГИТ по местам, где вредные факторы не выявлены или условия труда признаны оптимальными/допустимыми. С 2021 года декларации стали бессрочными, при условии, что на рабочем месте не произошло несчастного случая или не было выявлено профзаболевания. Кроме того, организация, проводившая СОУТ, обязана передать сведения о результатах в Федеральную государственную информационную систему учета результатов проведения специальной оценки условий труда (ФГИС СОУТ). Руководитель службы ОТ должен убедиться, что отчет получил идентификационный номер в системе — без этого номера результаты СОУТ юридически не могут применяться для обоснования компенсаций или расходов на охрану труда.\", \"id\": \"09908f58-b78a-4d54-a270-0deb770ad6ac\"}, {\"type\": \"heading2\", \"content\": \"Результаты СОУТ напрямую влияют на другие процессы системы управления охраной труда (СУОТ). Согласно Постановлению Правительства РФ № 2464 «О порядке обучения по охране труда», информация о вредных факторах, зафиксированная в картах СОУТ, должна стать основой для программ инструктажей и программ обучения безопасным методам выполнения работ. Недопустимо, когда в карте СОУТ указан шум как вредный фактор, а в программе обучения по использованию СИЗ отсутствует раздел по защите органов слуха. Это прямое нарушение логики СУОТ и требований НПА.\", \"id\": \"31b1fed2-c6d6-47e5-88ee-3a8d82032917\"}, {\"type\": \"list\", \"content\": \"Использование результатов СОУТ для оценки профессиональных рисков.\\nКорректировка программ первичного и повторного инструктажей на рабочем месте.\\nОбоснование перечня должностей, подлежащих обязательным медицинским осмотрам (Приказ № 29н).\\nРазработка плана мероприятий по приведению условий труда в соответствие с нормативами.\", \"id\": \"3f852a1f-72b9-446f-beb6-8f281c917044\"}, {\"type\": \"paragraph\", \"content\": \"Завершая процесс, важно помнить о периодичности. Плановая СОУТ проводится не реже одного раза в пять лет. Однако руководитель службы ОТ должен инициировать внеплановую оценку, если введены новые рабочие места, изменился технологический процесс, состав используемого сырья или материалов, либо поступило предписание инспектора ГИТ. Нарушение порядка проведения СОУТ или ее непроведение влечет административную ответственность по ст. 5.27.1 КоАП РФ, что для юридических лиц может вылиться в штраф до 80 000 рублей за первое нарушение и до 200 000 рублей при повторном нарушении.\", \"id\": \"3d68a9f0-4392-4040-ae45-1efd2d0dba8a\"}, {\"type\": \"quote\", \"content\": \"В соответствии со статьей 17 Федерального закона № 426-ФЗ, внеплановая специальная оценка условий труда должна быть проведена в течение двенадцати месяцев со дня ввода в эксплуатацию вновь организованных рабочих мест или изменения технологического процесса, который может оказать влияние на уровень воздействия вредных факторов.\", \"id\": \"999476ff-2720-454e-9caa-017e401099a5\"}]", "9b78de26-9038-4c9d-b803-e647e4373476": "[{\"type\": \"heading1\", \"content\": \"Производственный контроль и гигиена труда в системе управления охраной труда\", \"id\": \"5617765b-5948-40c6-895c-1d4e1f7bc33a\"}, {\"type\": \"paragraph\", \"content\": \"Производственный контроль за соблюдением санитарных правил и выполнением санитарно-противоэпидемических (профилактических) мероприятий является фундаментальной обязанностью работодателя, закрепленной в статье 32 Федерального закона № 52-ФЗ «О санитарно-эпидемиологическом благополучии населения». Для руководителя службы охраны труда крайне важно понимать разграничение и точки соприкосновения между производственным контролем (ПК) и специальной оценкой условий труда (СОУТ). В то время как СОУТ направлена на установление классов условий труда и предоставление гарантий и компенсаций, производственный контроль нацелен на обеспечение динамического мониторинга безопасности производственной среды и предотвращение профессиональных заболеваний через системные лабораторные исследования и испытания.\", \"id\": \"4610f0a8-7959-40a7-8284-336bd1b4acfc\"}, {\"type\": \"heading2\", \"content\": \"Нормативно-правовое регулирование и роль СП 2.2.3670-20\", \"id\": \"cfa966c0-def4-479b-a9d2-2566390d3e1c\"}, {\"type\": \"paragraph\", \"content\": \"Основным документом, регламентирующим требования к условиям труда, являются санитарные правила СП 2.2.3670-20 «Санитарно-эпидемиологические требования к условиям труда». Согласно данным правилам, работодатель обязан осуществлять производственный контроль за соблюдением санитарных правил и гигиенических нормативов. Программа производственного контроля (ППК) утверждается руководителем организации и включает в себя перечень должностей работников, подлежащих медицинским осмотрам, объем и периодичность лабораторных исследований факторов производственной среды (химических, физических, биологических). Важно отметить, что объекты производственного контроля включают в себя не только рабочие места, но и производственные помещения, технологические процессы, оборудование, транспорт, а также готовую продукцию и отходы производства.\", \"id\": \"cba8ff67-7e6c-4e74-a14e-a28e89f5a0e3\"}, {\"type\": \"quote\", \"content\": \"Статья 214 ТК РФ: Работодатель обязан обеспечить создание и функционирование системы управления охраной труда, выполнение предписаний должностных лиц органов государственного контроля (надзора) и проведение производственного контроля.\", \"id\": \"909c0853-1e42-4cfc-891c-83b798a7cc68\"}, {\"type\": \"heading2\", \"content\": \"Составление программы производственного контроля (ППК)\", \"id\": \"08225bc7-3b22-42d2-b3ba-1e969a1ac01f\"}, {\"type\": \"paragraph\", \"content\": \"Разработка ППК — это процесс, требующий интеграции знаний о технологическом процессе и гигиенических нормативах. В структуру программы обязательно включаются сведения о наличии санитарно-эпидемиологических заключений, перечень официально изданных санитарных правил, графики лабораторных исследований. При определении точек замера следует руководствоваться требованиями гигиенических нормативов (СанПиН 1.2.3685-21). Частота замеров варьируется: например, контроль за содержанием вредных веществ в воздухе рабочей зоны для веществ I класса опасности должен проводиться не реже одного раза в 10 дней, тогда как параметры микроклимата могут измеряться дважды в год (в теплый и холодный периоды).\", \"id\": \"874f66ec-511f-4fa3-a97e-29138148d210\"}, {\"type\": \"list\", \"content\": \"Перечень определяемых вредных факторов производственной среды\\nТочки контроля и периодичность проведения лабораторных исследований\\nПеречень должностных лиц, несущих ответственность за организацию производственного контроля\\nМероприятия по обеспечению безопасности при работе с новыми видами продукции\\nФормы отчетности и журналы учета результатов контроля\", \"id\": \"61bbfdb6-3514-4f70-9324-69f1b6352a8d\"}, {\"type\": \"heading2\", \"content\": \"Взаимосвязь ПК и СОУТ: практическое применение результатов\", \"id\": \"8ab24c02-67bf-46a6-b66c-e643dab3671c\"}, {\"type\": \"paragraph\", \"content\": \"С 2021 года существенно изменились подходы к использованию результатов производственного контроля при проведении СОУТ. Федеральный закон № 426-ФЗ «О специальной оценке условий труда» позволяет использовать результаты лабораторных исследований, проведенных в рамках производственного контроля, для целей СОУТ, если они были выполнены аккредитованной испытательной лабораторией не ранее чем за шесть месяцев до проведения оценки. Это позволяет оптимизировать затраты предприятия и повысить достоверность идентификации вредных факторов. Руководитель службы охраны труда должен обеспечить синхронизацию графиков ПК и СОУТ для достижения максимальной эффективности управления рисками.\", \"id\": \"6bca90f6-a92e-4ba7-8485-f9855145c14e\"}, {\"type\": \"heading2\", \"content\": \"Гигиенические критерии оценки факторов рабочей среды\", \"id\": \"ebf35b0c-94d9-45fb-bccf-410512896ce3\"}, {\"type\": \"paragraph\", \"content\": \"Гигиена труда базируется на соблюдении предельно допустимых концентраций (ПДК) и предельно допустимых уровней (ПДУ). Основным документом здесь выступает СанПиН 1.2.3685-21 «Гигиенические нормативы и требования к обеспечению безопасности и (или) безвредности для человека факторов среды обитания». В данном НПА сведены воедино все нормативы: от химических веществ в воздухе до параметров освещенности, шума, вибрации и электромагнитных полей. Превышение данных нормативов по результатам производственного контроля обязывает работодателя немедленно принять меры по снижению воздействия (технические, организационные) или обеспечить использование адекватных средств индивидуальной защиты (СИЗ).\", \"id\": \"3d4d9c47-fc16-484d-bece-e1dc56d6bf66\"}, {\"type\": \"list\", \"content\": \"Химический фактор: контроль паров, газов и аэрозолей в зоне дыхания\\nФизические факторы: шум, инфразвук, ультразвук, вибрация общая и локальная\\nМикроклимат: температура, влажность, скорость движения воздуха, тепловое облучение\\nСветовая среда: освещенность рабочей поверхности, коэффициент пульсации\\nБиологический фактор: патогенные микроорганизмы, живые клетки и споры в воздухе\", \"id\": \"27d393be-a2cb-4ee1-803b-62e7eca50d13\"}, {\"type\": \"heading2\", \"content\": \"Обязательность медицинских осмотров и психоосвидетельствования\", \"id\": \"08acddc5-770e-4763-b2b0-536d1981a32d\"}, {\"type\": \"paragraph\", \"content\": \"Гигиена труда неразрывно связана с мониторингом состояния здоровья работников. Согласно Приказу Минздрава № 29н, основанием для направления на обязательный периодический медицинский осмотр являются наличие вредных производственных факторов на рабочем месте (по результатам СОУТ или ПК) или выполнение определенных видов работ. Роль службы охраны труда заключается в контроле за составлением списков лиц, подлежащих медосмотрам, и проверке соответствия этих списков актуальным данным производственного контроля. Важно помнить, что с 2023 года изменен порядок психиатрического освидетельствования (Приказ Минздрава № 342н), которое теперь проводится по конкретным видам деятельности, а не по факту наличия вредных условий труда.\", \"id\": \"5f897fa4-4a28-49e3-be37-c28deece680e\"}, {\"type\": \"heading2\", \"content\": \"Обучение по охране труда в контексте гигиены\", \"id\": \"d18c719b-9f39-4e7c-a4cd-0a8ecaacdadc\"}, {\"type\": \"paragraph\", \"content\": \"Постановление Правительства РФ № 2464 требует, чтобы работники были обучены методам безопасного выполнения работ и способам защиты от воздействия вредных факторов. Программы обучения должны включать разделы, посвященные правильному использованию СИЗ, мерам профилактики профзаболеваний и действиям при аварийных ситуациях, связанных с выбросом вредных веществ. Информация о результатах производственного контроля и фактических уровнях воздействия факторов среды должна доводиться до работников в обязательном порядке, что способствует формированию культуры осознанной безопасности.\", \"id\": \"5424230d-6618-4660-b113-222d499b52d8\"}, {\"type\": \"quote\", \"content\": \"Пункт 1.1 СП 2.2.3670-20: Настоящие санитарные правила устанавливают санитарно-эпидемиологические требования к обеспечению безопасных для человека условий труда. Соблюдение правил является обязательным для юридических лиц и индивидуальных предпринимателей.\", \"id\": \"555cb174-8746-4314-bbb8-b5c1d7f9cad4\"}, {\"type\": \"heading2\", \"content\": \"Профилактика профессиональных заболеваний\", \"id\": \"904e9366-66e2-4167-ba9c-ae92b1671421\"}, {\"type\": \"paragraph\", \"content\": \"Основная цель гигиены труда на предприятии — минимизация риска развития профпатологий. Руководитель службы ОТ должен инициировать внедрение риск-ориентированного подхода, где данные производственного контроля служат индикаторами для модернизации коллективных средств защиты (вентиляция, звукоизоляция, экранирование). В случае выявления предварительных признаков профзаболевания в ходе медосмотра, работодатель обязан реализовать комплекс оздоровительных мер, включая санаторно-курортное лечение, переобучение или перевод на другую работу в соответствии с медицинскими рекомендациями.\", \"id\": \"8059677a-3a56-4a4f-aa6a-ad080d489893\"}, {\"type\": \"list\", \"content\": \"Внедрение систем автоматизированного мониторинга воздушной среды\\nИспользование средств индивидуальной защиты органов дыхания с соответствующим фактором защиты\\nРегламентация перерывов для отдыха и обогрева в зависимости от категории тяжести работ\\nОсуществление контроля за режимами труда и отдыха в соответствии с ТК РФ\\nПропаганда здорового образа жизни и проведение производственной гимнастики\", \"id\": \"8cc9dc6a-9f73-4cb3-b7c4-73598fbacb7e\"}, {\"type\": \"heading2\", \"content\": \"Ответственность за нарушение требований производственного контроля\", \"id\": \"9d769f52-9433-4a65-acce-0e48e29cf54b\"}, {\"type\": \"paragraph\", \"content\": \"Несоблюдение законодательства в области обеспечения санитарно-эпидемиологического благополучия населения влечет за собой административную ответственность по статье 6.3 КоАП РФ. Однако, если выявленные нарушения касаются именно охраны труда (отсутствие замеров, непредоставление СИЗ), применяются санкции по статье 5.27.1 КоАП РФ, где штрафы для юридических лиц могут достигать 150 000 рублей за каждое правонарушение. В случае, если несоблюдение норм гигиены труда повлекло за собой групповое профзаболевание или смерть работника, предусмотрена уголовная ответственность для должностных лиц по статье 143 УК РФ.\", \"id\": \"40929398-2922-4914-b696-c125881d2d0a\"}, {\"type\": \"paragraph\", \"content\": \"В заключение подчеркнем: производственный контроль и гигиена труда — это не формальное ведение журналов, а живой механизм управления профессиональными рисками. Руководитель службы охраны труда, эффективно использующий инструменты лабораторного контроля, способен не только избежать штрафных санкций, но и создать реально безопасную рабочую среду, способствующую росту производительности труда и сохранению здоровья кадрового потенциала организации.\", \"id\": \"4a4c7315-1401-4c70-82c1-d8235a86ca2b\"}]", "0bc64c44-7f4b-469f-a61b-303a38a104ca": "[{\"type\": \"heading1\", \"content\": \"Урок: Классификация условий труда и гарантии работникам по результатам СОУТ\", \"id\": \"b87a9977-d92e-4665-a587-9cef5ff9f160\"}, {\"type\": \"paragraph\", \"content\": \"Специальная оценка условий труда (СОУТ) представляет собой единый комплекс последовательно осуществляемых мероприятий по идентификации вредных и опасных факторов производственной среды и трудового процесса, а также оценке уровня их воздействия на работника. Основным нормативным правовым актом, регулирующим этот процесс, является Федеральный закон от 28.12.2013 № 426-ФЗ «О специальной оценке условий труда». Результатом проведения СОУТ является установление классов и подклассов условий труда на конкретных рабочих местах, что напрямую влияет на объем обязанностей работодателя по предоставлению гарантий, компенсаций и уплате страховых взносов. Для руководителя службы охраны труда понимание классификации является критически важным, так как это фундамент системы управления охраной труда (СУОТ).\", \"id\": \"0ab3daf8-b300-4a5b-a63c-073cdfdee9bb\"}, {\"type\": \"heading2\", \"content\": \"Классификация условий труда: от оптимальных до опасных\", \"id\": \"974e3225-9139-4c8a-b08e-608327fa8fce\"}, {\"type\": \"paragraph\", \"content\": \"Согласно статье 14 Федерального закона № 426-ФЗ, условия труда по степени вредности и опасности подразделяются на четыре основных класса. Каждый из них характеризует уровень риска для здоровья работника и необходимость реализации мер защиты. Оптимальные условия труда (1 класс) — это условия, при которых воздействие вредных факторов отсутствует или не превышает уровни, принятые в качестве безопасных для населения, и создаются предпосылки для поддержания высокого уровня работоспособности. Допустимые условия труда (2 класс) характеризуются тем, что уровни воздействия факторов не превышают установленных нормативов, а организм работника восстанавливается в период регламентированного отдыха или к началу следующего рабочего дня.\", \"id\": \"399fb747-867a-4ddc-b8e0-bbe6ebc35c71\"}, {\"type\": \"paragraph\", \"content\": \"Вредные условия труда (3 класс) характеризуются наличием факторов, уровни воздействия которых превышают гигиенические нормативы. Этот класс подразделяется на четыре подкласса. Подкласс 3.1 (вредные условия труда 1 степени) — это условия, при которых функциональные изменения в организме восстанавливаются, как правило, при более длительном прерывании контакта с факторами. Подкласс 3.2 подразумевает возможность возникновения стойких функциональных изменений и развития начальных форм профзаболеваний без потери трудоспособности после длительной экспозиции (15 лет и более). Подкласс 3.3 характеризуется вероятностью развития болезней легкой и средней степени тяжести, а подкласс 3.4 — тяжелых форм профессиональных заболеваний. Самым критическим является 4 класс — опасные условия труда, при которых воздействие факторов в течение смены создает угрозу жизни или высокий риск развития острого профессионального заболевания.\", \"id\": \"cba55669-5a23-42c5-ba70-58c83f0c2186\"}, {\"type\": \"quote\", \"content\": \"Статья 14 ФЗ-426: «Условиями труда признается совокупность факторов производственной среды и трудового процесса, оказывающих влияние на работоспособность и здоровье работника. По результатам проведения специальной оценки условий труда устанавливаются классы (подклассы) условий труда на рабочих местах».\", \"id\": \"51d1dadf-3591-482b-9a7f-068187f83d9d\"}, {\"type\": \"heading2\", \"content\": \"Гарантии и компенсации: правовые основания и объемы\", \"id\": \"ea3bb0bd-5157-4e80-abd1-bf7de40f7766\"}, {\"type\": \"paragraph\", \"content\": \"Система компенсаций за работу во вредных условиях труда жестко регламентирована Трудовым кодексом РФ. Руководитель службы охраны труда обязан контролировать, чтобы в трудовых договорах работников были отражены все полагающиеся льготы по результатам актуальной карты СОУТ. Основными видами компенсаций являются: сокращенная продолжительность рабочего времени, ежегодный дополнительный оплачиваемый отпуск и повышенный размер оплаты труда. Важно отметить, что предоставление этих компенсаций начинается с момента внесения сведений о результатах СОУТ в Федеральную государственную информационную систему (ФГИС СОУТ), а не с даты утверждения отчета, что является частой точкой споров с проверяющими органами.\", \"id\": \"c80e5b31-7ae5-4db2-bcf8-df98fae2fb92\"}, {\"type\": \"list\", \"content\": \"Сокращенная продолжительность рабочего времени (ст. 92 ТК РФ): устанавливается для работников с классом условий труда 3.3 и 3.4, составляя не более 36 часов в неделю.\\nЕжегодный дополнительный оплачиваемый отпуск (ст. 117 ТК РФ): предоставляется работникам с классами 3.2, 3.3, 3.4 и 4; его минимальная продолжительность составляет 7 календарных дней.\\nПовышенная оплата труда (ст. 147 ТК РФ): положена всем работникам, условия труда которых отнесены к вредным (любой подкласс 3 класса) или опасным, в размере не менее 4% тарифной ставки или оклада.\\nОбеспечение молоком или другими равноценными пищевыми продуктами: регламентируется статьей 222 ТК РФ и приказом Минтруда № 291н для определенных вредных факторов.\\nПраво на досрочное назначение страховой пенсии: зависит от стажа работы по Спискам №1 и №2 при условии подтверждения вредного класса результатами СОУТ.\", \"id\": \"07291afc-4338-4edc-8123-af809cb88b0e\"}, {\"type\": \"heading2\", \"content\": \"Связь СОУТ с обучением и СИЗ по новым правилам\", \"id\": \"920d8e17-4f60-48a9-9f8e-af22007400ee\"}, {\"type\": \"paragraph\", \"content\": \"С 2022-2023 годов вступили в силу масштабные изменения в области обучения и обеспечения СИЗ. Постановление Правительства РФ № 2464 радикально изменило подход к обучению по охране труда. Теперь программы обучения напрямую зависят от выявленных в ходе СОУТ факторов и опасностей. Например, если на рабочем месте установлен класс 3.1 по шуму, работник в обязательном порядке должен проходить обучение по программе «Б» (обучение безопасным методам и приемам выполнения работ при воздействии вредных и (или) опасных производственных факторов), а в программу инструктажа на рабочем месте включаются конкретные замеры из протоколов СОУТ.\", \"id\": \"c552c66c-8540-4164-b25d-37cdd76a195f\"}, {\"type\": \"paragraph\", \"content\": \"Аналогичная связь прослеживается и с обеспечением СИЗ. Согласно Единым типовым нормам (ЕТН), использование которых стало обязательным, работодатель подбирает СИЗ не только по наименованию профессии, но и на основании выявленных опасностей и результатов СОУТ. Если карта СОУТ подтверждает превышение ПДК вредных веществ, выбор СИЗОД (средств индивидуальной защиты органов дыхания) должен основываться на конкретных концентрациях, указанных в протоколах измерений. Это требует от руководителя службы ОТ тесной интеграции результатов оценки рисков и СОУТ в единый матричный перечень СИЗ предприятия.\", \"id\": \"dd21523c-a33f-42d8-93d8-fd605f19699c\"}, {\"type\": \"heading2\", \"content\": \"Обязанности руководителя службы ОТ по итогам классификации\", \"id\": \"da140413-71f0-4aed-b5e1-54c45cc3ebd7\"}, {\"type\": \"list\", \"content\": \"Организация ознакомления работников с результатами СОУТ в течение 30 календарных дней под подпись.\\nКонтроль за внесением изменений в трудовые договоры в части условий труда и полагающихся гарантий.\\nРазработка плана мероприятий по улучшению условий труда для снижения классов вредности (например, модернизация вентиляции или замена оборудования).\\nПередача сведений в СФР (Социальный фонд России) для расчета дополнительных тарифов страховых взносов.\\nИспользование результатов СОУТ при формировании контингентов на периодические медицинские осмотры в соответствии с Приказом Минздрава № 29н.\", \"id\": \"33db58ba-8a35-4aa0-bd64-2b8abeceb50c\"}, {\"type\": \"quote\", \"content\": \"Постановление Правительства РФ от 24.12.2021 № 2464: «Обучению по охране труда подлежат работники, условия труда которых по результатам специальной оценки условий труда отнесены к вредным и (или) опасным условиям труда».\", \"id\": \"34f62a15-b2e9-405c-bcfa-1da51427524d\"}, {\"type\": \"heading2\", \"content\": \"Особенности декларирования соответствия условий труда\", \"id\": \"f4c5426a-9e25-46a7-a9f9-8c40be617ade\"}, {\"type\": \"paragraph\", \"content\": \"Для рабочих мест, на которых вредные и опасные производственные факторы не выявлены (классы 1 и 2), работодатель обязан подать декларацию соответствия условий труда государственным нормативным требованиям охраны труда. С 2021 года декларации стали бессрочными (за исключением случаев совершения правонарушений или несчастных случаев). Это значимая экономическая выгода для бизнеса, так как повторное проведение СОУТ на таких местах раз в пять лет больше не требуется, если условия труда не изменились и инцидентов не происходило. Однако руководитель службы охраны труда должен неукоснительно соблюдать процедуру подачи декларации: в течение 30 рабочих дней после утверждения отчета в территориальный орган Роструда.\", \"id\": \"2e896056-bc63-4cb5-b2be-eb4fca13eafc\"}, {\"type\": \"paragraph\", \"content\": \"Важно помнить о «подводных камнях». Если на задекларированном рабочем месте с работником произойдет несчастный случай по вине работодателя или у него будет выявлено профессиональное заболевание, действие декларации прекращается, и на данном рабочем месте должна быть проведена внеплановая СОУТ. Это стимулирует руководителя службы ОТ постоянно мониторить реальное состояние безопасности, не ограничиваясь формальными результатами предыдущей оценки.\", \"id\": \"0a30ea01-c8a0-495d-968e-778c4065732d\"}, {\"type\": \"heading2\", \"content\": \"Гигиена труда и производственный контроль\", \"id\": \"8b82b27d-58eb-4164-a14e-879367ef0991\"}, {\"type\": \"paragraph\", \"content\": \"Хотя СОУТ проводится раз в пять лет (или реже для декларируемых мест), гигиена труда требует непрерывного контроля. Производственный контроль, регламентируемый СП 1.1.1058-01, — это обязанность работодателя проводить регулярные лабораторные исследования факторов среды вне зависимости от СОУТ. Руководитель службы ОТ должен синхронизировать программу производственного контроля с картами СОУТ. Если СОУТ выявила подкласс 3.2 по вибрации, производственный контроль должен фиксировать уровни вибрации ежегодно или чаще, чтобы предупредить развитие вибрационной болезни и своевременно корректировать режимы труда и отдыха.\", \"id\": \"b975c4db-098f-472d-893c-694ef375046e\"}, {\"type\": \"list\", \"content\": \"Мониторинг соблюдения режимов труда и отдыха в зависимости от класса вредности.\\nКонтроль за исправностью систем коллективной защиты (вентиляции, экранирования).\\nУчет стажа работы во вредных условиях для целей управления профзаболеваниями.\\nВзаимодействие с отделом кадров по вопросу правильного наименования профессий из Списков.\", \"id\": \"88671730-9e7d-4275-be5a-0e22a5da1500\"}, {\"type\": \"paragraph\", \"content\": \"Подводя итог, можно сказать, что классификация условий труда — это не просто набор цифр в отчете СОУТ, а стратегический инструмент управления. От корректности установленного класса зависит финансовая стабильность предприятия (штрафы ГИТ, выплаты СФР) и защищенность самого руководителя службы охраны труда в случае юридических разбирательств. Грамотное использование результатов классификации позволяет не только предоставлять законные льготы, но и планомерно снижать профзаболеваемость через адресные профилактические меры.\", \"id\": \"dcd8f828-ff21-4b12-a088-e16314aa4182\"}]", "fb69340c-84af-44bc-96fd-477228ddf661": "[{\"type\": \"heading1\", \"content\": \"Организация системы обучения по охране труда в соответствии с Постановлением Правительства РФ №2464\", \"id\": \"ec76a49e-2083-4673-9964-418cbc66e1f8\"}, {\"type\": \"paragraph\", \"content\": \"С 1 сентября 2022 года алгоритм подготовки персонала по охране труда претерпел коренные изменения в связи с вступлением в силу Постановления Правительства РФ от 24.12.2021 № 2464. Для руководителя службы охраны труда это означает переход от формального контроля за 'корочками' к выстраиванию гибкой системы управления компетенциями. Новый порядок не просто актуализировал старые нормы, а предложил модульный подход, где каждый вид обучения привязан к конкретным рискам на рабочем месте и характеру выполняемых работ. Основная задача руководителя службы — правильно классифицировать персонал по группам обучения, определить формы проверки знаний и обеспечить своевременность внесения сведений в реестры Минтруда России.\", \"id\": \"b876bb1c-1f09-46b7-9596-b6fd325ae4cc\"}, {\"type\": \"heading2\", \"content\": \"Пять ключевых направлений обучения\", \"id\": \"4effd115-a7b8-42f5-a355-cd78885191db\"}, {\"type\": \"paragraph\", \"content\": \"Действующий порядок выделяет пять самостоятельных видов обучения, каждый из которых имеет свои требования к периодичности, контингенту и содержанию программ. Это обучение по оказанию первой помощи пострадавшим, обучение по использованию (применению) средств индивидуальной защиты (СИЗ), а также три подвида обучения требованиям охраны труда: по общим вопросам охраны труда и функционирования системы управления охраной труда (программа А), по безопасным методам и приемам выполнения работ при воздействии вредных и (или) опасных производственных факторов (программа Б) и по безопасным методам и приемам выполнения работ повышенной опасности (программа В). Разделение на эти потоки позволяет оптимизировать бюджет на обучение и сосредоточить внимание на наиболее опасных участках производства.\", \"id\": \"b034fdbb-d7bc-46c3-9e01-5edcf58f98d2\"}, {\"type\": \"quote\", \"content\": \"Статья 219 ТК РФ: Обучение по охране труда — это процесс получения работниками, в том числе руководителями организаций, а также работодателями — индивидуальными предпринимателями знаний, умений, навыков, позволяющих предотвращать случаи производственного травматизма и профессиональных заболеваний.\", \"id\": \"831d1363-1111-4bfd-bd6b-1b1fdba45b96\"}, {\"type\": \"heading2\", \"content\": \"Программы обучения: структура и периодичность\", \"id\": \"4b17481b-5291-49ce-a04c-eca09b08ce19\"}, {\"type\": \"list\", \"content\": \"Программа А (20 часов) — рассчитана в основном на руководителей и специалистов, организующих процессы. Периодичность — 1 раз в 3 года.\\nПрограмма Б (16 часов) — предназначена для рядовых работников и их руководителей, работающих во вредных условиях. Периодичность — 1 раз в 3 года.\\nПрограмма В (длительность устанавливается НПА) — специфическое обучение для работ повышенной опасности (высота, замкнутые пространства и др.). Периодичность — ежегодно.\\nПервая помощь (8 часов) — обязательна для рабочих, водителей и лиц, обучающих первой помощи. Периодичность — 1 раз в 3 года.\\nОбучение по СИЗ — требуется в случаях, когда применение СИЗ требует от работника практических навыков. Периодичность — 1 раз в 3 года.\", \"id\": \"624e2911-84f3-4409-9107-1db91339f411\"}, {\"type\": \"paragraph\", \"content\": \"Важным аспектом является возможность объединения программ. Если работнику требуется обучение по нескольким направлениям, суммарная продолжительность курса может быть уменьшена за счет исключения дублирующих тем, однако общая продолжительность объединенной программы (А+Б) не может быть менее 40 часов. Это требует от руководителя СОТ тщательного планирования учебных планов совместно с учебными центрами или внутренними комиссиями организации. Особое внимание следует уделять практической части: для программ СИЗ и первой помощи не менее 50% учебного времени должны занимать практические занятия.\", \"id\": \"4ccdcb18-9ea1-462d-9b14-a63669ad7793\"}, {\"type\": \"heading2\", \"content\": \"Инструктажи по охране труда: новые требования\", \"id\": \"397c9b5b-5c8e-4e05-910d-b700bb0175cd\"}, {\"type\": \"paragraph\", \"content\": \"Механизм проведения инструктажей также был пересмотрен. Теперь Постановление № 2464 четко разграничивает вводный инструктаж, инструктаж на рабочем месте (первичный, повторный, внеплановый) и целевой инструктаж. Важное нововведение — возможность освобождения отдельных категорий офисных работников от первичного и повторного инструктажей на рабочем месте. Это допустимо, если их деятельность связана исключительно с использованием офисной оргтехники и бытовой техники, а условия труда по результатам СОУТ признаны оптимальными или допустимыми. Однако решение об освобождении должно быть закреплено локальным нормативным актом работодателя с учетом мнения профсоюза.\", \"id\": \"86b2ecb1-b8da-4a13-91b2-f6e1dbbd8726\"}, {\"type\": \"list\", \"content\": \"Вводный инструктаж — проводится до начала выполнения трудовых функций всеми принимаемыми сотрудниками.\\nИнструктаж на рабочем месте — проводится непосредственным руководителем, прошедшим обучение по охране труда.\\nЦелевой инструктаж — проводится перед работами повышенной опасности, на которые оформляется наряд-допуск, или при ликвидации последствий ЧС.\\nВнеплановый инструктаж — инициируется при изменениях в законодательстве, замене оборудования или по требованию ГИТ.\", \"id\": \"fa51f5df-46e5-4831-b1e7-362a96ac33d6\"}, {\"type\": \"heading2\", \"content\": \"Стажировка на рабочем месте\", \"id\": \"18b05dbd-2aae-433b-b7e3-f55dee570f24\"}, {\"type\": \"paragraph\", \"content\": \"Стажировка стала обязательным этапом для работников, выполняющих работы повышенной опасности, а также для тех, чья профессия определена работодателем как требующая практического освоения навыков. Продолжительность стажировки должна составлять не менее двух смен. Руководитель службы охраны труда должен обеспечить наличие программы стажировки для каждой должности и назначение опытных наставников. Окончание стажировки оформляется записью в журнале или иным документом, подтверждающим допуск к самостоятельной работе. Важно помнить, что стажировка проводится только после прохождения обучения и успешной проверки знаний.\", \"id\": \"b540f265-ada4-4350-a81a-2726005796b1\"}, {\"type\": \"heading2\", \"content\": \"Организация проверки знаний внутри организации\", \"id\": \"92cb090b-dd50-4fcf-acf3-76ce6ff2a430\"}, {\"type\": \"paragraph\", \"content\": \"Для проведения проверки знаний внутри компании работодатель обязан создать комиссию (не менее 3 человек). Ключевое требование — члены комиссии сами должны быть обучены в аккредитованных учебных центрах. Постановление № 2464 устанавливает строгие требования к материально-технической базе для внутреннего обучения: наличие учебных помещений, тренажеров для первой помощи и актуальных учебных пособий. Если организация не способна обеспечить качественную практическую отработку навыков, обучение должно быть передано на аутсорсинг в специализированные образовательные организации.\", \"id\": \"0d08c086-c8ef-4c06-a870-d2b09aca003c\"}, {\"type\": \"quote\", \"content\": \"Пункт 96 Постановления №2464: Работодатель, проводящий обучение работников требованиям охраны труда, обучение по оказанию первой помощи пострадавшим, обучение по использованию (применению) средств индивидуальной защиты, должен иметь материально-техническую базу, учебно-методическое обеспечение и штатных специалистов или лиц, привлекаемых по договорам.\", \"id\": \"add7c084-d3c5-4bd0-a264-14dc9d5b3b69\"}, {\"type\": \"heading2\", \"content\": \"Реестры Минтруда и цифровая трансформация\", \"id\": \"7d91a591-aa37-4e51-a8a2-ad0b069c72f0\"}, {\"type\": \"paragraph\", \"content\": \"Одним из самых трудоемких нововведений стала необходимость работы с реестрами Минтруда. С 1 марта 2023 года работодатели, желающие обучать своих сотрудников самостоятельно, обязаны пройти регистрацию в Личном кабинете по охране труда (ЛКОТ) и предоставить уведомление об осуществлении деятельности по обучению. После каждой проверки знаний сведения о работниках (ФИО, СНИЛС, программа, результат) должны вноситься в Реестр обученных лиц. Без присвоения регистрационного номера протоколу проверки знаний обучение считается недействительным. Это требует от руководителя СОТ и IT-службы синхронизации внутренних учетных систем с государственными цифровыми сервисами.\", \"id\": \"1fcc5c1b-3564-423a-9c1e-25ede1afa54d\"}, {\"type\": \"heading2\", \"content\": \"Планирование и документирование: алгоритм действий\", \"id\": \"89be4a94-d1de-4cdb-8d81-41f42432fcab\"}, {\"type\": \"list\", \"content\": \"Шаг 1. Актуализация перечня должностей и профессий, подлежащих разным видам обучения.\\nШаг 2. Разработка и утверждение программ обучения, адаптированных под специфику рисков предприятия.\\nШаг 3. Издание приказа о назначении ответственных за инструктажи и стажировки.\\nШаг 4. Формирование комиссии по проверке знаний и их направление в УЦ.\\nШаг 5. Регистрация личного кабинета в системе Минтруда и уведомление о намерении обучать самостоятельно.\\nШаг 6. Проведение обучения, оформление протоколов и их выгрузка в федеральный реестр.\", \"id\": \"d7db6b81-c6bc-4854-8f8f-b1001b6bde8f\"}, {\"type\": \"paragraph\", \"content\": \"Завершая обзор, следует отметить, что несоблюдение порядка обучения влечет серьезные административные штрафы по ч. 3 ст. 5.27.1 КоАП РФ (до 130 000 рублей за каждого необученного сотрудника). Однако главная цель реформы № 2464 — не наполнение реестров, а формирование реальных навыков безопасности. Руководитель службы охраны труда должен выступать методологом, который превращает скучные лекции в эффективный инструмент снижения травматизма, используя риск-ориентированный подход и современные образовательные методики.\", \"id\": \"0986ecb0-a4a9-499e-8182-6ee745c7d329\"}, {\"type\": \"heading2\", \"content\": \"Заключение\", \"id\": \"05a29a4a-f316-4761-9c3f-4d68dd221ed0\"}, {\"type\": \"paragraph\", \"content\": \"Новое законодательство дает работодателю больше свободы в выборе форм обучения, но накладывает колоссальную ответственность за прозрачность этого процесса. Роль руководителя СОТ трансформируется из контролера в архитектора образовательной среды. Знание нюансов Постановления № 2464 позволяет не только избежать предписаний инспекции труда, но и создать прозрачную систему допуска персонала к работам, где каждый сотрудник четко понимает риски своего рабочего места и владеет приемами самоспасения.\", \"id\": \"9b307e86-6305-465e-baa2-4195f526f9f3\"}]", "a86d6d07-dffa-4c42-84eb-8acb4c16e760": "[{\"type\": \"heading1\", \"content\": \"Инструктажи по охране труда: виды и порядок проведения в соответствии с Постановлением Правительства РФ № 2464\", \"id\": \"c3f1433e-677c-4e6b-ac5d-f9412cce287e\"}, {\"type\": \"paragraph\", \"content\": \"Организация процесса обучения и проверки знаний требований охраны труда является одной из ключевых обязанностей работодателя, закрепленной в статье 214 Трудового кодекса РФ. В структуре профессиональной переподготовки руководителей служб ОТ понимание механики проведения инструктажей занимает центральное место, так как именно этот процесс является наиболее массовым и контролируемым со стороны надзорных органов. С 1 сентября 2022 года основным нормативным правовым актом, регулирующим данный вопрос, является Постановление Правительства РФ от 24.12.2021 № 2464 «О порядке обучения по охране труда и проверки знания требований охраны труда». Этот документ радикально изменил подходы к документированию и периодичности процедур, внедрив риск-ориентированный подход в повседневную практику специалиста по охране труда.\", \"id\": \"d66ead67-cc31-46c0-97d2-11a164367006\"}, {\"type\": \"heading2\", \"content\": \"Классификация инструктажей по охране труда\", \"id\": \"bf07ceea-78d1-4a31-9d35-c9785eff6324\"}, {\"type\": \"paragraph\", \"content\": \"В современной системе управления охраной труда (СУОТ) выделяют несколько видов инструктажей, каждый из которых имеет строго целевое назначение и временные рамки проведения. К ним относятся: вводный инструктаж, инструктаж на рабочем месте (включающий первичный, повторный и внеплановый) и целевой инструктаж. Руководитель службы ОТ должен четко разграничивать эти виды деятельности, так как ошибка в квалификации мероприятия ведет к признанию обучения недействительным, что влечет административную ответственность по статье 5.27.1 КоАП РФ. Важно понимать, что инструктаж — это не просто формальная подпись в журнале, а процесс передачи знаний о безопасных методах выполнения работ и существующих на рабочем месте рисках, выявленных в ходе специальной оценки условий труда (СОУТ) и оценки профессиональных рисков (ОПР).\", \"id\": \"2068be2d-e6ee-4e18-a257-119a7cb7c1a7\"}, {\"type\": \"heading2\", \"content\": \"Вводный инструктаж: порядок и субъектный состав\", \"id\": \"2570990c-673d-443c-b6ca-73b39966322b\"}, {\"type\": \"paragraph\", \"content\": \"Вводный инструктаж проводится до начала выполнения любых трудовых функций в организации. Согласно пункту 10 Правил № 2464, данному виду обучения подлежат все вновь принимаемые работники, командированные лица, работники сторонних организаций, выполняющие работы на подконтрольной территории, а также лица, проходящие производственную практику. Программу вводного инструктажа разрабатывает руководитель службы ОТ (или специалист по ОТ), а утверждает работодатель с учетом мнения профсоюза. Программа должна базироваться на специфике деятельности предприятия и включать общие сведения об организации, правила внутреннего трудового распорядка, основы оказания первой помощи и действия при возникновении чрезвычайных ситуаций.\", \"id\": \"a03a2dd7-6b31-4168-b907-fa91f85cb04d\"}, {\"type\": \"quote\", \"content\": \"Вводный инструктаж по охране труда проводится по программе вводного инструктажа. Программа вводного инструктажа разрабатывается на основе примерного перечня тем согласно приложению № 1 к Правилам № 2464. Проведение вводного инструктажа осуществляется специалистом по охране труда или иным уполномоченным работником организации, на которого приказом работодателя возложены эти обязанности. При отсутствии у работодателя службы охраны труда или специалиста по охране труда проводить вводный инструктаж может работодатель — индивидуальный предприниматель лично, руководитель организации, другой уполномоченный работодателем работник либо организация или индивидуальный предприниматель, оказывающие услуги в области охраны труда, привлекаемые работодателем по гражданско-правовому договору.\", \"id\": \"cc79e501-9762-4f29-8d46-23143d062012\"}, {\"type\": \"heading2\", \"content\": \"Инструктажи на рабочем месте: от первичного до внепланового\", \"id\": \"99fd2cb0-2451-44c4-b716-1f5acfca26d8\"}, {\"type\": \"paragraph\", \"content\": \"Инструктажи на рабочем месте проводятся непосредственно руководителями подразделений (мастерами, прорабами, начальниками отделов), прошедшими обучение в аккредитованных учебных центрах. Первичный инструктаж проводится до начала самостоятельной работы сотрудника. Его цель — ознакомить работника с конкретным оборудованием, технологическим процессом и опасными факторами на его рабочем месте. Повторный инструктаж проводится для закрепления знаний не реже одного раза в 6 месяцев. Однако для определенных категорий работников работодатель может установить более частую периодичность в локальных нормативных актах. Важным нововведением является право работодателя освободить определенных офисных сотрудников от прохождения инструктажа на рабочем месте, если их труд связан исключительно с эксплуатацией ПЭВМ и офисной оргтехники, а условия труда по результатам СОУТ признаны оптимальными или допустимыми.\", \"id\": \"4c735647-b5e0-4104-b8cf-db8cd32db723\"}, {\"type\": \"list\", \"content\": \"Внеплановый инструктаж проводится в строго определенных законом случаях:\\nИзменение федеральных законов или иных НПА, содержащих государственные нормативные требования ОТ.\\nИзменение технологического процесса, замена оборудования или сырья, влияющих на безопасность труда.\\nНарушение работником требований охраны труда, если это создало реальную угрозу наступления тяжких последствий.\\nПерерыв в работе сотрудника более чем на 60 календарных дней.\\nПо требованию должностных лиц ГИТ при выявлении нарушений.\\nПри выявлении дополнительных производственных факторов и источников риска в рамках процедуры ОПР.\", \"id\": \"a7482727-200f-4cd2-b722-f9c463ebcafb\"}, {\"type\": \"heading2\", \"content\": \"Целевой инструктаж: специфика и условия применения\", \"id\": \"90a4bd52-6644-49b4-bb03-00a1b2e539ef\"}, {\"type\": \"paragraph\", \"content\": \"Целевой инструктаж выделяется в отдельную категорию, так как он привязан к конкретному событию или нестандартной задаче. Он проводится перед выполнением работ, не связанных с прямыми должностными обязанностями (например, погрузочно-разгрузочные работы, уборка территории), перед работами по ликвидации последствий аварий или стихийных бедствий, а также перед работами, на которые оформляется наряд-допуск. Руководитель службы охраны труда должен контролировать, чтобы целевой инструктаж сопровождался четким разъяснением мер безопасности, специфичных для данной разовой задачи. В условиях современных строек и производств целевой инструктаж часто совмещается с выдачей наряда-допуска, что требует синхронизации записей в соответствующих реестрах и журналах.\", \"id\": \"a105b40e-5bde-449a-9c27-ebad4ea4620a\"}, {\"type\": \"heading2\", \"content\": \"Документирование и регистрация результатов\", \"id\": \"9d2f7348-38c9-4566-ba85-5183e4ffd08c\"}, {\"type\": \"paragraph\", \"content\": \"Одним из самых существенных изменений, внесенных Постановлением № 2464, стал отход от жестко установленных форм журналов инструктажей. Работодатель теперь вправе самостоятельно определять порядок регистрации инструктажей: это могут быть журналы, личные карточки обучения или электронные реестры (при условии использования электронной подписи). Однако закон устанавливает минимальный перечень информации, которая должна быть зафиксирована. К ней относятся: дата проведения, ФИО инструктируемого и инструктирующего, их подписи, наименование программы или вида инструктажа. Для внепланового инструктажа обязательно указывается причина его проведения.\", \"id\": \"d2b32320-2539-421d-96b4-f946f3fbd2dc\"}, {\"type\": \"list\", \"content\": \"Реестр регистрации инструктажа обязательно должен содержать:\\nДата проведения инструктажа;\\nФамилия, имя, отчество работника, прошедшего инструктаж;\\nПрофессия (должность) работника;\\nЧисло, месяц, год рождения работника;\\nВид инструктажа по охране труда;\\nПричина проведения инструктажа (для внепланового или целевого);\\nНаименование локального акта (программы), в объеме которой проведен инструктаж;\\nФамилия, имя, отчество, должность работника, проводившего инструктаж;\\nПодпись работника, проводившего инструктаж;\\nПодпись работника, прошедшего инструктаж.\", \"id\": \"ecc60e63-721c-4629-a61d-26f8081c9eb0\"}, {\"type\": \"heading2\", \"content\": \"Проверка знания по итогам инструктажа\", \"id\": \"4a1307e8-8c12-442c-b967-af7db0b50d51\"}, {\"type\": \"paragraph\", \"content\": \"Любой инструктаж должен завершаться устной проверкой знаний. Это требование пункта 23 Правил № 2464. Инструктор обязан убедиться, что работник усвоил материал, понимает алгоритм безопасного выполнения работ и знает, как действовать в аварийной ситуации. В случае неудовлетворительного результата проверки сотрудник не допускается к самостоятельной работе и обязан пройти инструктаж повторно в сроки, установленные работодателем. Руководитель службы ОТ должен разработать контрольные вопросы или чек-листы для руководителей подразделений, чтобы стандартизировать качество проверки знаний на местах и исключить формализм в обучении.\", \"id\": \"9cbae2cc-4ee7-4b3a-8098-f43612a666ba\"}, {\"type\": \"quote\", \"content\": \"Статья 214 ТК РФ: Работодатель обязан обеспечить обучение безопасным методам и приемам выполнения работ и оказанию первой помощи пострадавшим на производстве, проведение инструктажа по охране труда, стажировки на рабочем месте и проверки знания требований охраны труда.\", \"id\": \"8821f2ec-645b-4185-926c-8cde9e4c47bb\"}, {\"type\": \"heading2\", \"content\": \"Роль руководителя службы ОТ в организации процесса\", \"id\": \"85caaf4c-c547-4d25-a6ea-e2a16a16fbbd\"}, {\"type\": \"paragraph\", \"content\": \"Для слушателей курса профессиональной переподготовки важно осознать, что руководитель службы охраны труда выполняет функцию методолога и контролера. Он не должен лично проводить все инструктажи на рабочем месте — это задача линейных руководителей. Его задача — выстроить систему: разработать качественные программы с учетом ГОСТ 12.0.004-2015, обучить инструкторов методам донесения информации, организовать своевременное обновление материалов при изменении законодательства. Особое внимание следует уделять интеграции результатов СОУТ и ОПР в программы инструктажей. Если в карте СОУТ указан повышенный уровень шума, а в программе инструктажа об этом нет ни слова, такая система СУОТ будет признана неэффективной при первой же проверке.\", \"id\": \"7832942d-5b19-4ce8-bfbc-201c2e935098\"}, {\"type\": \"paragraph\", \"content\": \"В заключении стоит отметить, что автоматизация учета инструктажей становится мировым трендом. Использование специализированного ПО позволяет вовремя уведомлять руководителей о необходимости проведения повторных или внеплановых мероприятий. Как будущий руководитель службы ОТ, вы должны стремиться к прозрачности этого процесса, обеспечивая не только юридическую безопасность организации через наличие подписей, но и фактическую безопасность работников через качественное информирование о рисках. Помните, что грамотно проведенный инструктаж — это первый и самый важный барьер на пути производственного травматизма.\", \"id\": \"21d52ece-acec-4475-ba2b-d7e9fb133619\"}]", "c5e4958d-2318-4835-8b68-a98a32bb0456": "[{\"type\": \"heading1\", \"content\": \"Организация медицинских осмотров и обязательного психиатрического освидетельствования работников\", \"id\": \"138d6322-9cc5-4d0f-9f6c-7671306a20d0\"}, {\"type\": \"paragraph\", \"content\": \"В системе управления охраной труда (СУОТ) медицинские осмотры являются ключевым элементом профилактики профессиональных заболеваний и производственного травматизма. Руководитель службы охраны труда обязан выстроить процесс так, чтобы ни один сотрудник, имеющий медицинские противопоказания, не был допущен к выполнению работ. Это не только требование безопасности, но и жесткое условие законодательства. Основу правового регулирования в этой сфере составляют статьи 213, 214 и 220 Трудового кодекса РФ, а также специфические подзаконные акты, такие как Приказ Минздрава России от 28.01.2021 № 29н, утвердивший порядок проведения осмотров, и Постановление Правительства РФ от 30.05.2022 № 1027, касающееся психиатрического освидетельствования.\", \"id\": \"b28d162e-c885-45e2-af84-27f53e7106ee\"}, {\"type\": \"heading2\", \"content\": \"Виды медицинских осмотров и их периодичность\", \"id\": \"9f6a44d8-2040-428b-9d51-9f5793d17482\"}, {\"type\": \"paragraph\", \"content\": \"Законодательство выделяет три основных типа осмотров, за организацию которых отвечает работодатель. Первый — предварительный медицинский осмотр. Он проводится при приеме на работу и позволяет определить, соответствует ли состояние здоровья соискателя требованиям конкретной должности. Если по результатам осмотра выявлены противопоказания, работодатель обязан отказать в трудоустройстве. Второй тип — периодические осмотры. Они проводятся с определенной частотой (обычно раз в год или раз в два года) для сотрудников, уже состоящих в штате. Цель — динамическое наблюдение за состоянием здоровья и выявление ранних признаков профзаболеваний. Третий тип — предсменные, предрейсовые (а также послесменные и послерейсовые) осмотры, обязательные для водителей и работников определенных опасных производств.\", \"id\": \"378433de-0ce1-487a-942a-4dad4cf83d37\"}, {\"type\": \"list\", \"content\": \"Предварительные (при поступлении на работу)\\nПериодические (в течение трудовой деятельности)\\nВнеочередные (по медицинским рекомендациям или после болезни)\\nПредсменные и послесменные (для отдельных категорий)\\nХимико-токсикологические исследования (для авиаперсонала, ведомственной охраны и др.)\", \"id\": \"a3ed957f-184e-4cda-bd6f-b73969090b84\"}, {\"type\": \"paragraph\", \"content\": \"Важно отметить, что с 2021 года основания для направления на медосмотр существенно изменились. Теперь мы ориентируемся не только на наличие вредных факторов, превышающих ПДК и ПДУ по результатам СОУТ, но и на сам факт наличия определенных работ (например, работа на высоте, управление транспортным средством) вне зависимости от класса условий труда. Это требует от руководителя службы охраны труда предельной внимательности при составлении Списка лиц, подлежащих медицинским осмотрам.\", \"id\": \"195d71e3-2641-4f46-a962-463e50278495\"}, {\"type\": \"quote\", \"content\": \"Статья 220 ТК РФ: Работники, занятые на работах с вредными и (или) опасными условиями труда (в том числе на подземных работах), а также на работах, связанных с движением транспорта, проходят обязательные предварительные и периодические медицинские осмотры для определения пригодности этих работников для выполнения поручаемой работы и предупреждения профессиональных заболеваний.\", \"id\": \"ec336ec4-2da2-4121-b5c1-372ed042dce5\"}, {\"type\": \"heading2\", \"content\": \"Алгоритм организации периодического медосмотра\", \"id\": \"4917992b-ea41-4f7a-91e4-5999a10a5efd\"}, {\"type\": \"paragraph\", \"content\": \"Процедура организации осмотра — это многоступенчатый процесс. Начинается он с формирования Списка лиц. В него включаются профессии и должности работников, которые подвергаются воздействию вредных факторов, поименованных в Приложении к Приказу № 29н. Список должен быть утвержден руководителем организации и направлен в территориальный орган Роспотребнадзора в десятидневный срок (если организация относится к отдельным отраслям, например, пищевая промышленность или водопроводные сооружения). После этого составляется Поименный список работников. В нем указываются ФИО, стаж работы в данной должности и конкретные вредные факторы. Этот документ передается в медицинскую организацию не позднее чем за два месяца до согласованной даты начала осмотра.\", \"id\": \"05011217-cff9-4206-a57c-9cd298dad60a\"}, {\"type\": \"list\", \"content\": \"Заключение договора с лицензированной медицинской организацией\\nРазработка и утверждение Списка лиц (по должностям)\\nРазработка Поименного списка работников (с указанием ФИО)\\nСогласование с медорганизацией календарного плана\\nОзнакомление работников с графиком осмотров за 10 дней\\nВыдача направлений на бумажном носителе или в электронном виде\", \"id\": \"5b88354f-ee85-48d2-8083-350ccf0e27e2\"}, {\"type\": \"paragraph\", \"content\": \"Медицинская организация на основании поименного списка составляет календарный план, который утверждается обеими сторонами. Руководитель службы ОТ должен проконтролировать, чтобы работники были ознакомлены с планом под подпись. После прохождения комиссии медорганизация выдает Заключение по каждому работнику, а по итогам всего осмотра составляется Заключительный акт. Этот акт — критически важный документ: в нем фиксируются группы здоровья, выявленные подозрения на профзаболевания и рекомендации по оздоровлению. Акт подписывается врачом, представителем работодателя и Роспотребнадзора.\", \"id\": \"4463994b-dc1b-459d-b567-e0c0f59d9132\"}, {\"type\": \"heading2\", \"content\": \"Психиатрическое освидетельствование: новые правила\", \"id\": \"5895431c-c84c-46b7-bb89-d75ec5850619\"}, {\"type\": \"paragraph\", \"content\": \"С 1 сентября 2022 года вступил в силу Приказ Минздрава России № 342н, который радикально изменил порядок психиатрического освидетельствования. Ранее его проходили почти все «вредники» раз в 5 лет. Теперь список видов деятельности сокращен, а периодичность «раз в 5 лет» упразднена. Освидетельствование проводится только по конкретным видам деятельности, указанным в приложении к приказу: например, деятельность, связанная с управлением транспортом, производством взрывчатых материалов, оборотом оружия, управлением атомными энергоустановками, или работа в сфере педагогики и присмотра за детьми.\", \"id\": \"40da131a-3873-4a9f-916c-a21b6a50b176\"}, {\"type\": \"quote\", \"content\": \"Постановление Правительства РФ № 1027: Психиатрическое освидетельствование проводится врачебной комиссией, создаваемой органом исполнительной власти субъекта РФ в сфере здравоохранения. Целью является подтверждение отсутствия психиатрических противопоказаний к выполнению отдельных видов деятельности.\", \"id\": \"4501d90d-cd98-48a9-a909-6175d3915353\"}, {\"type\": \"paragraph\", \"content\": \"Ключевое отличие психиатрического освидетельствования от медосмотра заключается в его полной автономности. Это отдельная процедура, проводимая врачебной комиссией. Если работник выполняет вид деятельности из списка 342н, он сначала проходит психиатра, получает заключение, и только потом идет на основной медицинский осмотр. При этом врачебная комиссия имеет право запрашивать дополнительные сведения о состоянии здоровья обследуемого в других медицинских организациях, о чем работник уведомляется официально.\", \"id\": \"674778bc-1b24-4d31-97ed-72d2fffc7cc2\"}, {\"type\": \"heading2\", \"content\": \"Взаимосвязь с СОУТ и оценкой рисков\", \"id\": \"84a68c84-4c87-4cea-aaed-ba7701628abe\"}, {\"type\": \"paragraph\", \"content\": \"Результаты Специальной оценки условий труда (СОУТ) по ФЗ-426 являются фундаментом для назначения медосмотров. В картах СОУТ прописываются вредные факторы (химические, биологические, физические), которые служат основанием для медосмотра по пунктам Приказа 29н. Однако руководитель службы ОТ должен помнить, что отсутствие превышений (класс условий труда 2.0) не всегда освобождает от медосмотра. Если фактор относится к аллергенам, канцерогенам, веществам, опасным для репродуктивного здоровья, или если работа поименована в разделе VI Приказа 29н, медосмотр обязателен вне зависимости от концентрации фактора.\", \"id\": \"21b7ca06-cb8b-44ea-bf4e-2cec35cc5ba5\"}, {\"type\": \"list\", \"content\": \"Класс 3.1 и выше — безусловное основание для медосмотра по фактору\\nКласс 2.0 — медосмотр нужен только по специфическим факторам (химия-канцерогены и др.)\\nРаботы на высоте и в замкнутых пространствах — осмотр обязателен\\nРаботы в районах Крайнего Севера — осмотр обязателен для всех\", \"id\": \"98e158b5-9392-4e70-9332-8f18bfcd959f\"}, {\"type\": \"paragraph\", \"content\": \"Оценка профессиональных рисков также влияет на объем обследований. Если при оценке рисков выявлена высокая вероятность травматизации из-за состояния здоровья (например, риск эпилептического припадка у оператора крана), служба ОТ может инициировать внеочередные осмотры, обосновывая это требованиями ТК РФ по обеспечению безопасности.\", \"id\": \"26aa5e39-1fd4-4a57-850a-1db8047ef553\"}, {\"type\": \"heading2\", \"content\": \"Ответственность и хранение документов\", \"id\": \"d9f60f8f-c499-4c41-9294-962fdd9adcaf\"}, {\"type\": \"paragraph\", \"content\": \"Допуск к работе без прохождения обязательного медосмотра или психиатрического освидетельствования является грубым нарушением. Согласно КоАП РФ (ст. 5.27.1, ч. 3), штраф за каждого такого работника может составлять до 130 000 рублей для юридического лица. Руководитель службы ОТ должен обеспечить хранение Заключительных актов в течение 50 лет (согласно переченю архивных документов). Направления на медосмотры также должны учитываться в специальном журнале, что подтверждает выполнение работодателем своих обязанностей по организации процесса.\", \"id\": \"bc037144-92a4-4202-a3f6-7281cf31ed53\"}, {\"type\": \"paragraph\", \"content\": \"В завершение подчеркнем: эффективная система медосмотров — это не формальный сбор справок, а инструмент управления здоровьем персонала. Для руководителя службы ОТ важно наладить взаимодействие с отделом кадров и бухгалтерией, чтобы обеспечить своевременную оплату услуг клиник и недопущение вовремя не прошедших осмотр сотрудников к рабочим местам.\", \"id\": \"812e5dd0-1b14-497c-835c-55150564086a\"}]", "19447354-2ecb-4106-ab16-083ca7708fc2": "[{\"type\": \"heading1\", \"content\": \"Практическое задание: Переход на Единые типовые нормы (ЕТН) выдачи СИЗ и смывающих средств\", \"id\": \"94860af4-78ee-42a0-b9e3-f03efe6a5598\"}, {\"type\": \"paragraph\", \"content\": \"Целью данного практического задания является закрепление навыков разработки локальных норм выдачи средств индивидуальной защиты (СИЗ) в соответствии с новыми требованиями законодательства. С 1 сентября 2023 года вступили в силу Правила обеспечения работников СИЗ и смывающими средствами, утвержденные Приказом Минтруда РФ от 29.10.2021 № 766н, а также Единые типовые нормы (ЕТН), утвержденные Приказом Минтруда РФ от 29.10.2021 № 767н. До 31 декабря 2024 года установлен переходный период, однако работодателям необходимо заранее сформировать внутренние Перечни СИЗ, основываясь на результатах СОУТ и оценки профессиональных рисков (ОПР).\", \"id\": \"319f5f86-393f-4a9c-8be5-228bfa82cde9\"}, {\"type\": \"heading2\", \"content\": \"Постановка задачи и описание организации\", \"id\": \"a51fc67b-3452-4f9f-9258-a682b7d11da5\"}, {\"type\": \"paragraph\", \"content\": \"Общество с ограниченной ответственностью «МеталлКонструкт» (ООО «МК») занимается производством металлических дверей и каркасных конструкций. Генеральный директор принял решение о переходе на выдачу СИЗ по ЕТН. Вам, как специалисту по охране труда, поручено разработать проект Норм выдачи СИЗ для одной из ключевых профессий предприятия — Электросварщик ручной сварки (5-й разряд). Ваша задача — синтезировать данные из штатного расписания, карт СОУТ и реестра рисков, чтобы сформировать полный комплект защиты, обеспечивающий как базовую защиту по профессии, так и дополнительную защиту от выявленных опасностей.\", \"id\": \"031c211a-d475-4b05-85ac-61c802bcb54d\"}, {\"type\": \"heading2\", \"content\": \"Исходные данные для выполнения задания\", \"id\": \"8513dfa7-f85f-44e3-96b1-fcd9af5debe6\"}, {\"type\": \"list\", \"content\": [\"Профессия по штатному расписанию: Электросварщик ручной сварки.\", \"Условия труда (по результатам СОУТ): Подкласс 3.2 (вредные условия). Выявлены факторы: световое излучение, аэрозоли преимущественно фиброгенного действия (сварочный аэрозоль), шум, повышенная температура поверхности оборудования.\", \"Результаты оценки профессиональных рисков (ОПР): Высокий риск поражения органов зрения ИК-излучением; средний риск механического травмирования стоп падающими заготовками; риск химических ожогов кожи при контакте с антикоррозийными присадками; риск падения на скользких поверхностях (масляные пятна на полу цеха).\", \"Отраслевая специфика: Работы проводятся в неотапливаемом цехе в зимний период и на открытых площадках.\", \"Производственное оборудование: Сварочные инверторы, углошлифовальные машины (УШМ), грузоподъемные механизмы управляемые с пола.\"], \"id\": \"0decf188-eab7-4be2-a23b-5411f8c12d41\"}, {\"type\": \"heading2\", \"content\": \"Вопросы для разбора\", \"id\": \"881ab83c-86a9-4126-b445-74e3aebec554\"}, {\"type\": \"list\", \"content\": [\"Вопрос 1: Какие разделы Единых типовых норм (Приказ № 767н) необходимо использовать для формирования полного перечня СИЗ для электросварщика?\", \"Вопрос 2: Как сопоставить наименование профессии в штатном расписании с Приложением № 1 к ЕТН, если название должности совпадает не полностью?\", \"Вопрос 3: Какие дополнительные СИЗ должны быть включены в Нормы на основании выявленных опасностей (риск падения тяжелых предметов на ноги и наличие масляных пятен)?\", \"Вопрос 4: Как правильно отразить в Нормах выдачу дерматологических СИЗ и смывающих средств согласно Приложению № 3 к ЕТН?\", \"Вопрос 5: Допускается ли замена СИЗ, указанных в ЕТН, на аналогичные или более современные средства защиты, и каков механизм такой замены?\"], \"id\": \"53ded623-d5ce-4312-8b38-51daab2a7e16\"}, {\"type\": \"heading2\", \"content\": \"Методические указания\", \"id\": \"bcd6918d-06c6-450d-b131-a885140284a3\"}, {\"type\": \"paragraph\", \"content\": \"При разработке Норм выдачи СИЗ строго следуйте алгоритму, описанному в пунктах 10-18 Правил № 766н. Помните, что Нормы работодателя должны содержать: наименование профессии, пункты ЕТН, наименование СИЗ, уровень защиты (при наличии), количество на период (год) и периодичность выдачи. Сначала выбираем СИЗ по профессии (Приложение 1 к Приказу 767н), затем дополняем его СИЗ на основании выявленных опасностей (Приложение 2 к Приказу 767н). Особое внимание уделите совместимости СИЗ — например, сварочный щиток должен крепиться на защитную каску, если условия труда требуют её ношения. При выборе смывающих средств ориентируйтесь на Приложение 3 к Приказу 767н, учитывая типы загрязнений (устойчивые, трудносмываемые).\", \"id\": \"46f85207-b540-42de-9b41-16be5b63d312\"}, {\"type\": \"heading2\", \"content\": \"Образец решения (эталонный ответ)\", \"id\": \"fc04a405-f901-49c5-93b3-09a92be08b96\"}, {\"type\": \"quote\", \"content\": \"Выписка из проекта Норм выдачи СИЗ ООО «МК» для профессии «Электросварщик ручной сварки»\", \"id\": \"a4176c0b-5082-43dc-8906-14817b2f28a3\"}, {\"type\": \"paragraph\", \"content\": \"1. На основании Приложения № 1 к Приказу 767н (п. 2225): Костюм для защиты от искр и брызг расплавленного металла (3 класс защиты) — 1 шт./год; Ботинки кожаные с защитным подноском — 1 пара/год; Перчатки с защитными свойствами от искр и брызг (краги) — 6 пар/год; Щиток защитный лицевой сварщика — до износа; Подшлемник под щиток — 2 шт./год.\", \"id\": \"bd4f4c54-96ac-457f-aab4-226951664496\"}, {\"type\": \"paragraph\", \"content\": \"2. На основании Приложения № 2 к Приказу 767н (по результатам ОПР): Риск механического воздействия (удары в области стопы) — обувь должна иметь внутренний защитный подносок ударной прочностью не менее 200 Дж (п. 1.1 таблицы). Риск скольжения на замасленных поверхностях — подошва обуви должна иметь коэффициент трения/протектор согласно п. 5.1 таблицы. Риск шума (свыше 80 дБ) — вкладыши противошумные (беруши) или наушники — до износа.\", \"id\": \"3808b5a8-4293-4a06-aa2c-a3592e1084b8\"}, {\"type\": \"paragraph\", \"content\": \"3. На основании Приложения № 3 к Приказу 767н (Смывающие средства): При работах, связанных с трудносмываемыми загрязнениями (масла, металлическая пыль) — паста для очистки кожи (от сорбентов) 100 мл/мес; регенерирующий (восстанавливающий) крем 100 мл/мес. Мыло туалетное для удаления обычных загрязнений — 200 г/мес.\", \"id\": \"99a798d0-62d2-4171-b428-cec0bc12f63b\"}, {\"type\": \"paragraph\", \"content\": \"Резюме по решению: Итоговый перечень объединяет базовые СИЗ сварщика и специальные средства защиты, выявленные в ходе оценки рисков. Для условий неотапливаемого помещения дополнительно включается утепленная спецодежда (куртка на утепляющей прокладке и брюки) согласно климатическому поясу.\", \"id\": \"7a4c0977-a40d-4bff-820b-d8be6a074b7f\"}, {\"type\": \"heading2\", \"content\": \"Список нормативно-правовых актов (НПА)\", \"id\": \"774dd733-a735-4fe9-bf86-0ea129755f17\"}, {\"type\": \"list\", \"content\": [\"Трудовой кодекс Российской Федерации (статьи 209, 214, 221).\", \"Приказ Минтруда России от 29.10.2021 № 766н «Об утверждении Правил обеспечения работников средствами индивидуальной защиты и смывающими средствами».\", \"Приказ Минтруда России от 29.10.2021 № 767н «Об утверждении Единых типовых норм выдачи средств индивидуальной защиты и смывающих средств».\", \"Постановление Правительства РФ от 24.12.2021 № 2464 «О порядке обучения по охране труда и проверки знания требований охраны труда» (в части обучения использованию СИЗ).\", \"Технический регламент Таможенного союза ТР ТС 019/2011 «О безопасности средств индивидуальной защиты».\"], \"id\": \"fb782971-5d3c-4232-85e0-6110bd6fa289\"}]", "6e2b88a1-bf8f-4788-9d34-0f51107158f7": "[{\"type\": \"heading1\", \"content\": \"Организация обеспечения работников средствами индивидуальной защиты (СИЗ) в современных условиях\", \"id\": \"70ddcc89-609a-4ac4-a03c-aa7c6d2c96be\"}, {\"type\": \"paragraph\", \"content\": \"Обеспечение работников средствами индивидуальной защиты (СИЗ) является одной из ключевых обязанностей работодателя, закрепленной в Трудовом кодексе РФ. В рамках профессиональной переподготовки руководителей службы охраны труда крайне важно понимать, что с 2023 года система обеспечения СИЗ претерпела фундаментальные изменения. Мы перешли от типовых отраслевых норм к Единым типовым нормам (ЕТН), ориентированным не только на профессию работника, но и на выявленные на его рабочем месте опасности. СИЗ рассматриваются как последний, но критически важный рубеж защиты, когда технические и организационные меры по снижению уровня профессиональных рисков исчерпаны или невозможны.\", \"id\": \"f9980087-8e62-4298-955c-09c904649d47\"}, {\"type\": \"heading2\", \"content\": \"Нормативно-правовая база и обязанности работодателя\", \"id\": \"8fd90651-84e5-4b8d-b46d-91996be971ab\"}, {\"type\": \"paragraph\", \"content\": \"Основным документом, регулирующим данную сферу, является статья 221 ТК РФ, которая устанавливает обязанность работодателя за счет собственных средств обеспечивать своевременную выдачу СИЗ, прошедших обязательную сертификацию или декларирование соответствия. Технические требования к самим средствам защиты установлены Техническим регламентом Таможенного союза ТР ТС 019/2011. Однако для руководителя службы ОТ наиболее практическими документами являются Приказ Минтруда России от 29.10.2021 № 766н, устанавливающий правила обеспечения, и Приказ от 29.10.2021 № 767н, содержащий Единые типовые нормы. Не стоит забывать и о Постановлении Правительства РФ от 24.12.2021 № 2464, которое регламентирует порядок обучения правилам применения СИЗ.\", \"id\": \"4f62ddbb-c6fc-4bcf-b190-8369105524fe\"}, {\"type\": \"quote\", \"content\": \"Согласно ст. 221 ТК РФ: На работах с вредными и (или) опасными условиями труда, а также на работах, выполняемых в особых температурных условиях или связанных с загрязнением, работникам бесплатно выдаются средства индивидуальной защиты и смывающие средства, прошедшие подтверждение соответствия в установленном законодательством Российской Федерации порядке.\", \"id\": \"5f0b2a9a-4955-429e-97ae-3e38c1fcc5cd\"}, {\"type\": \"heading2\", \"content\": \"Алгоритм перехода на Единые типовые нормы (ЕТН)\", \"id\": \"7e7da3b0-5c46-41b1-8ec2-451a010e4304\"}, {\"type\": \"paragraph\", \"content\": \"Переходный период на ЕТН завершается 31 декабря 2024 года. До этого момента работодатель вправе использовать старые Типовые отраслевые нормы (ТОН), однако стратегия развития службы охраны труда должна быть направлена на риск-ориентированный подход. Процесс перехода включает в себя несколько этапов. Во-первых, это аудит результатов специальной оценки условий труда (СОУТ) и оценки профессиональных рисков (ОПР). Во-вторых, сопоставление выявленных опасностей с Приложением №2 к Приказу №767н. В-третьих, разработка и утверждение локальным нормативным актом Норм бесплатной выдачи СИЗ конкретно для вашей организации.\", \"id\": \"f5d97225-d8bf-4c4f-97ed-d71f0351d8ae\"}, {\"type\": \"list\", \"content\": \"Проведение актуальной оценки профессиональных рисков на каждом рабочем месте\\nФормирование перечня СИЗ на основании профессии (должности) по Приложению №1 к Приказу №767н\\nДополнение перечня СИЗ на основании выявленных опасностей по Приложению №2 к Приказу №767н\\nВыбор дерматологических СИЗ и смывающих средств по Приложению №3 к Приказу №767н\\nСогласование Норм с профсоюзным или иным представительным органом работников\", \"id\": \"4c8f73dd-0abc-4af7-824c-fcf988ddf262\"}, {\"type\": \"heading2\", \"content\": \"Классификация СИЗ и требования к сертификации\", \"id\": \"dd169baf-6802-4843-ad8f-3d69c7b78c85\"}, {\"type\": \"paragraph\", \"content\": \"Согласно ТР ТС 019/2011, все СИЗ делятся на два класса риска. К первому классу относятся СИЗ простой конструкции, используемые в условиях с низким риском причинения вреда (например, обычные халаты, перчатки от загрязнений). Для них достаточно декларации о соответствии. Ко второму классу относятся СИЗ сложной конструкции, защищающие от гибели или необратимого вреда здоровью (СИЗ органов дыхания, страховочные привязи, спецобувь от проколов). Для таких изделий обязателен сертификат соответствия. Руководитель службы ОТ обязан проверять наличие и подлинность этих документов в реестрах Росаккредитации перед закупкой и выдачей.\", \"id\": \"33fd8c1b-8418-4fbb-b4bc-c1c5477a5992\"}, {\"type\": \"heading2\", \"content\": \"Порядок выдачи, учета и хранения СИЗ\", \"id\": \"67667f94-e4c9-426d-be0f-e965a37cc4ba\"}, {\"type\": \"paragraph\", \"content\": \"Выдача СИЗ должна фиксироваться в личной карточке учета выдачи СИЗ. Допускается ведение карточек как в бумажном, так и в электронном виде. При электронном учете вместо личной подписи работника указываются реквизиты документа бухгалтерского учета о получении или данные с электронных считывающих устройств. Важным аспектом является соблюдение сроков носки, которые исчисляются со дня фактической выдачи работнику. Работодатель обязан организовать надлежащий уход за СИЗ: своевременную стирку, чистку, дезинфекцию и ремонт. Работа в загрязненных или неисправных СИЗ категорически запрещена.\", \"id\": \"7f67446b-cf96-4fb6-8c70-8408f7f4c85a\"}, {\"type\": \"list\", \"content\": \"Приемка СИЗ от поставщика комиссией по охране труда\\nПроверка целостности, комплектности и маркировки изделий\\nМаркировка СИЗ инвентарными номерами или ФИО работника (рекомендуется)\\nПроведение первичного инструктажа по правилам эксплуатации и осмотра СИЗ\\nОрганизация мест хранения (гардеробных), соответствующих требованиям гигиены\", \"id\": \"2bee374e-547c-48f7-9e97-63a126ba2b02\"}, {\"type\": \"heading2\", \"content\": \"Обучение использованию СИЗ по Постановлению № 2464\", \"id\": \"bb8c8507-38f9-4b6d-a869-096459c81544\"}, {\"type\": \"paragraph\", \"content\": \"Просто выдать качественные СИЗ недостаточно — работник должен уметь ими пользоваться. Согласно Правилам №2464, обучение по использованию СИЗ является отдельным видом обучения. Для СИЗ, применение которых требует практических навыков (например, изолирующие противогазы, удерживающие системы, сложные респираторы), обязательно проведение практических занятий в объеме не менее 50% от общего количества часов программы. По результатам обучения проводится проверка знаний с оформлением протокола. Если СИЗ не требуют специальных навыков (очки, каски), достаточно провести инструктаж по их применению в рамках инструктажа на рабочем месте.\", \"id\": \"68dcc9e1-aa22-41e6-b39a-45a5459d2e76\"}, {\"type\": \"heading2\", \"content\": \"Контроль и ответственность руководителя службы ОТ\", \"id\": \"d4747a0f-79da-462d-8772-9f602b69d36d\"}, {\"type\": \"paragraph\", \"content\": \"Система контроля за применением СИЗ должна быть многоуровневой. Ответственность за непосредственное использование возлагается на линейных руководителей (мастеров, начальников участков), однако служба охраны труда осуществляет выборочные проверки и методическое руководство. Важно помнить о праве и обязанности работодателя отстранить от работы сотрудника, который не применяет выданные ему СИЗ, обязательные для использования. При этом, если СИЗ не были выданы по вине работодателя, он не имеет права требовать исполнения трудовых обязанностей и обязан оплатить простой в размере среднего заработка.\", \"id\": \"0fc671e3-24c6-4727-9912-e35a31013628\"}, {\"type\": \"list\", \"content\": \"Регулярные рейды и проверки рабочих мест\\nВнедрение системы фото- или видеофиксации нарушений\\nАнализ износа СИЗ для корректировки плана закупок\\nПроверка знаний работников в части методов проверки СИЗ перед началом смены\\nКонтроль за своевременным списанием и утилизацией СИЗ\", \"id\": \"52ca956e-6dea-440f-b3a8-18c66016803e\"}, {\"type\": \"heading2\", \"content\": \"Дежурные СИЗ и СИЗ для посетителей\", \"id\": \"1ec6522f-dd56-400f-a172-1691d76cfe0b\"}, {\"type\": \"paragraph\", \"content\": \"Существуют категории СИЗ, которые не закрепляются за конкретным работником, а являются дежурными. Это средства защиты, используемые периодически при выполнении отдельных видов работ (например, диэлектрические перчатки в электроустановках, сигнальные жилеты, страховочные пояса для редких работ на высоте). Дежурные СИЗ закрепляются за определенным рабочим местом или руководителем работ и передаются от смены к смене. Ответственность за их исправность несет мастер смены. Также необходимо предусматривать запас СИЗ для посетителей, руководителей и инспектирующих лиц, посещающих производственные площадки.\", \"id\": \"3b102400-d6b9-4ab8-bfda-bc1441a08d10\"}, {\"type\": \"heading2\", \"content\": \"Экономическая эффективность и налоговые аспекты\", \"id\": \"6afe74ee-7f8b-4397-b6a5-43224dc62ef8\"}, {\"type\": \"paragraph\", \"content\": \"Расходы на СИЗ относятся на себестоимость продукции, что уменьшает налогооблагаемую базу по налогу на прибыль. Более того, до 20% (а в ряде случаев до 30%) сумм страховых взносов за предыдущий год можно направить на предупредительные меры по сокращению производственного травматизма, включая закупку СИЗ. Для этого руководитель службы ОТ совместно с бухгалтерией должен своевременно подать заявление в Социальный фонд России (СФР). Важно помнить: компенсации подлежат только те СИЗ, которые изготовлены на территории государств-членов ЕАЭС (из материалов также произведенных в ЕАЭС), что требует тщательного подбора поставщиков.\", \"id\": \"60556afa-7f6a-4630-9d2c-ba0faf456670\"}, {\"type\": \"quote\", \"content\": \"Приказ Минтруда №766н, п. 10: Работодатель обязан разработать и утвердить локальным нормативным актом Нормы выдачи СИЗ работникам организации на основании Единых типовых норм, с учетом результатов СОУТ и ОПР, а также мнения выборного органа первичной профсоюзной организации.\", \"id\": \"eaca7636-62c9-481e-b667-9e159d0064d9\"}, {\"type\": \"paragraph\", \"content\": \"Подводя итог, можно сказать, что современная система обеспечения СИЗ — это гибкий инструмент управления рисками. Руководитель службы охраны труда должен отойти от формального выполнения 'списочных' норм и перейти к анализу реальных угроз. Только индивидуальный подбор средств защиты, качественное обучение персонала и жесткий контроль их применения позволят реально снизить производственный травматизм и избежать административных штрафов, которые по статье 5.27.1 КоАП РФ могут достигать 150 000 рублей за каждого необеспеченного работника.\", \"id\": \"09d277e4-7de5-487f-b435-705680be5918\"}]", "2cc59793-12ea-4d49-a18a-9f7b9b76db96": "[{\"type\": \"heading1\", \"content\": \"Урок: Порядок расследования и учета профессиональных заболеваний\", \"id\": \"b56b6a40-1b39-49f0-8653-9dcf99a77d65\"}, {\"type\": \"paragraph\", \"content\": \"Профессиональное заболевание — это хроническое или острое заболевание застрахованного, ставшее результатом воздействия на него вредного производственного фактора (факторов) и повлекшее временную или стойкую утрату им профессиональной трудоспособности либо его смерть. В современных условиях деятельности руководителя службы охраны труда (СОТ) глубокое понимание процедуры расследования профзаболеваний является критически важным, так как это напрямую связано с реализацией государственных гарантий работникам и управлением профессиональными рисками организации. Основным нормативным правовым актом, регламентирующим данный процесс, является Постановление Правительства РФ от 05.07.2022 № 1206 «О порядке расследования и учета случаев профессиональных заболеваний работников», которое пришло на смену старому порядку и внесло ряд существенных корректировок в процедуру взаимодействия работодателя и медицинских организаций.\", \"id\": \"3adb9cf2-a6a5-40e7-83be-5be7f5d62e01\"}, {\"type\": \"heading2\", \"content\": \"Нормативно-правовая база и классификация\", \"id\": \"bf990eb1-7c3c-4a16-b150-6757217dc321\"}, {\"type\": \"quote\", \"content\": \"Статья 214 ТК РФ обязывает работодателя обеспечивать расследование и учет в установленном Трудовым кодексом Российской Федерации, другими федеральными законами и иными нормативными правовыми актами Российской Федерации порядке несчастных случаев на производстве и профессиональных заболеваний.\", \"id\": \"79f3c7d8-38ba-4fb8-b788-e623f368aead\"}, {\"type\": \"paragraph\", \"content\": \"Профессиональные заболевания классифицируются на два типа: острые и хронические. Острое профессиональное заболевание возникает в результате однократного (в течение не более одного рабочего дня или одной рабочей смены) воздействия на работника вредного производственного фактора, повлекшее временную или стойкую утрату трудоспособности. Хроническое профессиональное заболевание является результатом длительного воздействия вредных факторов и, как правило, выявляется в ходе обязательных периодических медицинских осмотров, предусмотренных Приказом Минздрава России от 28.01.2021 № 29н.\", \"id\": \"1fe56125-bb32-448b-a02e-d0196f48c17f\"}, {\"type\": \"heading2\", \"content\": \"Первичные действия при выявлении подозрения на профзаболевание\", \"id\": \"b03af25c-0c00-4b08-9cde-5c0b4330cc43\"}, {\"type\": \"paragraph\", \"content\": \"Процесс расследования запускается медицинской организацией. При установлении предварительного диагноза «острое профессиональное заболевание» медорганизация обязана в течение суток направить извещение в орган государственного санитарно-эпидемиологического надзора (Роспотребнадзор) и работодателю. В случае хронического заболевания срок направления извещения составляет 3 рабочих дня. Получив такое извещение, руководитель службы охраны труда должен подготовить сведения для составления санитарно-гигиенической характеристики условий труда работника. Это один из ключевых документов, на основании которого Центр профпатологии впоследствии будет устанавливать окончательный диагноз.\", \"id\": \"8c78ff14-c938-4ef7-a04c-54f925b2e8c4\"}, {\"type\": \"list\", \"content\": \"Подготовка данных о результатах специальной оценки условий труда (СОУТ) на рабочем месте работника.\\nСбор сведений о результатах производственного контроля.\\nПредоставление информации о стаже работы сотрудника в условиях воздействия вредных факторов.\\nВыписки из журналов инструктажей и протоколов обучения по охране труда по программе Приказа Минтруда №2464.\\nДанные о предоставлении работнику средств индивидуальной защиты (СИЗ) и смывающих средств.\", \"id\": \"9725918c-d0e9-42f1-bccd-c3ff66d83278\"}, {\"type\": \"heading2\", \"content\": \"Установление окончательного диагноза и создание комиссии\", \"id\": \"2e6e6afa-f2d3-4e77-b7c8-9f5b2d0632cc\"}, {\"type\": \"paragraph\", \"content\": \"Окончательный диагноз устанавливается специализированными медицинскими организациями — центрами профессиональной патологии. После того как работодатель получает медицинское заключение об установлении окончательного диагноза, он обязан в течение 10 рабочих дней образовать комиссию по расследованию профзаболевания. Возглавляет комиссию главный государственный санитарный врач по соответствующей территории или его заместитель. В состав комиссии в обязательном порядке включаются представитель работодателя (зачастую это руководитель СОТ), специалист по охране труда, представитель выборного органа первичной профсоюзной организации и представитель медицинского учреждения.\", \"id\": \"cb70c96e-6f4b-454b-b724-59b7244f2018\"}, {\"type\": \"paragraph\", \"content\": \"Важно отметить, что согласно ПП РФ № 1206, если расследование проводится в отношении работника, который на момент выявления заболевания уже сменил место работы, комиссия все равно создается у того работодателя, чье воздействие вредных факторов привело к заболеванию. Если же организация ликвидирована, расследование проводится комиссией, созданной органом Роспотребнадзора.\", \"id\": \"16fba8c7-6a34-4854-ac4a-df1935cb5fe9\"}, {\"type\": \"heading2\", \"content\": \"Процедура работы комиссии и сроки расследования\", \"id\": \"d4d445ca-7061-4398-a226-19391d60559b\"}, {\"type\": \"list\", \"content\": \"Срок расследования составляет 30 рабочих дней со дня создания комиссии (может быть продлен не более чем на 30 рабочих дней).\\nОпрос сослуживцев работника, лиц, допустивших нарушение санитарно-эпидемиологических правил.\\nИзучение документов СОУТ (ФЗ-426) и технической документации на оборудование.\\nПроведение (при необходимости) дополнительных экспертиз и лабораторных исследований.\\nУстановление факта грубой неосторожности застрахованного (если это способствовало возникновению вреда).\", \"id\": \"93d687c7-1626-45a0-bf97-ff3301670b08\"}, {\"type\": \"paragraph\", \"content\": \"Крайне ответственным этапом для руководителя службы охраны труда является участие в определении степени вины застрахованного. Если комиссией установлено, что грубая неосторожность застрахованного способствовала возникновению или увеличению вреда, причиненного его здоровью, в акте указывается степень его вины в процентах (но не более 25%). Это решение принимается с учетом заключения профсоюзного комитета. Ошибки на этом этапе могут привести к судебным искам со стороны работника или претензиям со стороны Социального фонда России (СФР).\", \"id\": \"1a341b13-2335-49ae-8c29-2f318c902dab\"}, {\"type\": \"heading2\", \"content\": \"Оформление акта о случае профессионального заболевания\", \"id\": \"66ccabc2-05fd-468a-9f6e-a0d0d2cd4736\"}, {\"type\": \"paragraph\", \"content\": \"Результатом работы комиссии является Акт о случае профессионального заболевания. Это основной документ, подтверждающий право работника на получение страховых выплат через СФР. Акт составляется в течение 3 рабочих дней по истечении срока расследования в пяти экземплярах: для работника, работодателя, Роспотребнадзора, Центра профпатологии и СФР. В акте подробно описываются обстоятельства возникновения заболевания, указываются виновные лица и мероприятия по устранению причин развития патологий.\", \"id\": \"660833f7-8292-42e7-9fff-f7d9273c6022\"}, {\"type\": \"quote\", \"content\": \"Согласно требованиям ГОСТ 12.0.230-2007 ССБТ, результаты расследования должны использоваться организацией для совершенствования системы управления охраной труда (СУОТ) и актуализации карт оценки рисков.\", \"id\": \"a2a5d69b-3228-427a-97bd-78bf918a1507\"}, {\"type\": \"heading2\", \"content\": \"Обязанности руководителя СУОТ после завершения расследования\", \"id\": \"598de808-ace2-41e2-abda-b2e5eef1507f\"}, {\"type\": \"paragraph\", \"content\": \"После подписания акта работа руководителя службы охраны труда не заканчивается. В течение месяца работодатель обязан издать приказ о мерах по предупреждению профзаболеваний на основе предложений комиссии. Эти меры могут включать в себя: модернизацию оборудования, изменение технологического процесса, усиление контроля за применением СИЗ, перевод работника на другую работу (в соответствии с медицинским заключением), внеочередную оценку рисков. Контроль за исполнением этих мероприятий возлагается на руководителя СОТ. Невыполнение указанных мер влечет административную ответственность по статье 5.27.1 КоАП РФ.\", \"id\": \"fe3ff243-84ad-4dce-8dcc-ea04858dc36c\"}, {\"type\": \"paragraph\", \"content\": \"Также необходимо внести сведения о случае заболевания в Журнал учета профессиональных заболеваний. Срок хранения актов о профзаболеваниях и материалов расследования составляет 75 лет, что подчеркивает значимость данного документа для архивного дела и будущих социальных запросов. Руководитель СОТ должен обеспечить сохранность этих данных, так как они могут потребоваться при повторных расследованиях или при возникновении отложенных последствий для здоровья других членов коллектива.\", \"id\": \"6e53a380-8156-4ea3-b589-643af9e71c90\"}, {\"type\": \"heading2\", \"content\": \"Заключение\", \"id\": \"34914f0a-b2f7-4114-aff7-b7d1d8bb27d0\"}, {\"type\": \"paragraph\", \"content\": \"Эффективная система расследования профзаболеваний в организации — это не только исполнение требований законодательства, но и мощный инструмент для снижения издержек. Выявление истинных причин профессиональной патологии позволяет предотвратить массовые заболевания персонала, снизить текучесть кадров и избежать регрессных исков. Профессиональная компетенция руководителя СОТ в этом вопросе заключается в умении координировать действия между медиками, государственными инспекторами и внутренними техническими службами предприятия, соблюдая законные интересы как работодателя, так и пострадавшего сотрудника.\", \"id\": \"a046c2cb-be5c-452d-bdfc-0c7c5619f7ba\"}]", "db676df8-62bf-4036-8fef-52655855588d": "[{\"type\": \"heading1\", \"content\": \"Урок: Порядок расследования и учета несчастных случаев на производстве\", \"id\": \"e2bf31d9-b155-4d1a-9eab-93ab8a64fe96\"}, {\"type\": \"paragraph\", \"content\": \"Расследование несчастных случаев на производстве является одной из самых ответственных и юридически сложных процедур в работе руководителя службы охраны труда. Основная цель данного процесса заключается не только в формальном соблюдении требований законодательства, но и в выявлении истинных коренных причин происшествия для предотвращения подобных инцидентов в будущем. Процедура строго регламентирована Трудовым кодексом РФ (статьи 227–231) и Положением об особенностях расследования несчастных случаев на производстве в отдельных отраслях и организациях, утвержденным Приказом Минтруда России от 20.04.2022 № 223н. Руководитель службы охраны труда должен выступать гарантом легитимности работы комиссии, обеспечивая объективность сбора доказательств и правильность квалификации события.\", \"id\": \"dab26ed4-d6a7-4509-af22-01260a5a297b\"}, {\"type\": \"heading2\", \"content\": \"Квалификация несчастного случая и первоочередные действия\", \"id\": \"facc3846-f51a-4ca3-939d-93c763a11396\"}, {\"type\": \"paragraph\", \"content\": \"Согласно статье 227 ТК РФ, расследованию подлежат события, в результате которых работники получили телесные повреждения или иные повреждения здоровья, приведшие к необходимости перевода на другую работу, временной или стойкой утрате трудоспособности либо смерти. Важнейшим критерием является исполнение работником своих трудовых обязанностей или выполнение работ по поручению работодателя. Это включает в себя время в течение рабочего дня, перерывы, время до начала и после окончания работ, а также следование к месту работы на транспорте работодателя. Руководитель службы охраны труда должен четко дифференцировать производственные травмы от несчастных случаев, не связанных с производством (например, смерть вследствие общего заболевания или травма при совершении преступления), поскольку это напрямую влияет на социальные гарантии пострадавшего.\", \"id\": \"3717b66a-d99f-4fcb-9fc9-049415b8091a\"}, {\"type\": \"quote\", \"content\": \"Статья 228 ТК РФ: При групповом несчастном случае (два человека и более), тяжелом несчастном случае или несчастном случае со смертельным исходом работодатель в течение суток обязан направить извещение по установленной форме в государственную инспекцию труда, прокуратуру, орган исполнительной власти субъекта РФ, территориальный орган СФР и соответствующее профсоюзное объединение.\", \"id\": \"51882d29-b379-423d-9a60-0693cc30b579\"}, {\"type\": \"heading2\", \"content\": \"Формирование и работа комиссии по расследованию\", \"id\": \"e2a90192-c779-4fc4-b9b9-113dc6bd23f5\"}, {\"type\": \"paragraph\", \"content\": \"Для расследования каждого несчастного случая работодатель незамедлительно образует комиссию в составе не менее трех человек. Возглавляет комиссию, как правило, работодатель или его представитель, а при расследовании тяжелых и смертельных случаев — государственный инспектор труда. Руководитель службы охраны труда обязательно входит в состав комиссии и фактически является ее «мотором»: он координирует сбор документов, организует выезды на место происшествия и контролирует соблюдение сроков. Важно помнить, что в состав комиссии не может быть включен непосредственный руководитель пострадавшего, на которого возложена ответственность за обеспечение охраны труда на данном участке, дабы избежать конфликта интересов и попыток сокрытия фактов нарушений.\", \"id\": \"431b1f94-9a05-4e69-9455-72a76e7974ee\"}, {\"type\": \"list\", \"content\": \"Запрос медицинского заключения о характере и степени тяжести повреждений (форма № 315/у);\\nОбеспечение сохранности обстановки на месте происшествия до начала работы комиссии;\\nФото- и видеофиксация места происшествия, составление схем и протоколов осмотра;\\nОпрос очевидцев, должностных лиц и самого пострадавшего (при возможности);\\nИзучение локальных нормативных актов: инструкций по ОТ, журналов инструктажей, карточек выдачи СИЗ.\", \"id\": \"3f001ff9-be35-4d2c-a8e8-b5eab26c3466\"}, {\"type\": \"heading2\", \"content\": \"Анализ документации и выявление причин\", \"id\": \"3a5eac11-52df-438a-bcc5-589565f5a7d1\"}, {\"type\": \"paragraph\", \"content\": \"На этапе анализа эксперт по охране труда должен сопоставить фактические действия работника с требованиями локальных актов и Постановления Правительства РФ № 2464 «О порядке обучения по охране труда и проверки знаний требований охраны труда». Было ли проведено своевременное обучение? Прошел ли работник инструктаж на рабочем месте? Был ли он обеспечен сертифицированными СИЗ в соответствии с нормами? Особое внимание уделяется результатам Специальной оценки условий труда (СОУТ) и оценки профессиональных рисков (ОПР). Если риск, приведший к травме, не был идентифицирован в картах ОПР, это указывает на системный сбой в системе управления охраной труда (СУОТ) организации, что требует немедленной корректировки документации после завершения расследования.\", \"id\": \"6d9289e5-3fd6-45f1-a2a9-83ee790f216e\"}, {\"type\": \"quote\", \"content\": \"Согласно Приказу Минтруда № 223н, при выявлении факта грубой неосторожности застрахованного, содействовавшей возникновению или увеличению вреда, в акте Н-1 указывается степень его вины в процентах (не более 25%), установленная комиссией на основании заключения профсоюзного комитета.\", \"id\": \"2db70c13-d10c-4c6b-8e8f-f6f1d552bf39\"}, {\"type\": \"heading2\", \"content\": \"Сроки расследования и документальное оформление\", \"id\": \"3965720e-f9e7-4716-959a-6bae37170d7a\"}, {\"type\": \"paragraph\", \"content\": \"Сроки расследования жестко ограничены законом. Несчастные случаи, квалифицированные как легкие, расследуются в течение 3 календарных дней. Расследование тяжелых, групповых или смертельных случаев занимает до 15 календарных дней. Если пострадавший не сразу сообщил о травме или утрата работоспособности наступила спустя время, расследование проводится в течение одного месяца со дня поступления заявления от пострадавшего. Руководитель службы охраны труда должен следить за тем, чтобы все материалы дела были подшиты в установленном порядке: от приказа о создании комиссии до акта формы Н-1. Ошибка в одной дате или отсутствие подписи одного из членов комиссии может привести к признанию результатов расследования недействительными в судебном порядке.\", \"id\": \"422bb3e2-fdad-42dd-a6f8-af3fc5544b6d\"}, {\"type\": \"list\", \"content\": \"Протокол осмотра места несчастного случая;\\nПротоколы опросов очевидцев и должностных лиц;\\nКопии документов об обучении пострадавшего и прохождении медицинских осмотров;\\nАкт о несчастном случае на производстве по форме Н-1 (в 3 экземплярах);\\nЗаключение государственного инспектора труда (при участии в расследовании).\", \"id\": \"59fbb517-bcaf-4086-91cb-96c0e00955a8\"}, {\"type\": \"heading2\", \"content\": \"Учет, отчетность и профилактические мероприятия\", \"id\": \"4496791e-dc3d-4949-9162-3637dbd185d9\"}, {\"type\": \"paragraph\", \"content\": \"После подписания акта Н-1 работодатель обязан в трехдневный срок выдать один экземпляр пострадавшему, а второй — направить в Социальный фонд России (СФР). Каждый несчастный случай регистрируется в Журнале регистрации несчастных случаев на производстве. Однако работа руководителя службы охраны труда на этом не заканчивается. Главный итог расследования — разработка мероприятий по устранению причин несчастного случая. Это могут быть как технические решения (установка ограждений, блокировок, модернизация оборудования согласно ГОСТ ССБТ), так и организационные: внеплановое обучение по Приказу № 2464н, пересмотр инструкций, проведение внеочередной оценки рисков.\", \"id\": \"b7f8e0b1-3b8a-491f-b65d-e1f154071bf4\"}, {\"type\": \"paragraph\", \"content\": \"Эффективный руководитель службы ОТ использует данные расследований для формирования ежегодного отчета о состоянии охраны труда в компании и обоснования бюджета на безопасность перед руководством. Помните, что сокрытие несчастного случая является грубым нарушением законодательства и влечет за собой административную ответственность по статье 5.27.1 КоАП РФ, а в случае тяжелых последствий — уголовную ответственность по статье 143 УК РФ. Прозрачность и методичность в расследовании — залог юридической чистоты организации и безопасности персонала.\", \"id\": \"3baef4b7-3e4d-4cc0-b8ab-233b7c3b2516\"}, {\"type\": \"heading2\", \"content\": \"Связь расследования с системой управления охраной труда (СУОТ)\", \"id\": \"34cc8503-6e3a-4f6c-a1f8-8d57ba78a1cd\"}, {\"type\": \"paragraph\", \"content\": \"Интеграция результатов расследования в общую СУОТ организации является обязательным требованием современных стандартов. После завершения процедуры материалы должны быть проанализированы на предмет соответствия принятой политике в области ОТ. Если в ходе расследования выясняется, что причиной стал человеческий фактор (например, нарушение дисциплины), руководителю службы ОТ необходимо инициировать внедрение программ «поведенческого аудита безопасности». Если же причиной стали конструктивные недостатки оборудования, необходимо направить рекламации поставщикам или внести изменения в план планово-предупредительных ремонтов. Таким образом, расследование превращается из реактивного механизма в проактивный инструмент управления качеством производственной среды.\", \"id\": \"6762fb4a-1ef9-4533-8748-a350957ec734\"}, {\"type\": \"list\", \"content\": \"Проведение внепланового инструктажа со всеми работниками подразделения;\\nОбновление карт идентификации опасностей и оценки рисков;\\nКорректировка программ обучения и проверки знаний;\\nИздание приказа о привлечении к дисциплинарной ответственности виновных лиц;\\nИнформирование коллектива о причинах происшествия для предупреждения аналогичных действий.\", \"id\": \"17e9130c-81db-49fc-86a8-197ec657e5e9\"}, {\"type\": \"paragraph\", \"content\": \"Завершая изучение данной темы, важно отметить, что роль руководителя службы охраны труда в процессе расследования — это не просто заполнение бланков, а глубокая аналитическая работа, требующая знаний в области психологии труда, технического устройства оборудования и юриспруденции. Только комплексный подход к каждому инциденту позволит минимизировать травматизм и создать культуру безопасности, где жизнь и здоровье человека являются высшим приоритетом.\", \"id\": \"2591820a-3ca7-4afe-bc18-7e9ce85e9c8a\"}]", "42b50bf8-b9fa-44da-bd3a-99a1a4d62eb6": "[{\"type\": \"heading1\", \"content\": \"Урок: Планирование и бюджетирование мероприятий по охране труда\", \"id\": \"051c1a0b-215c-47df-939c-09711d1ce197\"}, {\"type\": \"paragraph\", \"content\": \"Эффективное управление охраной труда (ОТ) в современной организации невозможно без четкого стратегического и оперативного планирования. Для руководителя службы ОТ планирование — это не просто составление списка дел, а процесс распределения ресурсов, направленный на минимизацию профессиональных рисков и обеспечение соответствия деятельности компании нормативным требованиям законодательства РФ. Основой для финансового обеспечения безопасности труда является статья 225 Трудового кодекса РФ, которая обязывает работодателя финансировать мероприятия по улучшению условий и охраны труда. Понимание механизмов бюджетирования позволяет руководителю службы аргументированно отстаивать необходимые затраты перед финансовым директором и генеральным директором, переводя расходы на безопасность в категорию инвестиций в человеческий капитал и стабильность бизнеса.\", \"id\": \"b20ba49d-4cd6-4573-a4ab-8f73fcc0b09b\"}, {\"type\": \"heading2\", \"content\": \"Нормативно-правовая база планирования\", \"id\": \"5334d09e-18fb-4f02-84ca-fd28308e5419\"}, {\"type\": \"quote\", \"content\": \"Статья 225 ТК РФ: Финансирование мероприятий по улучшению условий и охраны труда осуществляется работодателями в размере не менее 0,2 процента суммы затрат на производство продукции (работ, услуг). Это положение является императивной нормой, определяющей минимальный финансовый порог, который компания обязана выделить на охрану труда ежегодно.\", \"id\": \"336dc225-2db3-4965-96eb-e638ba2b477d\"}, {\"type\": \"paragraph\", \"content\": \"Помимо ТК РФ, ключевым инструментом планирования является Приказ Минтруда России от 29.10.2021 № 771н, который утвердил Примерный перечень ежегодно реализуемых работодателем мероприятий по улучшению условий и охраны труда, ликвидации или снижению уровней профессиональных рисков либо недопущению повышения их уровней. Данный перечень служит фундаментом для составления локального плана мероприятий. Руководитель службы ОТ должен использовать этот документ как чек-лист при формировании бюджета на очередной календарный год. Игнорирование пунктов данного перечня при наличии соответствующих рисков на рабочих местах может привести к административной ответственности согласно КоАП РФ.\", \"id\": \"04ea6904-94ff-41fe-a873-7bf76e058370\"}, {\"type\": \"heading2\", \"content\": \"Этапы разработки плана мероприятий по ОТ\", \"id\": \"c55e48b4-8883-42ae-a633-1d0c78daf421\"}, {\"type\": \"paragraph\", \"content\": \"Процесс планирования начинается с анализа текущего состояния условий труда. Основными входными данными являются результаты специальной оценки условий труда (СОУТ), проведенной в соответствии с Федеральным законом № 426-ФЗ, и результаты оценки профессиональных рисков (ОПР). Если СОУТ выявляет вредные условия (классы 3.1–3.4), планирование должно включать мероприятия по модернизации оборудования или совершенствованию СИЗ. Если же ОПР указывает на высокую вероятность травмирования, акцент смещается на технические решения: установку ограждений, систем блокировки или изменение технологического процесса. Важно помнить, что согласно ст. 214 ТК РФ, приоритет всегда отдается коллективным средствам защиты и замене опасных факторов безопасными.\", \"id\": \"8b124317-e22e-408b-a010-f54a33aa0371\"}, {\"type\": \"list\", \"content\": \"Сбор и анализ данных: результаты СОУТ, ОПР, предписания надзорных органов, данные производственного контроля.\\nРазработка проектов мероприятий на основе Приказа Минтруда № 771н.\\nОпределение ресурсной базы: материальные затраты, фонд оплаты труда задействованных специалистов, привлечение сторонних организаций.\\nСогласование сроков реализации и ответственных лиц (обычно это руководители подразделений).\\nУтверждение плана руководителем организации и согласование с профсоюзом (при наличии).\", \"id\": \"83d424e2-5de3-46e8-af06-4981017f7a7d\"}, {\"type\": \"heading2\", \"content\": \"Бюджетирование расходов на обучение и СИЗ\", \"id\": \"feec50e1-42ac-4910-9027-2609997a4a27\"}, {\"type\": \"paragraph\", \"content\": \"Значительную долю бюджета занимают расходы на обучение персонала и обеспечение средствами индивидуальной защиты (СИЗ). С 1 сентября 2022 года расчет затрат на обучение проводится в строгом соответствии с Постановлением Правительства РФ № 2464. Новые правила требуют разделения обучения на несколько видов: по использованию СИЗ, по оказанию первой помощи, по общим вопросам ОТ и по безопасным методам выполнения работ. Руководитель службы ОТ должен рассчитать количество работников, подлежащих внешнему обучению в учебных центрах, и затраты на организацию внутреннего обучения (подготовка материалов, проверка знаний через личный кабинет Минтруда).\", \"id\": \"a9c3e3d6-9ea9-40a0-86f9-659807217aeb\"}, {\"type\": \"paragraph\", \"content\": \"В части СИЗ бюджетирование переходит на Единые типовые нормы (ЕТН) в соответствии с Приказами Минтруда № 766н и № 767н. Это требует от руководителя службы ОТ перехода от списочного снабжения к риск-ориентированному подходу. Теперь объем финансирования СИЗ напрямую зависит от выявленных на рабочих местах рисков и опасностей. Планируя бюджет, необходимо учитывать не только стоимость закупки, но и затраты на стирку, химчистку, ремонт, хранение и своевременную утилизацию СИЗ. ГОСТ Р 12.4.297-2013 также дает ориентиры по качественным характеристикам защиты, которые могут влиять на итоговую стоимость закупки.\", \"id\": \"1793c53e-1f66-4c7b-ac23-144db798a67e\"}, {\"type\": \"heading2\", \"content\": \"Мероприятия по медицине и производственному контролю\", \"id\": \"f2fb81b1-3a17-4868-9c02-103ad417eda6\"}, {\"type\": \"list\", \"content\": \"Организация обязательных предварительных и периодических медицинских осмотров (Приказ Минздрава № 29н).\\nПроведение психиатрических освидетельствований (Постановление Правительства № 695).\\nЗакупка аптечек для оказания первой помощи (Приказ Минздрава № 1331н).\\nПроведение лабораторных исследований и испытаний в рамках программы производственного контроля (СП 2.2.3670-20).\\nПриобретение приборов контроля вредных факторов для нужд внутренней службы ОТ.\", \"id\": \"868334fc-b38b-4189-8b03-7fabf984929c\"}, {\"type\": \"heading2\", \"content\": \"Инструменты защиты бюджета: Возврат средств из СФР\", \"id\": \"af9e6c23-9bff-49dc-a016-c0b3a634ee6c\"}, {\"type\": \"paragraph\", \"content\": \"Важным аспектом бюджетирования является возможность финансового обеспечения предупредительных мер за счет сумм страховых взносов в Социальный фонд России (СФР). Работодатель имеет право вернуть до 20% (в ряде случаев до 30%) от сумм страховых взносов, начисленных за прошлый год. Для руководителя службы ОТ это ключевой инструмент «экономии», позволяющий проводить СОУТ, закупать СИЗ или отправлять работников предпенсионного возраста в санатории практически бесплатно для компании. Заявление на финансовое обеспечение должно быть подано в СФР до 1 августа текущего года. Правильное планирование этих мероприятий позволяет снизить нагрузку на чистую прибыль организации.\", \"id\": \"5c467d1e-b5b0-4f60-9e7f-fef4cc020b68\"}, {\"type\": \"heading2\", \"content\": \"Контроль исполнения и отчетность\", \"id\": \"4c465782-e813-4e5b-98d9-c1a0b527ecae\"}, {\"type\": \"paragraph\", \"content\": \"Планирование не заканчивается утверждением документа. Требуется мониторинг исполнения бюджета (план-фактный анализ). Рекомендуется проводить ежеквартальные аудиты выполнения мероприятий. Недоосвоение бюджета по охране труда так же негативно характеризует работу службы, как и перерасход, поскольку это означает, что запланированные меры безопасности не были реализованы в полном объеме, что повышает риск возникновения несчастных случаев. В системе СУОТ (Система управления охраной труда), согласно ГОСТ Р 12.0.007-2009, контроль бюджета является частью процесса постоянного совершенствования.\", \"id\": \"84fd1f40-83ce-4594-9505-c31a9d0b5b31\"}, {\"type\": \"list\", \"content\": \"Ведение реестра договоров по направлению ОТ.\\nКонтроль первичной документации (акты выполненных работ, накладные на СИЗ).\\nПодготовка годового отчета для руководства с расчетом экономической эффективности (например, предотвращенный ущерб от штрафов или снижение выплат по больничным листам).\\nАктуализация плана на следующий цикл в зависимости от изменений в законодательстве (например, вступление в силу новых правил по охране труда).\", \"id\": \"06b31be6-51f6-45f3-809d-630280923192\"}, {\"type\": \"heading2\", \"content\": \"Заключение\", \"id\": \"45506dc1-85dc-45a7-94f9-f269692f2389\"}, {\"type\": \"paragraph\", \"content\": \"Роль руководителя службы охраны труда в планировании и бюджетировании является синтетической: он должен обладать глубокими знаниями в области безопасности, права и экономики. Умение грамотно обосновать необходимость закупки экзоскелетов или внедрения системы автоматического дистанционного контроля вредных выбросов через призму снижения производственного травматизма и профессиональных заболеваний — это то, что отличает профессионала высокого уровня. Планируйте мероприятия не для проверяющих органов, а для создания реально безопасной среды, опираясь на ст. 214 и 225 ТК РФ, и тогда бюджет будет восприниматься руководством не как бремя, а как залог стабильности всей компании.\", \"id\": \"eb05527b-c225-4fad-a7ce-d21522f21af9\"}]", "d4f02906-f74a-4a0c-9a03-67fdcfe7eea5": "[{\"type\": \"heading1\", \"content\": \"Структура и функции службы охраны труда: построение эффективной работы подразделения\", \"id\": \"f2a36180-71ba-410f-80cc-55f2142d4aa4\"}, {\"type\": \"paragraph\", \"content\": \"Создание и функционирование службы охраны труда в организации является не просто формальным выполнением требований трудового законодательства, а стратегическим инструментом управления производственными рисками. Руководитель службы охраны труда (ОТ) должен четко осознавать, что его подразделение выступает центральным звеном в системе управления охраной труда (СУОТ). Основная цель деятельности службы заключается в обеспечении соблюдения государственно-нормативных требований охраны труда, профилактике несчастных случаев на производстве и предупреждении профессиональных заболеваний. Согласно статье 223 Трудового кодекса РФ, создание службы охраны труда или введение должности специалиста по охране труда является обязательным для каждого работодателя, осуществляющего производственную деятельность, численность работников которого превышает 50 человек.\", \"id\": \"6c2bef10-1ce0-4f8d-bb6d-b169b3b75874\"}, {\"type\": \"quote\", \"content\": \"ТК РФ Статья 223. Служба охраны труда в организации. При отсутствии у работодателя службы охраны труда, штатного специалиста по охране труда их функции осуществляет работодатель - индивидуальный предприниматель (лично), руководитель организации, другой уполномоченный работодателем работник либо организация или индивидуальный предприниматель, оказывающие услуги в области охраны труда, привлекаемые работодателем по гражданско-правовому договору.\", \"id\": \"21bd4a72-4f1f-48a9-82d6-828b8017c7c0\"}, {\"type\": \"heading2\", \"content\": \"Правовые основы и нормативы формирования службы\", \"id\": \"3302996f-a470-4661-9a12-e7748fceeb21\"}, {\"type\": \"paragraph\", \"content\": \"При проектировании структуры службы охраны труда руководитель должен опираться на профессиональный стандарт «Специалист в области охраны труда», утвержденный приказом Минтруда России от 22.04.2021 № 274н, а также на Рекомендации по структуре службы охраны труда в организации и по численности работников службы охраны труда, утвержденные приказом Минтруда России от 31.01.2022 № 37. Эти документы определяют не только количественный состав подразделения, но и квалификационные требования к сотрудникам. Расчет численности службы производится исходя из объема работы: количества обособленных подразделений, удаленности объектов, специфики производственных процессов и общей численности персонала. Важно понимать, что служба ОТ подчиняется непосредственно работодателю или по его поручению одному из его заместителей, что обеспечивает независимость контроля и оперативность принятия решений на высшем уровне управления.\", \"id\": \"7806d86b-a1e3-43b1-bf3e-2bed994b3d09\"}, {\"type\": \"heading2\", \"content\": \"Ключевые функции службы охраны труда\", \"id\": \"11705c91-a8ad-4f4e-abaf-5aad9e8ad016\"}, {\"type\": \"paragraph\", \"content\": \"Функционал службы охраны труда можно разделить на несколько ключевых блоков, каждый из которых требует детальной проработки и системного подхода. Первым и важнейшим блоком является организация работы по обеспечению требований охраны труда. Это включает в себя разработку локальных нормативных актов, таких как Положение о СУОТ, инструкции по охране труда, программы инструктажей. Вторым блоком выступает контроль за соблюдением законодательства. Специалисты службы обязаны проводить регулярные проверки рабочих мест, контролировать состояние защитных устройств и правильность использования средств индивидуальной защиты (СИЗ). Согласно Приказу Минтруда № 766н, с сентября 2023 года вступили в силу новые правила обеспечения СИЗ и смывающими средствами, что требует от службы ОТ пересмотра внутренних норм выдачи на основе Единых типовых норм (ЕТН).\", \"id\": \"23b87741-9ea0-41bf-8b36-5e4dfe8d83d5\"}, {\"type\": \"list\", \"content\": \"Организация и координация работ по идентификации опасностей и оценке профессиональных рисков.\\nПодготовка отчетности по охране труда по установленным формам.\\nОрганизация проведения специальной оценки условий труда (СОУТ) в соответствии с ФЗ-426.\\nУчастие в расследовании и учете несчастных случаев на производстве и профессиональных заболеваний.\\nОрганизация проведения медицинских осмотров и психиатрических освидетельствований.\\nКоординация процесса обучения работников по охране труда согласно Постановлению Правительства № 2464.\", \"id\": \"5afc8271-3b8c-4f62-90c0-1aa41cab47c3\"}, {\"type\": \"heading2\", \"content\": \"Обучение персонала как критический процесс\", \"id\": \"faa69f32-8c58-4218-a3e8-f8e0d85951d9\"}, {\"type\": \"paragraph\", \"content\": \"Особое место в работе руководителя службы занимает организация обучения. С 1 сентября 2022 года вступило в силу Постановление Правительства РФ № 2464 «О порядке обучения по охране труда и проверки знания требований охраны труда». Теперь обучение делится на пять различных видов: обучение по использованию СИЗ, обучение оказанию первой помощи, обучение безопасным методам и приемам выполнения работ (разделенное по видам рисков и категорий персонала), а также инструктажи и стажировки. Служба охраны труда обязана не только контролировать сроки проведения обучения, но и обеспечивать наличие актуальных программ, реестров обученных лиц и протоколов проверки знаний. Для крупных организаций критически важно правильно настроить работу постоянно действующей комиссии по проверке знаний и обеспечить ее регистрацию в реестрах Минтруда, если обучение проводится внутри компании.\", \"id\": \"14e42945-365b-476c-894f-bcbb40ce6131\"}, {\"type\": \"heading2\", \"content\": \"Управление рисками и взаимодействие с подразделениями\", \"id\": \"88f8df96-ddce-45ef-b77a-31adf396bc3f\"}, {\"type\": \"paragraph\", \"content\": \"Современный подход к охране труда базируется на риск-ориентированном методе. Служба ОТ выступает модератором процесса оценки рисков. Руководитель службы должен организовать работу так, чтобы в процесс выявления опасностей были вовлечены сами работники и руководители линейных подразделений. Это позволяет создать реальную карту рисков, а не формальный документ для проверяющих органов. На основе результатов оценки рисков формируется План мероприятий по охране труда, который должен быть подкреплен бюджетом. Эффективное взаимодействие с отделом кадров, финансовой службой и техническим директором позволяет интегрировать вопросы безопасности во все бизнес-процессы. Например, при закупке нового оборудования служба охраны труда должна участвовать в согласовании технических заданий на предмет соответствия ГОСТам системы стандартов безопасности труда (ССБТ).\", \"id\": \"66cae5f7-23d0-4e31-ad29-4a8ac48f5fa6\"}, {\"type\": \"quote\", \"content\": \"Федеральный закон № 426-ФЗ Статья 4. Обязанности работодателя в связи с проведением специальной оценки условий труда. Работодатель обязан обеспечить проведение специальной оценки условий труда, в том числе внеплановой специальной оценки условий труда, в случаях, установленных частью 1 статьи 17 настоящего Федерального закона.\", \"id\": \"cad24b11-7e41-449c-ae20-f2d1eaffca9a\"}, {\"type\": \"heading2\", \"content\": \"Построение системы контроля и аудита\", \"id\": \"3a699655-4ee3-49a1-a5f5-c7cd991b5180\"}, {\"type\": \"paragraph\", \"content\": \"Система контроля, выстраиваемая службой ОТ, должна быть многоуровневой. Первый уровень — это самоконтроль работников и оперативный контроль мастеров (бригадиров). Втором уровень — контроль со стороны начальников цехов и специалистов службы ОТ. Третий уровень — периодические аудиты системы управления охраной труда со стороны руководителя службы или внешних экспертов. Для автоматизации этого процесса рекомендуется использовать специализированные ИТ-решения, позволяющие отслеживать сроки медосмотров, выдачи СИЗ и прохождения обучения в режиме реального времени. Это снижает риск человеческой ошибки и позволяет руководителю службы видеть объективную картину состояния безопасности на всех объектах компании.\", \"id\": \"ee7b4eaa-19e3-406e-a624-f941331d28eb\"}, {\"type\": \"heading2\", \"content\": \"Документационное обеспечение службы\", \"id\": \"5584d55d-c6a2-4190-845e-2c2fbd7b7721\"}, {\"type\": \"paragraph\", \"content\": \"Деятельность службы охраны труда генерирует значительный объем документации. Важно структурировать этот массив данных так, чтобы любой документ мог быть оперативно предоставлен при проверке ГИТ или прокуратуры. Основной перечень документации включает: журналы регистрации инструктажей (или личные книжки инструктажа), материалы СОУТ (карты, протоколы, перечень мероприятий), документы по оценке рисков, приказы о назначении ответственных лиц, личные карточки учета выдачи СИЗ (в том числе в электронном виде), а также графики и протоколы обучения. Переход на электронный документооборот (ЭДО) в области охраны труда, разрешенный действующим законодательством, существенно упрощает работу распределенных служб ОТ в крупных холдингах.\", \"id\": \"4d4c6fa6-4114-4e86-84ee-bef0b78c9e9e\"}, {\"type\": \"list\", \"content\": \"Положение о СУОТ (актуализированное под требования Приказа № 776н).\\nПеречень профессий и должностей, подлежащих медицинским осмотрам.\\nНормы выдачи СИЗ, разработанные на основе ЕТН.\\nРеестры обученных лиц и протоколы проверки знаний.\\nПланы мероприятий по улучшению условий и охраны труда на текущий год.\", \"id\": \"4a14c7e5-738f-4e43-86bf-e71e1cc9656d\"}, {\"type\": \"heading2\", \"content\": \"Роль руководителя службы в развитии культуры безопасности\", \"id\": \"5a9d0ee8-ce2d-40d4-941d-5b6021ef08d6\"}, {\"type\": \"paragraph\", \"content\": \"Высшим уровнем развития службы охраны труда является переход от надзорных функций к созданию культуры безопасности. Руководитель службы должен выступать лидером перемен, внедряя такие инструменты, как «поведенческий аудит безопасности», системы мотивации работников за соблюдение требований ОТ, конкурсы профессионального мастерства и программы «Vision Zero» (Нулевой травматизм). Это требует от службы ОТ не только знаний законодательства, но и навыков психологии, коммуникации и управления персоналом. Только когда безопасность становится осознанной потребностью каждого работника, а не принуждением со стороны специалиста по ОТ, можно говорить о действительно эффективном построении работы службы.\", \"id\": \"20263197-0f88-49a8-8454-b2d1fc1741a3\"}, {\"type\": \"paragraph\", \"content\": \"В заключение стоит отметить, что структура службы охраны труда должна быть гибкой и вовремя реагировать на изменения в законодательстве и бизнес-процессах компании. Регулярный пересмотр должностных обязанностей сотрудников службы, повышение их квалификации и использование современных технических средств контроля являются залогом успешного функционирования системы сохранения жизни и здоровья работников. Руководитель службы — это прежде всего эксперт-консультант для бизнеса, который помогает минимизировать юридические и финансовые риски предприятия через построение надежной системы охраны труда.\", \"id\": \"02a25185-c81e-4563-9ccd-1badedea91a1\"}]", "8d540f06-58d5-410d-9e91-8eb0bafb6fe3": "[{\"type\": \"heading1\", \"content\": \"Взаимодействие службы охраны труда с другими структурными подразделениями организации\", \"id\": \"fbf8565e-8952-4d4f-9f03-1ac9d5016e39\"}, {\"type\": \"paragraph\", \"content\": \"Эффективное функционирование системы управления охраной труда (СУОТ) невозможно в изоляции одного подразделения. Статус руководителя службы охраны труда предполагает постоянную кросс-функциональную коммуникацию. Согласно профессиональному стандарту, утвержденному Приказом Минтруда РФ №274н, одной из ключевых функций руководителя является координация деятельности подразделений по реализации мер безопасности. Это означает, что служба ОТ выступает методическим центром, который направляет работу других отделов, контролирует соблюдение законодательства и обеспечивает интеграцию требований безопасности в бизнес-процессы. Реализация положений статьи 214 ТК РФ по обеспечению безопасных условий труда требует вовлеченности каждого сотрудника — от рабочего до генерального директора.\", \"id\": \"7aa50cea-a29c-4bc4-8218-39d83f90ccb5\"}, {\"type\": \"heading2\", \"content\": \"Нормативная база и принципы разграничения ответственности\", \"id\": \"0f04c7fc-3be1-4a40-960a-85eeb438820a\"}, {\"type\": \"quote\", \"content\": \"Статья 217 ТК РФ: Система управления охраной труда — комплекс взаимосвязанных и взаимодействующих между собой элементов, устанавливающих политику и цели в области охраны труда у конкретного работодателя и процедуры по достижению этих целей. Работодатель обязан обеспечить создание и функционирование системы управления охраной труда.\", \"id\": \"d6f29067-5b26-486a-8055-770669711126\"}, {\"type\": \"paragraph\", \"content\": \"Для успешного взаимодействия необходимо четкое разграничение ответственности, которое фиксируется в Положении о СУОТ. Основная ошибка многих организаций — попытка переложить всю ответственность за состояние условий труда на службу ОТ. Однако, исходя из требований ГОСТ Р 12.0.007-2009 и положений Х раздела ТК РФ, ответственность за безопасность на конкретных участках несут руководители этих участков. Служба ОТ выполняет контрольно-консультационную роль. Взаимодействие должно строиться на принципе функциональной подчиненности: сотрудники подразделений выполняют указания специалистов по ОТ в части обеспечения безопасности труда.\", \"id\": \"a02405f6-1915-4dba-b1ef-d1e8faa54aad\"}, {\"type\": \"heading2\", \"content\": \"Взаимодействие с отделом кадров (HR-службой)\", \"id\": \"2cf6402f-260b-4796-a86e-cb414ab37418\"}, {\"type\": \"paragraph\", \"content\": \"Связь службы ОТ и отдела кадров начинается с момента приема сотрудника. Основные точки соприкосновения включают формирование списка профессий и должностей, подлежащих обязательным медицинским осмотрам и психиатрическим освидетельствованиям (согласно Приказу Минздрава №29н). Обмен данными должен быть автоматизирован: как только в штатное расписание вносится новая единица, служба ОТ должна провести оценку рисков и определить необходимость обучения. Также совместная работа ведется в части учета рабочего времени во вредных условиях труда для корректного начисления компенсаций, предусмотренных статьей 147 ТК РФ. Отдел кадров предоставляет данные о движении персонала, а служба ОТ — информацию о праве сотрудников на дополнительный отпуск и сокращенный рабочий день на основании результатов СОУТ (ФЗ-426).\", \"id\": \"6660faa5-7b5d-4b77-a3e5-0fd11c86f2c8\"}, {\"type\": \"list\", \"content\": \"Согласование должностных инструкций в части обязанностей по охране труда\\nСовместная подготовка графиков медицинских осмотров\\nКонтроль за соблюдением режимов труда и отдыха\\nОформление кадровых документов при расследовании несчастных случаев\\nИнформирование кандидатов об условиях труда при приеме на работу\", \"id\": \"9dc0b736-ca35-40c6-8cc0-c864613423a6\"}, {\"type\": \"heading2\", \"content\": \"Сотрудничество с техническими службами и главными специалистами\", \"id\": \"921ba1cd-116b-4283-902c-4e4342ba77ce\"}, {\"type\": \"paragraph\", \"content\": \"Взаимодействие с главными инженерами, энергетиками и механиками является критически важным для обеспечения промышленной безопасности и электробезопасности. Служба ОТ взаимодействует с техслужбами при планировании предупредительных ремонтов оборудования (ППР). Согласно Правилам технической эксплуатации электроустановок (ПТЭЭП) и правилам по охране труда при эксплуатации электроустановок, необходимо четкое распределение зон ответственности при допуске подрядных организаций. При закупке нового оборудования служба ОТ должна согласовывать технические задания, проверяя их на соответствие требованиям ТР ТС 010/2011 «О безопасности машин и оборудования». Совместно проводятся технические освидетельствования зданий, сооружений и подъемных механизмов.\", \"id\": \"e8c186a1-6ea9-4cfc-a197-5de8337f7cc7\"}, {\"type\": \"heading2\", \"content\": \"Организация обучения: Взаимодействие с руководителями подразделений\", \"id\": \"7069817e-1b2c-462e-89ee-d1fda217dec4\"}, {\"type\": \"paragraph\", \"content\": \"Согласно Постановлению Правительства РФ №2464, ответственность за проведение инструктажей на рабочем месте и стажировок лежит на непосредственных руководителях работ (мастерах, начальниках цехов). Служба ОТ в данном процессе выполняет роль организатора и контролера. Она разрабатывает программы вводного инструктажа, оказывает методическую помощь в разработке инструкций по охране труда по профессиям и видам работ, а также формирует комиссии по проверке знаний. Важно наладить систему своевременного уведомления руководителей подразделений о необходимости проведения ежегодного обучения и периодической проверки знаний. Без активного участия начальников отделов невозможно реализовать практическое обучение применению СИЗ и оказанию первой помощи, так как именно они знают специфику рисков на конкретном рабочем месте.\", \"id\": \"ebd68e66-e4d7-4683-b9e2-3506c2789bb6\"}, {\"type\": \"list\", \"content\": \"Разработка перечней профессий, освобожденных от первичного инструктажа\\nКонтроль ведения журналов регистрации инструктажей в подразделениях\\nМетодическая поддержка при проведении стажировок\\nОрганизация обучения в учебных центрах для руководителей и специалистов\\nУчастие в комиссиях по проверке знаний требований охраны труда\", \"id\": \"6df6663e-198d-4631-aebd-3fc6d85d36df\"}, {\"type\": \"heading2\", \"content\": \"Взаимодействие с бухгалтерией и финансовым отделом\", \"id\": \"48f9628e-48de-41b5-ba09-86556a6d3b53\"}, {\"type\": \"paragraph\", \"content\": \"Финансирование мероприятий по охране труда регламентировано статьей 225 ТК РФ, которая устанавливает минимальный размер затрат (не менее 0,2% от суммы затрат на производство продукции). Руководитель службы ОТ должен уметь обосновать бюджет перед финансовой службой. Основное взаимодействие касается закупок СИЗ, оплаты медосмотров и обучения. Важным аспектом является работа с Социальным фондом России (СФР) по возмещению затрат на предупредительные меры. Служба ОТ готовит пакет документов (план финансового обеспечения, документы по СОУТ, счета на СИЗ), а бухгалтерия обеспечивает проведение платежей и отражение их в отчетности. От четкости этого взаимодействия зависит возможность вернуть до 20% (в ряде случаев до 30%) страховых взносов, уплаченных в предыдущем году.\", \"id\": \"e01b84ea-ca99-4115-805d-7f2a7401aa95\"}, {\"type\": \"heading2\", \"content\": \"Специфика работы с отделом закупок и МТС\", \"id\": \"9bf1119e-058c-456e-8ef2-68d0a1816bb8\"}, {\"type\": \"paragraph\", \"content\": \"Процесс обеспечения работников средствами индивидуальной защиты (СИЗ) и смывающими средствами с 1 сентября 2023 года перешел на Единые типовые нормы (ЕТН). Служба ОТ формирует нормы выдачи на основе СОУТ и оценки рисков, а отдел закупок осуществляет закупку. Огромное значение имеет входной контроль качества СИЗ. Служба ОТ должна проверять наличие сертификатов соответствия и деклараций, предусмотренных ТР ТС 019/2011. Взаимодействие с отделом материально-технического снабжения также включает вопросы организации хранения СИЗ и своевременной чистки, стирки или ремонта спецодежды. Постоянный мониторинг рынка позволяет службе ОТ рекомендовать закупщикам более современные и эффективные средства защиты, что в долгосрочной перспективе снижает производственный травматизм.\", \"id\": \"29bf5e3c-fcb4-4d01-b1de-1ccda1748f3b\"}, {\"type\": \"heading2\", \"content\": \"Работа с юридическим отделом\", \"id\": \"de654f4f-f7df-4c95-8a38-a7d05f4f014f\"}, {\"type\": \"paragraph\", \"content\": \"Юридическая поддержка необходима службе ОТ при заключении договоров с подрядными организациями. В соответствии с Приказом Минтруда №656н, при производстве работ на одной территории несколькими работодателями необходимо согласовывать мероприятия по предотвращению производственного травматизма. Юристы помогают корректно прописать в договорах условия об ответственности подрядчиков за нарушение правил ОТ. Также совместная работа требуется при подготовке ответов на предписания надзорных органов (Роструда, Роспотребнадзора), при представлении интересов компании в судах по искам работников или при расследовании тяжелых несчастных случаев, когда требуется глубокая правовая оценка обстоятельств происшествия.\", \"id\": \"03b10209-58b8-4d81-8655-773d955e2188\"}, {\"type\": \"heading2\", \"content\": \"Взаимодействие с профсоюзами и уполномоченными по ОТ\", \"id\": \"2ea1411d-b1e3-4a37-b52c-898a0f566195\"}, {\"type\": \"quote\", \"content\": \"Статья 224 ТК РФ: Для обеспечения соблюдения требований охраны труда, осуществления контроля за их выполнением у каждого работодателя, осуществляющего производственную деятельность, численность работников которого превышает 50 человек, создается служба охраны труда или вводится должность специалиста по охране труда.\", \"id\": \"9b1b6352-6644-4921-bc1a-15466189c7b0\"}, {\"type\": \"paragraph\", \"content\": \"Эффективная СУОТ опирается на социальное партнерство. Служба ОТ взаимодействует с Комитетом (комиссией) по охране труда, в который входят представители работодателя и профсоюза на паритетных началах. Уполномоченные лица по охране труда от профсоюзов — это «глаза и уши» службы ОТ на местах. Они помогают выявлять опасные условия труда до того, как они приведут к инциденту. Регулярные совместные проверки и участие профсоюзов в СОУТ повышают доверие коллектива к принимаемым мерам безопасности и способствуют формированию культуры безопасности в организации.\", \"id\": \"70c2331f-d2b3-4fed-a8d5-3ffc4856f887\"}, {\"type\": \"list\", \"content\": \"Рассмотрение предложений работников по улучшению условий труда\\nСовместное проведение ступенчатого контроля за состоянием условий труда\\nСогласование локальных нормативных актов (инструкций, регламентов)\\nУчастие в комиссиях по расследованию несчастных случаев и профзаболеваний\\nПропаганда безопасного труда и проведение конкурсов по охране труда\", \"id\": \"c6dd0f36-f7b0-470f-8be3-28be0c21d1ab\"}, {\"type\": \"heading2\", \"content\": \"Заключение и выводы\", \"id\": \"4f1c7e3d-1654-4f6e-b186-398b20be2e94\"}, {\"type\": \"paragraph\", \"content\": \"Руководитель службы охраны труда выступает в роли «дипломата безопасности», который должен находить баланс между требованиями законодательства и производственными планами предприятия. Успех взаимодействия зависит от прозрачности регламентов, автоматизации документооборота и личного авторитета руководителя службы. Только интегрировав требования ОТ в функционал каждого подразделения, можно достичь «нулевого травматизма» (Vision Zero) — современного стандарта мирового бизнес-сообщества. Постоянный диалог с другими отделами позволяет превратить охрану труда из статьи расходов в эффективный инструмент управления рисками и повышения производительности труда.\", \"id\": \"d81da750-2220-4a89-9951-5ebf91b0a128\"}]", "39064dca-49db-4c84-b8b1-04d2ce8b7691": "[{\"type\": \"heading1\", \"content\": \"Финансирование предупредительных мер по сокращению производственного травматизма через Социальный фонд России (СФР)\", \"id\": \"c2e88a41-1d30-4ec8-a8e9-355d27fc10b1\"}, {\"type\": \"paragraph\", \"content\": \"Эффективное управление охраной труда требует не только методологической подготовки, но и грамотного финансового планирования. Одной из ключевых компетенций руководителя службы охраны труда является умение оптимизировать бюджет компании за счет использования механизмов государственного страхования. В соответствии с Федеральным законом от 24.07.1998 № 125-ФЗ «Об обязательном социальном страховании от несчастных случаев на производстве и профессиональных заболеваний», работодатели имеют право на финансовое обеспечение предупредительных мер за счет сумм страховых взносов. Это означает, что часть уплаченных в Социальный фонд России (СФР) взносов можно вернуть в компанию в виде оплаты конкретных мероприятий по улучшению условий труда.\", \"id\": \"8a6b5a2f-d774-4fe4-9dc3-cedfa39c019d\"}, {\"type\": \"heading2\", \"content\": \"Нормативно-правовая база и объем выделяемых средств\", \"id\": \"9819b0b5-ee52-4156-9f03-6f1f8ef7f44a\"}, {\"type\": \"paragraph\", \"content\": \"Основным документом, регламентирующим процедуру возврата средств, является Приказ Минтруда России от 14.07.2021 № 467н «Об утверждении Правил финансового обеспечения предупредительных мер по сокращению производственного травматизма и профессиональных заболеваний работников и санаторно-курортного лечения работников, занятых на работах с вредными и (или) опасными производственными факторами». Согласно данному акту, работодатель может направить на превентивные меры до 20% от суммы страховых взносов, начисленных за предшествующий календарный год, за вычетом расходов на выплату пособий по временной нетрудоспособности в связи с несчастными случаями. Объем финансирования может быть увеличен до 30%, если дополнительные 10% будут направлены на санаторно-курортное лечение работников предпенсионного возраста (не ранее чем за 5 лет до выхода на пенсию).\", \"id\": \"84a1d718-ad5f-419c-b0d1-265e95951604\"}, {\"type\": \"quote\", \"content\": \"Финансовое обеспечение предупредительных мер осуществляется в пределах бюджетных ассигнований, предусмотренных бюджетом Фонда на текущий финансовый год. Основанием для начала процедуры является подача заявления в территориальный орган СФР по месту регистрации страхователя в срок до 1 августа текущего календарного года.\", \"id\": \"05044ec8-256c-4ef1-a1bf-3ca766cfe3d0\"}, {\"type\": \"heading2\", \"content\": \"Перечень мероприятий, подлежащих компенсации\", \"id\": \"83a94416-5083-4aaa-b484-8e374c4eb3e7\"}, {\"type\": \"paragraph\", \"content\": \"Законодательство строго ограничивает список мер, на которые можно получить финансирование. Руководитель службы охраны труда должен четко понимать, какие статьи расходов подлежат возмещению, чтобы обоснованно составить план финансового обеспечения. Важно учитывать, что все заявленные мероприятия должны быть направлены на достижение конкретных целей: снижение уровня травматизма или профилактику профзаболеваний.\", \"id\": \"c115bd4e-3d62-428a-a206-517261a7c5f3\"}, {\"type\": \"list\", \"content\": \"Проведение специальной оценки условий труда (СОУТ) в соответствии с ФЗ-426.\\nРеализация мероприятий по приведению уровней воздействия вредных факторов на рабочих местах в соответствие с государственными требованиями.\\nОбучение по охране труда определенных категорий работников (включая членов комиссий, руководителей подразделений) в рамках реализации ПП РФ №2464.\\nПриобретение средств индивидуальной защиты (СИЗ), изготовленных на территории государств - членов ЕАЭС.\\nСанаторно-курортное лечение работников, занятых на работах с вредными и опасными условиями труда.\\nПроведение обязательных периодических медицинских осмотров работников.\\nОбеспечение лечебно-профилактическим питанием.\\nПриобретение приборов для определения наличия и концентрации алкоголя в крови (алкотестеров) и приборов для контроля режима труда и отдыха (тахографов).\\nПриобретение аптечек для оказания первой помощи.\", \"id\": \"4b62de98-774f-4975-8363-c997cb5c431a\"}, {\"type\": \"heading2\", \"content\": \"Особенности финансирования СИЗ и обучения\", \"id\": \"77685da8-902c-4b8b-bbd4-d62cdfcba9f1\"}, {\"type\": \"paragraph\", \"content\": \"При планировании закупки СИЗ за счет средств СФР необходимо учитывать требования к происхождению товара. Согласно текущим правилам, возмещению подлежат только те СИЗ, которые имеют подтверждение производства на территории РФ или стран ЕАЭС. Это подтверждается копией заключения Минпромторга России. Что касается обучения, то с вступлением в силу Постановления Правительства РФ № 2464 «О порядке обучения по охране труда и проверки знания требований охраны труда», требования к документации ужесточились. В пакет документов для СФР должны входить программы обучения, приказы о назначении ответственных и договоры с обучающими организациями, имеющими аккредитацию в реестре Минтруда.\", \"id\": \"d3ef2b3b-ff95-4b64-aee5-2f941c5c5a43\"}, {\"type\": \"heading2\", \"content\": \"Алгоритм действий руководителя службы охраны труда\", \"id\": \"303cfac4-05ca-435c-a48b-2900998aba0c\"}, {\"type\": \"paragraph\", \"content\": \"Процесс получения финансирования состоит из нескольких критически важных этапов. Нарушение сроков или некорректное оформление документов ведет к отказу СФР в выделении средств. Руководитель службы охраны труда выступает координатором взаимодействия между бухгалтерией, отделом закупок и фондом.\", \"id\": \"451f5888-c3ef-4380-a772-e4f2326e7b39\"}, {\"type\": \"list\", \"content\": \"Анализ остатка страховых взносов: запрос в бухгалтерию данных об уплаченных взносах за прошлый год.\\nРазработка плана финансового обеспечения: выбор наиболее приоритетных мероприятий из перечня 467н.\\nСбор документации: приказы, копии договоров, расчеты стоимости, копии протоколов СОУТ, медзаключения.\\nПодача заявления в СФР через Госуслуги или лично в срок до 1 августа.\\nПолучение решения от СФР: фонд обязан рассмотреть заявление в срок от 10 до 15 рабочих дней в зависимости от суммы.\\nРеализация мероприятий: компания оплачивает товары и услуги из собственных средств.\\nОтчетность: предоставление ежеквартальных отчетов в СФР и итогового отчета о целевом использовании средств до 15 декабря.\", \"id\": \"4c77cc6e-82eb-408b-b41c-a573f392bf15\"}, {\"type\": \"heading2\", \"content\": \"Разработка плана финансового обеспечения\", \"id\": \"e043e9a9-d985-4fe3-b88e-6d1ce00e0b83\"}, {\"type\": \"paragraph\", \"content\": \"План финансового обеспечения — это ключевой документ, который подписывается руководителем организации и заверяется печатью. В нем указываются наименования мероприятий, сроки их проведения, количественные показатели (например, количество закупаемых респираторов или число работников, направляемых на медосмотр) и планируемые затраты. Важно соотносить этот план с Перечнем мероприятий по улучшению условий и охраны труда, который ежегодно составляется в организации согласно требованиям ТК РФ. Рекомендуется использовать формы документов, предлагаемые региональными отделениями СФР, чтобы избежать формальных отказов.\", \"id\": \"e48a281a-6c5d-4dc5-9528-6a829e63fbb8\"}, {\"type\": \"heading2\", \"content\": \"Причины отказов и способы минимизации рисков\", \"id\": \"232235c5-9487-4e19-b21b-c9003770d684\"}, {\"type\": \"paragraph\", \"content\": \"Наиболее частыми причинами отказа фонда в финансовом обеспечении являются наличие у страхователя задолженности по уплате страховых взносов, пеней или штрафов на день подачи заявления. Также фонд отказывает, если предоставленный пакет документов не является полным или содержит недостоверную информацию. Специалисту по охране труда необходимо заблаговременно (в июне) инициировать сверку с фондом через бухгалтерию, чтобы успеть погасить случайные недоимки.\", \"id\": \"93b8d7e8-590a-4ced-8d85-dc025319c79b\"}, {\"type\": \"quote\", \"content\": \"Статья 17 Федерального закона № 125-ФЗ устанавливает, что страховщик имеет право проверять обоснованность расходования средств. Нецелевое использование сумм влечет за собой их взыскание в полном объеме с начислением пеней.\", \"id\": \"6d1275b4-614f-486d-8e5c-7cf23fd10733\"}, {\"type\": \"heading2\", \"content\": \"Заключение и выгоды для бизнеса\", \"id\": \"d38bd198-9929-41fd-8e18-b191ea603713\"}, {\"type\": \"paragraph\", \"content\": \"Использование механизма возмещения затрат через СФР превращает службу охраны труда из центра затрат в функциональное подразделение, способное эффективно управлять ресурсами. Например, компания с фондом оплаты труда в 100 млн рублей в год (при ставке взносов на травматизм 1%) выплачивает 1 млн рублей взносов. Возврат 200-300 тысяч рублей на медосмотры или СИЗ является существенной экономией бюджета. Профессионализм руководителя службы охраны труда проявляется в умении максимально глубоко интегрировать данные меры в долгосрочную стратегию безопасности предприятия, обеспечивая стабильное снижение профессиональных рисков без дополнительной финансовой нагрузки на собственника бизнеса.\", \"id\": \"4faa954b-8d4e-44a1-814a-f05cb7f104bc\"}, {\"type\": \"paragraph\", \"content\": \"Помните, что с 2024 года требования к электронному документообороту усиливаются, и работа с порталом Госуслуг становится основным каналом взаимодействия. Регулярный мониторинг изменений в Постановлениях Правительства и приказах Минтруда позволит вашей службе охраны труда своевременно актуализировать перечень закупаемого оборудования, например, новых систем страховки при работах на высоте в соответствии с обновленными ГОСТ ССБТ.\", \"id\": \"d4bf5a40-1597-4c30-9a93-4bb9821bb1cc\"}]"};

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
  );

  const results: any = { updated: 0, errors: [] };

  for (const [lessonId, content] of Object.entries(LESSONS)) {
    const { error } = await supabase
      .from("lessons")
      .update({ content })
      .eq("id", lessonId)
      .eq("course_id", COURSE_ID);
    if (error) results.errors.push({ lessonId, error: error.message });
    else results.updated++;
  }

  // marketplace card
  const { error: mErr } = await supabase
    .from("marketplace_courses")
    .update({
      description_short: SHORT_DESC,
      preview_image_url: COVER_URL,
      price_student: 15000,
      price_organization: 12000,
      is_active: true,
      is_validated: true,
    })
    .eq("course_id", COURSE_ID);
  if (mErr) results.errors.push({ scope: "marketplace_courses", error: mErr.message });

  // course
  const { error: cErr } = await supabase
    .from("courses")
    .update({
      description: FULL_DESC,
      cover_image_url: COVER_URL,
      is_published: true,
    })
    .eq("id", COURSE_ID);
  if (cErr) results.errors.push({ scope: "courses", error: cErr.message });

  return new Response(JSON.stringify(results), {
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
});
